#else
#define MV3_STUB_MOVES         // mv3_stubs.c: an empty move table until the generated header is in the tree
#endif
#include "int_phase_spawn.h"   // Interrogation lockbox-phase respawn selection (pure, tested)
#include "skills.h"            // 2013 survival skills (skills.c, included before t2r_tick)
