#include "crashfilter.h"       // when the crash report runs: last chance (top-level filter chained to the game's) instead of every first-chance exception
#include "crashbin.h"          // t2r-crash-<pid>-1.bin written by crash_report (g_cdiag + rings; no CRT / heap / locks in the handler)
