static const char *g_vx_lang_nm;                                   // the voice language's name once vx_lang_tab latched it (exec_beg.c)
static const uint8_t *vx_lang_tab(int which) {                  // 0 male team lines, 1 female team lines, 2 female efforts
    static const char *lang; static int init;
    if (!init) {                                                    // (latched once the engine's language object is filled in)
        uint8_t *g = (uint8_t *)GetModuleHandleW(NULL) + 0x36b56c0;
        if (!IsBadReadPtr(g, 0xce0)) {
            int e = *(int *)(g + 0xcc8);
            for (int i = 0; i < 27; i++) {
                const char *nm = *(const char **)(g + i * 0x68 + 0x38);
                if (*(int *)(g + i * 0x68 + 8) != e || !nm || IsBadReadPtr(nm, 24)) continue;
                init = 1;
                for (int k = 0; k < (int)(sizeof VXA_LANGS / sizeof *VXA_LANGS); k++)
                    if (!_stricmp(nm, VXA_LANGS[k].name)) { lang = (const char *)(uintptr_t)(k + 1); g_vx_lang_nm = VXA_LANGS[k].name; }
                xlog("vox+: voice language enum %d '%.20s' (cats text %d tts %d voice %d tts2 %d)%s", e, nm, *(int *)(g + 0xcc0), *(int *)(g + 0xcc4), e,
                     *(int *)(g + 0xccc), lang ? ": lines without audio in it are skipped" : "");
                break;
            }
        }
    }
    if (!lang) return NULL;
    int k = (int)(uintptr_t)lang - 1;
    return which == 0 ? VXA_LANGS[k].m : which == 1 ? VXA_LANGS[k].f : VXA_LANGS[k].e;
}
