// Multi-reviver (2013 EBOOT revive controller 0x3f3958, re/factions2013/rules/revive.md): every attached reviver i (0 = first to
// attach) adds elapsed_i x rate_i / revive_time_i with rate_i = 1 - min(i x 0.75, 0.5) (1, 0.5, 0.5). Two revive 1.5x as fast, three 2x.
// g_rvt[target][reviver] = when that reviver's hold started (ms, 0 = none) and its revive time (skills change it per reviver).
static struct { uint64_t ms; float secs; } g_rvt[T2R_MAX_PEERS][T2R_MAX_PEERS];
static void rv_refresh(uint32_t tgt) {
    if (tgt > T2R_MAX_PEERS - 1) return;
    uint64_t now = GetTickCount64(), first = 0; float fs = 0;
    for (int r = 0; r < T2R_MAX_PEERS; r++) {
        if (g_rvt[tgt][r].ms && now - g_rvt[tgt][r].ms > (uint64_t)((g_rvt[tgt][r].secs + 4.0f) * 2000)) g_rvt[tgt][r].ms = 0;   // lost "stop"
        if (g_rvt[tgt][r].ms && (!first || g_rvt[tgt][r].ms < first)) { first = g_rvt[tgt][r].ms; fs = g_rvt[tgt][r].secs; }
    }
    if (first) { if (!g_rev_start[tgt]) g_rev_start[tgt] = now; g_rev_start_ms[tgt] = first; g_rev_secs[tgt] = fs; }
    else g_rev_start[tgt] = 0;
}
static int rv_rank(uint32_t tgt, uint32_t rev) {      // 0 = first attached (ties: lower slot), -1 = not reviving
    if (tgt > T2R_MAX_PEERS - 1 || rev > T2R_MAX_PEERS - 1 || !g_rvt[tgt][rev].ms) return -1;
    int k = 0;
    for (uint32_t r = 0; r < T2R_MAX_PEERS; r++)
        if (r != rev && g_rvt[tgt][r].ms && (g_rvt[tgt][r].ms < g_rvt[tgt][rev].ms || (g_rvt[tgt][r].ms == g_rvt[tgt][rev].ms && r < rev))) k++;
    return k;
}
// the 2013 EBOOT rates (1, 0.5, 0.5 = 1.5x / 2x) become 1, 0.6, 0.4: two revivers 1.6x, three 2x, a fourth adds
// nothing (capped at 2x). Everything else of the co-revive was already there: every reviver's hold start + time travels in MSG_UC4_REACH (g_rvt on every client), each client's
// rv_prog adds them (skills: each reviver's own time T, so the Reviver perk stacks multiplicatively with this), the FIRST attached one books the completion (rv_rank 0), a later
// one only if that never comes (600 ms) or the first let go (then it is rank 0 itself). t2r-revive-corate.txt next to the exe: "second third fourth" rates (e.g. "0.5 0.5 0" = 2013).
static FILE *exe_side_open(const char *name, const char *mode);
static float rv_corate(int k) {
    static float r[3] = {0.6f, 0.4f, 0.0f}; static int init;
    if (!init) {
        init = 1; FILE *f = exe_side_open("t2r-revive-corate.txt", "r");
        if (f) { float a, b, c; int n = fscanf(f, "%f %f %f", &a, &b, &c); fclose(f);
                 if (n >= 1 && a >= 0 && a <= 1) r[0] = a; if (n >= 2 && b >= 0 && b <= 1) r[1] = b; if (n >= 3 && c >= 0 && c <= 1) r[2] = c;
                 xlog("revive: co-revive rates %.2f %.2f %.2f (t2r-revive-corate.txt)", r[0], r[1], r[2]); }
    }
    return k <= 0 ? 1.0f : r[k > 3 ? 2 : k - 1];
}
static float rv_prog(uint32_t tgt) {                  // 0..1+ revive progress of target slot tgt from all attached revivers
    if (tgt > T2R_MAX_PEERS - 1) return 0;
    uint64_t now = GetTickCount64(); float p = 0;
    for (uint32_t r = 0; r < T2R_MAX_PEERS; r++) {
        if (!g_rvt[tgt][r].ms) continue;
        int k = rv_rank(tgt, r);
        float rate = rv_corate(k);
        float T = g_rvt[tgt][r].secs > 0.2f ? g_rvt[tgt][r].secs : 5.0f;
        p += (float)(now - g_rvt[tgt][r].ms) / 1000.0f * rate / T;
    }
    return p;
}
static void rv_set(uint32_t tgt, uint32_t rev, int on, float secs, uint64_t ms) {
    if (tgt > T2R_MAX_PEERS - 1 || rev > T2R_MAX_PEERS - 1) return;
    g_rvt[tgt][rev].ms = on ? (ms ? ms : 1) : 0; g_rvt[tgt][rev].secs = secs;
    rv_refresh(tgt);
}
static void rv_clear(uint32_t tgt) { if (tgt < T2R_MAX_PEERS) { memset(g_rvt[tgt], 0, sizeof g_rvt[tgt]); g_rev_start[tgt] = 0; } }
