static int g_s8_dll_n;                          // the slot count N the DLL's descriptor states (v1 = 8); g_engine_peers is that, capped by T2R_MAX_PEERS
static uint8_t *g_s8_ss;                        // the relocated slotState table (dead, respawnGrace, grantCooldown) x 12 bytes (NULL: ctx+0x2bc8, slots 0..3 only)
static void s8_init(void) {                     // find the .t2r8 section (tools/features/slots8.py) and read its table descriptor
    const uint8_t *b = (const uint8_t *)g_winmm;
    uint32_t nt = *(const uint32_t *)(b + 0x3c);
    const uint8_t *fh = b + nt + 4;
    uint16_t ns = *(const uint16_t *)(fh + 2), osz = *(const uint16_t *)(fh + 16);
    const uint8_t *sh = fh + 20 + osz;
    for (int i = 0; i < ns; i++, sh += 40) {
        if (memcmp(sh, ".t2r8\0\0\0", 8)) continue;
        const uint8_t *d = b + *(const uint32_t *)(sh + 12) + 0x40000;      // data area start (after the 0x40000 byte code cave)
        uint32_t dver = *(const uint32_t *)(d + 4);          // 1 = N 8 (original 8-slot patch), 2 = N in +40, protocol in +44, stats rows base in +48 (slots8.py finalize)
        if (*(const uint32_t *)d != 0x38523254u || (dver != 1 && dver != 2)) return;
        g_s8_peers = (uint8_t *)((uintptr_t)g_winmm + (*(const uint64_t *)(d + 8) - 0x180000000ULL));
        g_s8_pa = (uint8_t *)((uintptr_t)g_winmm + (*(const uint64_t *)(d + 16) - 0x180000000ULL));
        { uint64_t ssv = *(const uint64_t *)(d + 32); g_s8_ss = ssv >= 0x180000000ULL ? (uint8_t *)((uintptr_t)g_winmm + (ssv - 0x180000000ULL)) : NULL; }   // descriptor: magic, version, peers, pa, players, slotstate (0 = an older winmm patch without the table: no garbage pointer)
        g_s8_dll_n = dver >= 2 ? (int)*(const uint32_t *)(d + 40) : 8;
        if (dver >= 2) { uint64_t stv = *(const uint64_t *)(d + 48); g_s8_stats = stv >= 0x180000000ULL ? (uint8_t *)((uintptr_t)g_winmm + (stv - 0x180000000ULL)) : NULL; }
        g_engine_peers = g_s8_dll_n < T2R_MAX_PEERS ? g_s8_dll_n : T2R_MAX_PEERS;      // an ext built for fewer slots than the DLL holds treats the extra ones as "no peer"
        return;
    }
}
static uint8_t *t2r_peer(uint32_t slot) {            // winmm net player record (FUN_180050FD0), NULL for a slot the engine does not have
    return slot < T2R_ENGINE_PEERS ? ((uint8_t *(*)(uint32_t))VMA(0x180050FD0))(slot) : NULL;
}
// smoothed real frame time (ms): durations authored in seconds that run on a frame counter (stun...) are converted with it, so a
