static uint64_t base_weapon(uint64_t wid);
static int upgrade_cost(uint64_t wid, int level) {       // level 0 -> price of upgrade I
    wid = base_weapon(wid);
    for (size_t k = 0; k < sizeof UPGRADE_COSTS / sizeof *UPGRADE_COSTS; k++)
        if (fnv64(UPGRADE_COSTS[k].weapon) == wid) return level ? UPGRADE_COSTS[k].c2 : UPGRADE_COSTS[k].c1;
    return level ? 350 : 200;
}
