// ---- new weapon ids (tools/features/weapon_clone.py): "<gun>-supp" = the gun with suppressed
// sounds / model. Everything keyed by gun here (damage, ammo, upgrades, stats) uses the base gun.
static const char *const CLONED_BASE[] = {"rifle-vepr", "rifle-remington-bolt", "pistol-beretta", "pistol-glock", "rifle-mpx5", "rifle-m14-semi",
                                          "pistol-cz75-enforcer", "shotgun-tactical", "rifle-burst", "rifle-frontier"};
#define N_CLONED (sizeof CLONED_BASE / sizeof *CLONED_BASE)
static uint64_t base_weapon(uint64_t wid);
static int base_weapon_is_gun(uint64_t wid) {
    static const char *G[] = {"rifle-vepr", "rifle-remington-bolt", "rifle-mpx5", "rifle-m14-semi", "rifle-burst", "shotgun-remington-pump",
                              "shotgun-baserri-over-under", "shotgun-tactical", "bow-ellie", "crossbow", "pistol-beretta",
                              "pistol-glock", "pistol-revolver-taurus", "pistol-cz75-enforcer", "rifle-galil", "pistol-xcaliber",
                              "pistol-el-diablo", "shotgun-shorty", "rifle-frontier", "rifle-milsniper", "pistol-snubby", ASSAULT_ID, EXPBOW_ID, FLAME_ID, VINTAGE_ID, LAUNCHER_ID};
    uint64_t b = base_weapon(wid);
    for (size_t i = 0; i < sizeof G / sizeof *G; i++) if (fnv64(G[i]) == b) return 1;
    return 0;
}
static uint64_t base_weapon(uint64_t wid) {
    static uint64_t clone[N_CLONED], base[N_CLONED];
    if (!clone[0])
        for (size_t k = 0; k < N_CLONED; k++) {
            char n[64];
            snprintf(n, sizeof n, "%s-supp", CLONED_BASE[k]);
            clone[k] = fnv64(n); base[k] = fnv64(CLONED_BASE[k]);
        }
    for (size_t k = 0; k < N_CLONED; k++) if (clone[k] == wid) return base[k];
    static uint64_t dragon, db;                       // Dragon's Buckshot = the Double Barrel everywhere a table is keyed by the base gun
    if (!dragon) { dragon = fnv64(DRAGON_ID); db = fnv64("shotgun-baserri-over-under"); }
    if (wid == dragon) return db;
    return wid;
}
static int upgrade_row_of(uint64_t wid) {
    wid = base_weapon(wid);
    for (size_t k = 0; k < sizeof UPGRADES / sizeof *UPGRADES; k++)
        if (fnv64(UPGRADES[k].weapon) == wid) return (int)k;
    return -1;
}
static int upgrade_level(uint64_t weapon) {
    // The shop stores the weapon id it saw (the '-supp' clone when the loadout gun is suppressed, which showed 'SUPPRESSED FRONTIER RIFLE UPGRADE I'),
    // the stat tables ask with the base gun: compared raw, a suppressed gun's levels read 0 (no mag / rof / reload / kick / lever change at all). Compare bases.
    uint64_t bw = base_weapon(weapon);
    for (int k = 0; k < g_nupg; k++) if (base_weapon(g_upg[k].weapon) == bw) return g_upg[k].level;
    return 0;
}
static int apply_bundle(uint64_t weapon, const char *bundle) {
    typedef uint64_t (*fn_apply)(void *, uint64_t, uint64_t);
    typedef uint8_t *(*fn_me)(void);
    static fn_apply impl;
    if (!impl) {
        uint8_t *rec = (uint8_t *)((fn_lookup)VMA(0x18000A190))(fnv64("player-weapon-upgrade-apply-bundle"));
        if (!rec || !*(void **)(rec + 0x10)) return 0;
        impl = *(fn_apply *)(rec + 0x10);
    }
    uint8_t *me = ((fn_me)VMA(0x180050390))();
    if (!me) return 0;
    uint64_t r = impl(me, weapon, fnv64(bundle));
    xlog("upgrade: %llx %s -> %llx", (unsigned long long)weapon, bundle, (unsigned long long)r);
    return 1;
}
static void apply_level(uint64_t weapon, int row, int from, int to) {
    for (int lv = from; lv <= to; lv++) {
        const char *const *b = lv == 1 ? UPGRADES[row].l1 : UPGRADES[row].l2;
        for (int j = 0; j < 3 && b[j]; j++) apply_bundle(weapon, b[j]);
    }
}
