static int reload_clip_row(const char *w) {
    for (size_t i = 0; i < sizeof RELOAD_CLIP / sizeof *RELOAD_CLIP; i++) if (!strcmp(RELOAD_CLIP[i].weapon, w)) return (int)i;
    return -1;
}
static void reload_log(const char *w, int lv, float base, float set, const char *how) {
    int r = reload_clip_row(w);
    char t[96] = "clip length unknown";
    if (r >= 0 && RELOAD_CLIP[r].clip > 0) {
        if (RELOAD_CLIP[r].round > 0)
            snprintf(t, sizeof t, "%.2f s start+end + %.2f s per round", RELOAD_CLIP[r].clip / set, RELOAD_CLIP[r].round / set);
        else snprintf(t, sizeof t, "%.2f s (was %.2f s)", RELOAD_CLIP[r].clip / set, base > 0 ? RELOAD_CLIP[r].clip / base : 0.0f);
    }
    xlog("reload 2013: %s level %d def +0x2c base %.2f -> %.2f %s: %s", w, lv, base, set, how, t);
}
static struct { uint8_t *def; uint64_t gun; float reload, chamber; const char *name; } g_rl_bolt[8];   // weapon_reload_rate_tick
static int g_rl_nbolt;
static const float LEVEL_RPM[3] = {1.0f, 1.15f, 1.3f}, LEVEL_KICK[3] = {1.0f, 0.85f, 0.7f};
#define CROUCH_KICK 0.75f      // 2013 *net-crouch-recoil-modifier* (net10.bin): kick x0.75 crouched / prone
#define BURST_SHOT_GAP 0.11f          // 2013 Burst Pistol (net10.bin firearm def +0x000)
