static int finisher_style_of(uint64_t id);
static float onetap_stick_s(uint64_t id);   // upgraded-melee one-tap: seconds into the move where the weapon is in the victim (0 = not a one-tap move)
static float anim_len(uint64_t ent, const char *clip);
static void *alloc_near(uint8_t *base, size_t size);
static void probe_flag_set(uint8_t v);
static void install_probe_flag(void);
static void install_nofade(void);
static void install_radar_fade(void);
