static void install_nan_ray_guard(void); static void install_huge_ray_guard(void);
static void install_probe_guard(void);
static void install_adelta_guard(void);
static uint64_t g_shot_until[T2R_MAX_PEERS];
static uint32_t g_shot_n[T2R_MAX_PEERS];          // unsuppressed shots heard per enemy slot (a new press of the firing byte, or every 400 ms of held auto fire): the music counts each one
static int shot_is_silent(uint64_t wid) {
    return base_weapon(wid) != wid || wid == fnv64("bow-ellie") || wid == fnv64("crossbow") || wid == fnv64(EXPBOW_ID);   // (the release is silent; the blast is not)
}
static int radar_marked_shot(int slot) {       // an unsuppressed shot of this enemy within SHOT_RADAR_MS (listen mode noise too)
    return slot >= 0 && slot < T2R_MAX_PEERS && GetTickCount64() < g_shot_until[slot];
}
static char radar_marked(int slot) {
    typedef char (*fn)(int);
    if (((fn)VMA(0x18001D030))(slot)) return 1;
    return slot >= 0 && slot < T2R_MAX_PEERS && GetTickCount64() < g_shot_until[slot];
}
static void install_shot_radar(void) {
    uint8_t *call = (uint8_t *)VMA(0x1800615FD);
    if (call[0] != 0xE8 || call + 5 + *(int32_t *)(call + 1) != (uint8_t *)VMA(0x18001D030)) {
        hook_fail("shot radar: call site differs, not installed"); return;
    }
    uint8_t *stub = alloc_near((uint8_t *)g_winmm, 0x1000);
    if (!stub) return;
    stub[0] = 0x48; stub[1] = 0xB8; *(uint64_t *)(stub + 2) = (uint64_t)radar_marked;   // mov rax, imm64
    stub[10] = 0xFF; stub[11] = 0xE0;                                                   // jmp rax
    DWORD old;
    VirtualProtect(stub, 0x1000, PAGE_EXECUTE_READ, &old);
    VirtualProtect(call, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(call + 1) = (int32_t)(stub - (call + 5));
    VirtualProtect(call, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), call, 5);
    xlog("shot radar: enemies firing unsuppressed guns show on the radar (%d ms)", SHOT_RADAR_MS);
}
static void feature_shot_radar(void) {
    typedef uint8_t *(*fn_peer)(uint32_t);
    static int installed;
    if (!installed) { installed = 1; install_shot_radar(); }
    if (match_substate() != 6) return;
    static uint8_t was_firing[T2R_MAX_PEERS]; static uint64_t held_n[T2R_MAX_PEERS];
    for (int slot = 0; slot < T2R_MAX_PEERS; slot++) {
        uint8_t *peer = ((fn_peer)t2r_peer)(slot);
        uint8_t firing = peer && peer[4] && !peer[5] && peer[0x89];
        int fresh = firing && !was_firing[slot];
        was_firing[slot] = firing;
        if (!peer || !peer[4] || peer[5] || is_teammate((uint32_t)slot) || !peer[0x89]) continue;
        uint64_t wid = *(uint64_t *)(peer + 0x91);
        if (shot_is_silent(wid)) {      // suppressed / bow: stays off our radar (2013)
            static uint64_t quiet_logged[T2R_MAX_PEERS];
            if (GetTickCount64() >= quiet_logged[slot])
                xlog("supp: slot %d fired suppressed/silent weapon %016llx - off the radar", slot, (unsigned long long)wid);
            quiet_logged[slot] = GetTickCount64() + SHOT_RADAR_MS;
            continue;
        }
        if (GetTickCount64() >= g_shot_until[slot]) xlog("shot radar: slot %d fired (weapon %016llx)", slot, (unsigned long long)wid);
        g_shot_until[slot] = GetTickCount64() + SHOT_RADAR_MS;
        if (fresh || GetTickCount64() >= held_n[slot]) { g_shot_n[slot]++; held_n[slot] = GetTickCount64() + 400; }
    }
}

