static uint64_t g_e_exec_until;            // an E execution of a downed enemy runs (attacker: set at the E press; victim: MSG_EXEC_E 0x49): the downed melee execution path is on for it
#define TACKLE_EXEC_ON (g_tackle_exec || g_t60 < g_e_exec_until)
static uint64_t g_drop_10_until;      // attacker: winmm's msg 0x10 for the replaced kill move is dropped until
static int tackle_ap_victim_start(uint64_t *ret, int argc, uint64_t *argv);
static int tackle_ap_recv(uint32_t slot, const uint8_t *buf, uint64_t len);
static void tackle_ap_attacker_begin(int slot);
static int tackle_ap_vic_slot(void);
static int finpos_place_on(int32_t slot) {   // a downed execution with this slot runs (fix on)
    return !g_no_finpos_fix && g_fp.role && g_fp.place && g_fp.slot == slot && g_t60 < g_fp.until;
}
// No Return chain blocks (interactable "interact-unchain-infected") keep a floating E prompt on
// every map (clickerprompt.png): disable the closest one whenever we're near one.
static void feature_chain_prompts(void) {
    if (match_substate() != 6 || g_frame % 20) return;
    uint64_t a[3]; float r = 8.0f;
    for (int i = 0; i < 3; i++) { a[i] = 0; memcpy(&a[i], &r, 4); }
    uint64_t h = dc_call(fnv64("get-closest-enabled-interactable"), 3, a);
    if (!h || h == ~0ULL) return;
    uint64_t def = dc_call(fnv64("interactable-get-def-id"), 1, &h);
    static uint64_t seen[16]; static int ns;
    int known = 0;
    for (int i = 0; i < ns; i++) if (seen[i] == def) known = 1;
    if (!known && ns < 16) { seen[ns++] = def; xlog("closest interactable def %llx", (unsigned long long)def); }
    if (def == fnv64("interact-unchain-infected")) {
        uint64_t r2 = dc_call(fnv64("interactable-disable"), 1, &h);
        static int n;
        if (LOGCAP(n, 20)) xlog("chain prompt: disabled unchain interactable %llx -> %llx", (unsigned long long)h, (unsigned long long)r2);
    }
}
static const char *g_pup_lie_cur[T2R_MAX_PEERS];             // the UC4 lying / crawl clip that played on a puppet when its down ended in a death (stopped at the ragdoll)
static struct { uint64_t h, at, hold_t60; uint8_t on, stopped, fb, rep; } g_bo_rd[T2R_MAX_PEERS];
// Bodies vanishing on a downed death: our npc-die on a
// downed puppet (killed by a hit while down, the remote bleed-out death, the held shiv kill) makes the body a ragdoll at once, but character-is-dead?
// reads 0 for 1-4 more frames, and winmm's net locator / msg-5 root writes go on until it reads dead (fling_hold, dead_root_slot): the net position
// is written onto a ragdoll. In .. logs 3.1 % of those deaths (247 of 7937+247) ended 15-196 m from the death spot, against 0.7 % of downed
// deaths without our npc-die; 238 of the 247 already sat 10-98 m off on the dead-here frame. From our npc-die on, the body counts as dead for those
// writes (NPCDIE_DEAD_FRAMES at most; the engine reading it dead ends it sooner). t2r-no-npcdie-hold.txt = old.
#define NPCDIE_DEAD_FRAMES 30
static int npcdie_dead(uint32_t slot, uint64_t h) {
    static int off = -1; static uint64_t chk;
    if (slot >= T2R_MAX_PEERS || !h || !g_bo_rd[slot].on || g_bo_rd[slot].h != h || g_frame - g_bo_rd[slot].at > NPCDIE_DEAD_FRAMES) return 0;
    if (off < 0 || g_frame - chk > 300) { chk = g_frame; off = GetFileAttributesA("t2r-no-npcdie-hold.txt") != INVALID_FILE_ATTRIBUTES; }
    return !off;
}   // bleed-out ragdoll hand-over per puppet slot (hold_t60: a death reaction clip plays on the dead body until then - deathreact.c)
// shiv kills (the newer ones did not have the victims follow them, they just ragdoll): winmm's kill of the victim's PUPPET (the victim's
// type 4 -> FUN_1800501d0 -> FUN_18002c7b0, damage 1e6) arrives at the authored kill frame - the stab - and a dead puppet ragdolls. The 2013 stealth
// shiv kills stab at 0.31 / 0.58 s of a 3.5 / 3.7 s victim half (the DLC insta-shiv at 1.30 / 1.45 s of 2.0 s, which is why only the old ones looked
// right): the body went limp at the stab and its buckle / knees / fall never played on the attacker's (or a bystander's) screen. The victim's own
// client still dies at the kill frame (its body keeps the half, death anims withheld); on the other screens the puppet kill is HELD until the half is
// over (recv_hit_hook, psync_kill_defer_slot in paired.c) and done then with no death anim (exkill_tick: npc-die no-anim + the ragdoll hand-over
// from the half's final pose, bleed_rd_tick). Logs "shiv kill:".
static struct { int on, slot; uint64_t h, ms; uint8_t *proc; } g_exk;
static int psync_kill_defer_slot(void);
static void psync_vic_throat_set(int on);
static float psync_phase(uint64_t ent, uint64_t sid);
static uint64_t g_gore_flag_frame[T2R_MAX_PEERS];            // gore_note_hit: frame of the last lethal gore flag per puppet (logged at their death)
static uint64_t anim_end_blend(uint64_t obj, const char *anim, float secs);
// a body shot on a downed enemy ragdolled ~1.2 s late (headshot at once). finisher_target_rules() passes the cannot-die threshold as the INTEGER 1
// (= a denormal float ~1e-45: "health never drops to 0"), and the native takes an hp FLOAT: threshold 0 was still "cannot drop below 0 hp" and npc-die
// (Die = maxhp damage) left the puppet alive for the 4 retries (log: "still alive - threshold 0 + npc-die again ... character-is-dead? 0") until the
// victim's net death ~70 frames later. The guard is only off below zero: threshold -1.0f (+ full invincibility off), then the health set to 0 on retries.
static uint64_t g_lk_until[T2R_MAX_PEERS];        // R-DK: our own kill of a DOWNED puppet (shot dead while down): hp / blast guards stay off it until the net confirms (or this tick)
static uint64_t g_pbg_until[T2R_MAX_PEERS];       // blast / low-hp guard: the puppet's cannot-die threshold is on until this tick (puppet_blast_guard_tick)
static void puppet_guard_off(uint64_t h) {
    union { float f; uint32_t u; } m1 = {-1.0f};
    uint64_t th[2] = {h, m1.u};
    dc_call(fnv64("character-set-invincibility-cannot-die-threshold"), 2, th);
    uint64_t inv[3] = {h, 0, 0};
    dc_call(fnv64("character-set-invincibility"), 3, inv);
}
static void bleed_rd_tick(void) {
    // a teammate who bled out stayed frozen in the downed pose on the other screen, then vanished. The puppet's lying /
    // crawl clip (script animate_ on layer 2) was never stopped when the down ended in a death (the overlay left it "until the
    // ragdoll"), and a scripted clip on the dead NPC holds the body in its pose (npc-die with the no-death-anim arg starts no
    // death reaction either). Hand-over like our own body (dd_limp_tick): right after npc-die the clip layer is cleared with no
    // blend (the blend stood the puppet up in its NPC pose), and the ragdoll bit is checked / logged.
    typedef uint8_t *(*fn_peer)(uint32_t);
    typedef void *(*fn_proc)(uint64_t);
    for (uint32_t sl = 0; sl < T2R_MAX_PEERS; sl++) {
        if (!g_bo_rd[sl].on) continue;
        uint8_t *peer = ((fn_peer)t2r_peer)(sl);
        uint64_t h = peer ? *(uint64_t *)(peer + 0x60) : 0;
        if (!h || h != g_bo_rd[sl].h) { g_bo_rd[sl].on = 0; continue; }
        uint64_t el = g_frame - g_bo_rd[sl].at;
        uint8_t *proc = ((fn_proc)VMA(0x18000A200))(h);
        int bit = proc && !IsBadReadPtr(proc + 0x9fd, 1) ? (proc[0x9fd] & 1) : -1;
        if (g_bo_rd[sl].hold_t60) {     // deathreact.c: a directional death clip plays on the dead body - the hand-over (clip layer cleared, ragdoll) starts when it is over
            if (g_t60 < g_bo_rd[sl].hold_t60) continue;
            g_bo_rd[sl].hold_t60 = 0; g_bo_rd[sl].at = g_frame ? g_frame : 1; el = 0;
            xlog("deathreact: slot %u puppet %llx clip over - hand-over to the ragdoll (ragdoll bit %d)", sl, (unsigned long long)h, bit);
        }
        if (el >= 2 && !g_bo_rd[sl].stopped) {
            g_bo_rd[sl].stopped = 1;
            uint64_t a[5] = {h, 2, 0, 0, 0};        // blend 0, anim 0 = whatever plays on the layer
            uint64_t r = dc_call(fnv64("stop-animating"), 5, a);
            if (g_pup_lie_cur[sl]) { anim_end_blend(h, g_pup_lie_cur[sl], 0.0f); g_pup_lie_cur[sl] = NULL; }
            anim_end_blend(h, g_down_loop, 0.0f);
            xlog("bleed-out: slot %u puppet %llx +%llu frames: lying clip layer cleared (-> %llx), ragdoll bit %d", sl, (unsigned long long)h,
                 (unsigned long long)el, (unsigned long long)r, bit);
        }
        if (el >= 1 && el <= 40 && g_bo_rd[sl].rep < 4) {   // still alive after npc-die (threshold / hp re-apply): lift the guard, kill again
            uint64_t p2 = h, d2 = dc_call(0xe93f704f02a9ecd5ULL /* character-is-dead? */, 1, &p2);
            int dead2 = d2 != ~0ULL && (d2 & 0xff);
            if (!dead2 && !(el % 3)) {
                g_bo_rd[sl].rep++;
                puppet_guard_off(h);
                { union { float f; uint32_t u; } z = {0.0f}; uint64_t hp0[2] = {h, z.u}; dc_call(0xcac2cb5a30fccf12ULL /* set-object-health */, 2, hp0); }
                uint64_t a[5] = {h, 0, 0, 1, 1};
                uint64_t r = dc_call(fnv64("npc-die"), 5, a);
                p2 = h; d2 = dc_call(0xe93f704f02a9ecd5ULL, 1, &p2);
                xlog("bleed-out: slot %u puppet %llx +%llu frames still alive - threshold -1.0f + hp 0 + npc-die again (%u) -> %llx, character-is-dead? %d", sl, (unsigned long long)h,
                     (unsigned long long)el, (unsigned)g_bo_rd[sl].rep, (unsigned long long)r, (int)(d2 != ~0ULL && (d2 & 0xff)));
            } else if (dead2) g_bo_rd[sl].rep = 99;
        }
        if (el == 10 && bit != 1 && !g_bo_rd[sl].fb) {
            g_bo_rd[sl].fb = 1;
            uint64_t a[3] = {h, 0, 0};
            uint64_t r = dc_call(fnv64("character-allow-dead-ragdoll-snap-back-to-animation"), 2, a);   // 0 = the corpse is not pulled back to a clip
            xlog("bleed-out: slot %u puppet %llx ragdoll bit still %d at +10 frames - snap-back off -> %llx", sl, (unsigned long long)h, bit, (unsigned long long)r);
        }
        if (el == 30 || el == 120) xlog("bleed-out: slot %u puppet %llx +%llu frames: ragdoll bit %d%s", sl, (unsigned long long)h, (unsigned long long)el, bit, bit == 1 ? " (limp)" : " (NOT limp)");
        if (el >= 120) g_bo_rd[sl].on = 0;
    }
}
static void feature_remote_deaths(void) {
    typedef uint8_t *(*fn_peer)(uint32_t);
    bleed_rd_tick();
    static uint64_t dead_since[T2R_MAX_PEERS], done[T2R_MAX_PEERS];
    static uint8_t exec_death[T2R_MAX_PEERS], down_latch[T2R_MAX_PEERS];
    if (match_substate() != 6) { memset(dead_since, 0, sizeof dead_since); memset(done, 0, sizeof done); memset(exec_death, 0, sizeof exec_death); memset(down_latch, 0, sizeof down_latch); return; }
    uint32_t me = *(uint32_t *)VMA(0x180138090);
    for (uint32_t slot = 0; slot < T2R_MAX_PEERS; slot++) {
        uint8_t *peer = slot != me ? ((fn_peer)t2r_peer)(slot) : NULL;
        uint64_t h = peer ? *(uint64_t *)(peer + 0x60) : 0;
        {   // trace (log 'remote death: trace'): the peer flags the kill decision reads, on every change
            static uint32_t tr[T2R_MAX_PEERS]; static int ntr;
            uint32_t now_s = (h ? 1u : 0u) | (peer && peer[4] ? 2u : 0u) | (peer && peer[5] ? 4u : 0u);
            if (peer && tr[slot] != now_s && ntr++ < 80) { xlog("remote death: trace slot %u puppet %llx peer[4] %u peer[5] %u (downed %u, dead here %u)", slot, (unsigned long long)h, peer[4], peer[5], g_peer_downed[slot], g_puppet_dead_here[slot]); }
            if (peer) tr[slot] = now_s;
        }
        // peer[4] is not required: if winmm clears it with the death flag the bleed-out puppet was never killed here (frozen in its
        // downed pose until the respawn replaced it); the body only has to still exist (the process lookup)
        if (h && peer[5] && !peer[4]) {
            typedef void *(*fn_proc4)(uint64_t);
            if (!((fn_proc4)VMA(0x18000A200))(h)) h = 0;
        }
        if (!h || (!peer[4] && !peer[5]) || !peer[5]) { dead_since[slot] = 0; done[slot] = 0; exec_death[slot] = 0; down_latch[slot] = 0; continue; }
        if (!dead_since[slot]) { dead_since[slot] = g_t60; down_latch[slot] = g_peer_downed[slot] || (g_down_end[slot] && g_t60 - g_down_end[slot] < 240); }
        {   // (log 'remote death: skipped' - why a net-dead puppet was not killed here, once per reason and body)
            static uint64_t sk_h[T2R_MAX_PEERS]; static int sk_r[T2R_MAX_PEERS];
            int why = done[slot] == h ? 1 : g_puppet_dead_here[slot] ? 2 : (g_t60 - dead_since[slot] < 15 && !psync_vic_kill_passed((uint32_t)slot)) ? 3 :
                      (g_finisher_frame && g_t60 - g_finisher_frame < 300) ? 4 : gx_busy_slot((uint32_t)slot) ? 5 : 0;
            if (why > 1 && (sk_h[slot] != h || sk_r[slot] != why)) {
                sk_h[slot] = h; sk_r[slot] = why;
                xlog("remote death: slot %u puppet %llx net-dead but skipped (%s; downed %u, down end %llu frames ago, finisher %llu frames ago)", slot, (unsigned long long)h,
                     why == 2 ? "already dead here" : why == 3 ? "first 15 frames" : why == 4 ? "our finisher plays" : "our E execution plays",
                     g_peer_downed[slot], g_down_end[slot] ? (unsigned long long)(g_t60 - g_down_end[slot]) : 0ULL, g_finisher_frame ? (unsigned long long)(g_t60 - g_finisher_frame) : 0ULL);
            }
        }
        if (done[slot] == h || g_puppet_dead_here[slot] || (g_t60 - dead_since[slot] < 15 && !psync_vic_kill_passed((uint32_t)slot))) continue;
        // our finisher on them is still playing: the paired animation kills them itself (an npc-die
        // now flung them into a ragdoll mid-tackle)
        // (a downed victim shot in the head after a takedown stayed up headless ~1.2 s - this waited 60 frames: a death from the
        // downed state with no paired move on the body has nothing else to kill it, so it dies at once)
        if (g_finisher_frame && g_t60 - g_finisher_frame < 300 && !(down_latch[slot] && !psync_busy_slot((uint32_t)slot))) continue;
        // an E execution (psync) still plays its victim half on this puppet: the body keeps the authored pose to the clip's end
        // and only then goes limp; an npc-die now cut the clip. Latched: the death came from the execution.
        // their death lands ON the kill frame (their client authored it then; kill time passed here too): npc-die with the
        // no-anim arg below, psync keeps their half playing to its end (psync_keep_victim). Before the kill time: deferred.
        if (psync_kill_defer_slot() == (int)slot || (g_exk.on && g_exk.slot == (int)slot) || dr_burn_defer_active((int)slot)) { exec_death[slot] = 1; continue; }   // shiv kill: dies at the end of its half (exkill_tick)
        if (gx_busy_slot((uint32_t)slot)) {
            exec_death[slot] = 1;
            if (!psync_vic_kill_passed((uint32_t)slot)) continue;
            psync_keep_victim("remote death");
        }
        // died while downed / right after the down ended (bleed-out, executed from the crawl): no death animation,
        // the puppet goes limp from its lying pose (npc-die arg 3 = 1 skips the death-anim setup, exe 0x140634daa;
        // a bled-out puppet played the standing neck-shot death)
        int from_down = down_latch[slot] || exec_death[slot] || g_peer_downed[slot] || (g_down_end[slot] && g_t60 - g_down_end[slot] < 240);
        // (deathreact.c): a downed player shot dead / a standing player killed by the Military Sniper plays TLOU2's own directional death clip
        // for the shot's side on the body (the victim announced it, or our own last hit on them says it); the body dies with no death anim of its own
        // and the ragdoll hand-over waits for the clip's end (bleed_rd_tick hold). Every other death: unchanged.
        uint64_t dr_hold = 0;
        int dr_on = dr_puppet_begin(slot, h, from_down, exec_death[slot], &dr_hold);
        if (dr_on || g_pbg_until[slot]) puppet_guard_off(h);      // the molotov pre-start / blast guard threshold must not keep the puppet alive under the clip - the victim's machine says it is dead
        g_pbg_until[slot] = 0;                                   // (the blast / low-hp guard: released here, the net death is the real one)
        uint64_t a[5] = {h, 0, 0, (uint64_t)(from_down || dr_on), 1};
        uint64_t r = dc_call(fnv64("npc-die"), 5, a);
        hs_arm(h, 0, 90);
        if (dr_on) {
            xlog("remote death: slot %u died with a death reaction clip (%s) - no death anim of its own, ragdoll after the clip", slot, from_down ? "downed shot" : "sniper kill");
            g_bo_rd[slot].h = h; g_bo_rd[slot].at = g_frame ? g_frame : 1; g_bo_rd[slot].on = 1; g_bo_rd[slot].stopped = 0; g_bo_rd[slot].fb = 0; g_bo_rd[slot].rep = 0;
            g_bo_rd[slot].hold_t60 = dr_hold;
        } else if (from_down) {
            xlog("remote death: slot %u died from the downed state - ragdoll, no death anim", slot);
            g_bo_rd[slot].h = h; g_bo_rd[slot].at = g_frame ? g_frame : 1; g_bo_rd[slot].on = 1; g_bo_rd[slot].stopped = 0; g_bo_rd[slot].fb = 0; g_bo_rd[slot].rep = 0;
            xlog("bleed-out: slot %u puppet %llx dead on their screen (down ended %llu frames ago): npc-die no-anim -> %llx, ragdoll hand-over follows", slot,
                 (unsigned long long)h, g_down_end[slot] ? (unsigned long long)(g_t60 - g_down_end[slot]) : 0ULL, (unsigned long long)r);
        }
        {   // (gore: did our last gun hit on them get the lethal gore pick? - tells a missed prediction from a missing gore asset)
            static int ng;
            if (LOGCAP(ng, 60))
                xlog("gore: slot %u died on their screen; lethal gore pick last flagged %s (frame %llu, now %llu)", slot,
                     g_gore_flag_frame[slot] ? "yes" : "never", (unsigned long long)g_gore_flag_frame[slot], (unsigned long long)g_frame);
        }
        done[slot] = h;
        static int n;
        if (LOGCAP(n, 40)) xlog("remote death: slot %u%s dead on their screen, puppet killed here (npc-die -> %llx)", slot,
                           is_teammate(slot) ? " (teammate)" : "", (unsigned long long)r);
    }
}

// ---------------------------------------------------------------- held weapon orientation (Abby guns)
// Abby's guns (Vepr, Glock, double barrel) are held canted by our Ellie-based MP bodies, own and
// puppets (abbyweapon/wrong.png vs correct.png). The gun is a process attached to the hand
// (exe 0x1CD2140 attach(weapon, file, line, func, &owner{handle, instance}, attach point, offset
// xform{pos4, quat4}) - spec's AttachWeaponToCorrectHand). The character's held weapon: vtable
// +0xD38. World transform of a process: exe+0x133db30(proc+0x100, out) -> {pos4, quat4}.
static uint8_t *player_weapon(uint8_t *player) {      // spec GetPlayerWeaponId: player+0x2F60 -> exe 0xBDC1F0
    typedef uint8_t *(*fn_w)(void *);
    if (!player || IsBadReadPtr(player + 0x2F60, 8)) return NULL;
    uint8_t *v3 = *(uint8_t **)(player + 0x2F60);
    if (!v3 || IsBadReadPtr(v3, 8)) return NULL;
    return ((fn_w)((uint8_t *)GetModuleHandleW(NULL) + 0xBDC1F0))(v3);
}
static uint8_t *held_weapon(uint8_t *chr) {
    typedef uint8_t *(*fn_w)(void *);
    if (!chr || IsBadReadPtr(chr, 8)) return NULL;
    void **vt = *(void ***)chr;
    if (!vt || IsBadReadPtr(vt + 0xD38 / 8, 8) || !is_code(vt[0xD38 / 8])) return NULL;
    return ((fn_w)vt[0xD38 / 8])(chr);
}
static int proc_world(uint8_t *proc, float out[8]) {
    typedef const float *(*fn_loc)(void *, float *);
    if (!proc || IsBadReadPtr(proc + 0x100, 0x50)) return 0;
    float b[16];
    const float *l = ((fn_loc)((uint8_t *)GetModuleHandleW(NULL) + 0x133db30))(proc + 0x100, b);
    if (!l) return 0;
    memcpy(out, l, 32);
    return 1;
}
static void qrotv(const float *q, const float *v, float *o) {     // o = q * v * q^-1 (q = x y z w)
    float x = q[0], y = q[1], z = q[2], w = q[3];
    float tx = 2 * (y * v[2] - z * v[1]), ty = 2 * (z * v[0] - x * v[2]), tz = 2 * (x * v[1] - y * v[0]);
    o[0] = v[0] + w * tx + (y * tz - z * ty);
    o[1] = v[1] + w * ty + (z * tx - x * tz);
    o[2] = v[2] + w * tz + (x * ty - y * tx);
}
// dev: log the held gun's barrel (+z) / up (+y) against the camera, own character (every 0.5 s)
static void feature_weapon_pose_diag(void) {
    typedef uint8_t *(*fn_me)(void);
#ifdef T2R_RELEASE
    return;
#endif
    if (match_substate() != 6 || (g_frame % 30)) return;
    uint8_t *me = ((fn_me)VMA(0x180050390))();
    uint8_t *w = player_weapon(me);
    float t[8];
    if (!w || !proc_world(w, t)) {
        static int n;
        if (!(n++ % 4)) xlog("wpose: no weapon (player %p, weapon %p)", (void *)me, (void *)w);
        return;
    }
    uint64_t none = 0;
    uint64_t rd = dc_call(fnv64("camera-get-dir-through-reticle"), 0, &none);
    float cd[3] = {0, 0, 1};
    if (rd && rd != ~0ULL && !IsBadReadPtr((void *)rd, 12)) memcpy(cd, (void *)rd, 12);
    const float zf[3] = {0, 0, 1}, yu[3] = {0, 1, 0}, xr[3] = {1, 0, 0};
    float f[3], u[3], r[3];
    qrotv(t + 4, zf, f); qrotv(t + 4, yu, u); qrotv(t + 4, xr, r);
    uint64_t aim = dc_call(fnv64("player-is-aiming?"), 0, &none);
    xlog("wpose: weapon %llx aim %d fwd %.2f %.2f %.2f up %.2f %.2f %.2f right %.2f %.2f %.2f cam %.2f %.2f %.2f q %.3f %.3f %.3f %.3f",
         (unsigned long long)current_weapon(), (int)(aim != ~0ULL && (aim & 0xff)), f[0], f[1], f[2], u[0], u[1], u[2], r[0], r[1], r[2],
         cd[0], cd[1], cd[2], t[4], t[5], t[6], t[7]);
    {   // (shoulder swap, lowered pose): the gun origin in the camera's own axes (right / up / forward of the reticle ray, metres from the camera
        // locator) + the DC swap state: a swapped aim with the gun low or on the wrong side of the screen shows as up << 0 / right of the unswapped aim.
        uint64_t cam = dc_call(0x42413e1c037969a8ULL /* camera-through-reticle-locator */, 0, &none);
        uint64_t cp = cam && cam != ~0ULL ? dc_call(fnv64("get-locator-position"), 1, &cam) : 0;
        if (cp && cp != ~0ULL && !IsBadReadPtr((void *)cp, 12)) {
            const float *c = (const float *)cp;
            float d[3] = {t[0] - c[0], t[1] - c[1], t[2] - c[2]};
            float cr[3] = {cd[1] * 0 - cd[2] * 1, cd[2] * 0 - cd[0] * 0, cd[0] * 1 - cd[1] * 0};      // fwd x worldUp
            float cl = __builtin_sqrtf(cr[0] * cr[0] + cr[1] * cr[1] + cr[2] * cr[2]);
            if (cl > 1e-3f) {
                for (int i = 0; i < 3; i++) cr[i] /= cl;
                float cu[3] = {cr[1] * cd[2] - cr[2] * cd[1], cr[2] * cd[0] - cr[0] * cd[2], cr[0] * cd[1] - cr[1] * cd[0]};   // perpendicular to both
                if (cu[1] < 0) { cu[0] = -cu[0]; cu[1] = -cu[1]; cu[2] = -cu[2]; }                                              // up = the side world +Y is on
                xlog("wpose: gun origin from the camera: right %.2f up %.2f fwd %.2f m",
                     d[0] * cr[0] + d[1] * cr[1] + d[2] * cr[2], d[0] * cu[0] + d[1] * cu[1] + d[2] * cu[2], d[0] * cd[0] + d[1] * cd[1] + d[2] * cd[2]);
            }
        }
    }
}

// ---------------------------------------------------------------- visible armour
// Twelve Weeks' armour meshes (actor mp-ellie-helmet-lvl-1 / mp-ellie-torso-armored-lvl-1, loaded
// with every MP level by pak68.txt) worn while a player has armour: ours (g_armor) and every
// puppet whose MSG_ARMOR says so. The game's gas-mask recipe (anim-gas-mask-impl): spawn-object(
// art, SimpleAttachable, 0, 0, 1, 0, 0, 0, 0), attach(obj, character, attach point, 0.0);
// kill-entity removes it. Re-made when the character changes (respawn, new puppet).
static int g_armor_variant = -1;     // probe override of the tint variant (-1: read t2r-armor-palette.txt)
static int g_armor_rewear;           // probe: strip + re-make our own armour meshes
static FILE *exe_side_open(const char *name, const char *mode) {
    // perf: read opens of opt-in / opt-out files that do not exist are polled from per-frame code; "not there" is remembered for
    // 2 s per name (same poll rate as ov_off), so a failed fopen (a file-system call) is not repeated every frame
    // "not there" is now the shared fa_poll cache (answered from memory, re-checked by a background thread: no file-system call on the
    // tick); the exe folder is looked up once
    int rd = mode[0] == 'r' && !strchr(mode, '+');
    static char dir[MAX_PATH]; static int dirn;
    if (!dirn) { char d[MAX_PATH]; GetModuleFileNameA(NULL, d, MAX_PATH); char *s = strrchr(d, 92); if (!s) return NULL; s[1] = 0; strcpy(dir, d); dirn = (int)strlen(dir); }
    char pth[MAX_PATH];
    if ((size_t)dirn + strlen(name) >= MAX_PATH) return NULL;
    strcpy(pth, dir); strcpy(pth + dirn, name);
    if (rd && fa_poll(pth) == INVALID_FILE_ATTRIBUTES) return NULL;
    FILE *f = fopen(pth, mode);
    if (!rd) fa_forget(pth);   // we write it: the next read must see it
    return f;
}
// 2013 rules alignment (re/factions2013/rules/*.md): every behaviour changed to match the PS3 data has an off switch,
// t2r-2013-<area>-off.txt next to the exe (checked every 2 s) -> the older behaviour comes back.
enum { R13_DOWNED, R13_REVIVE, R13_EXEC, R13_SHIV, R13_EXPLO, R13_MELEE, R13_SCORE, R13_SPAWN, R13_N };
static int r13_off(int a) {
    static const char *const nm[R13_N] = {"downed", "revive", "exec", "shiv", "explosives", "melee", "scoring", "spawns"};
    static int v[R13_N]; static uint64_t at[R13_N]; static char init[R13_N];
    uint64_t now = GetTickCount64();
    if (!init[a] || now - at[a] > 2000) {
        char fn[64]; snprintf(fn, sizeof fn, "t2r-2013-%s-off.txt", nm[a]);
        FILE *f = exe_side_open(fn, "r"); int o = f != NULL; if (f) fclose(f);
        if (init[a] && o != v[a]) xlog("2013 rules: %s %s (%s)", nm[a], o ? "OFF" : "on", fn);
        else if (!init[a]) xlog("2013 rules: %s %s", nm[a], o ? "OFF (switch file present)" : "on");
        v[a] = o; at[a] = now; init[a] = 1;
    }
    return v[a];
}
// Tint attempt for the flat-blue armour meshes: the MP armour actors are tinted by a
// look2-tint-palette channel ("torso-1", white) - mp-ellie-NN-palette in look2/palettes.bin - which a
// bare SimpleAttachable never gets. apply-look-palette's argument list is unknown, so variants:
// 1 (obj,pal) 2 (obj,pal,0) 3 (chr,pal) 4 (chr,pal,0) 5 (obj,pal,1) 6 (chr,pal,1) 7 (obj,pal,chr).
// Runtime switch t2r-armor-palette.txt: "<variant> [palette name]" (0 / no file = off). Probe: t2r-armorprobe.txt.
static void armor_tint(uint64_t obj, uint64_t chr, int variant, uint64_t pal) {
    if (variant <= 0 || !obj) return;
    uint64_t a[3];
    int argc = 3;
    switch (variant) {
    case 1: a[0] = obj; a[1] = pal; argc = 2; break;
    case 2: a[0] = obj; a[1] = pal; a[2] = 0; break;
    case 3: a[0] = chr; a[1] = pal; argc = 2; break;
    case 4: a[0] = chr; a[1] = pal; a[2] = 0; break;
    case 5: a[0] = obj; a[1] = pal; a[2] = 1; break;
    case 6: a[0] = chr; a[1] = pal; a[2] = 1; break;
    case 7: a[0] = obj; a[1] = pal; a[2] = chr; break;
    default: return;
    }
    uint64_t r = dc_call(fnv64("apply-look-palette"), argc, a);
    xlog("armour tint: variant %d obj %llx chr %llx pal %llx -> %llx", variant, (unsigned long long)obj,
         (unsigned long long)chr, (unsigned long long)pal, (unsigned long long)r);
}
static void armor_wear(uint64_t chr, int hero, uint64_t obj[2]) {
    // grey renamed copies of mp-ellie-helmet-lvl-1 / mp-ellie-torso-armored-lvl-1 (navy police gear,
    // colour baked in the material; tools/models/armour_paks.py, re/armour-colour.md)
    static const char *ART[2] = {"mp-t2r-helmet-grey-01", "mp-t2r-torso-armored-grey-01"};
    // attach POINTS (attach-points.bin), not joint names: targHeadB = headb, targChest = spined, both
    // identity offsets in the player and npc-common sets. "head"/"spined" were joint names and put the
    // (then model-space) armour ~1.2 m off the wearer; the paks now hold the meshes in those joints'
    // bind space (armour_paks.to_joint_space), so they follow head / chest animation.
    static const char *AP[2] = {"targHeadB", "targChest"};
    int variant = g_armor_variant;
    char palname[64] = "mp-ellie-01-palette";
    if (variant < 0) {
        variant = 0;
        FILE *tf = exe_side_open("t2r-armor-palette.txt", "r");
        if (tf) {
            char nm[64];
            int v = 0, n = fscanf(tf, "%d %63s", &v, nm);
            fclose(tf);
            if (n >= 1) variant = v;
            if (n >= 2) strcpy(palname, nm);
        }
    }
    for (int k = 0; k < 2; k++) {
        uint64_t a[9] = {fnv64(ART[k]), fnv64("SimpleAttachable"), 0, 0, 1, 0, 0, 0, 0};
        uint64_t o = dc_call(fnv64("spawn-object"), 9, a);
        obj[k] = (o && o != ~0ULL) ? o : 0;
        if (!obj[k]) continue;
        if (hero) { uint64_t h[2] = {obj[k], 1}; dc_call(fnv64("set-instance-flag-hero"), 2, h); }
        uint64_t at[4] = {obj[k], chr, fnv64(AP[k]), 0};
        uint64_t ar = dc_call(fnv64("attach"), 4, at);
        xlog("armour: attach(%s, %llx, %s) -> %llx", ART[k], (unsigned long long)chr, AP[k], (unsigned long long)ar);
        armor_tint(obj[k], chr, variant, fnv64(palname));
    }
}
static void armor_strip(uint64_t obj[2]) {
    for (int k = 0; k < 2; k++) if (obj[k]) { dc_call(fnv64("kill-entity"), 1, &obj[k]); obj[k] = 0; }
}
// the rigid pieces for a mask (bit 0 helmet, bit 1 vest): a broken piece is killed on its own; a piece
// that is wanted again (bought again: a bit new in the mask) or nothing is on re-makes both, the
// unwanted one killed again (a failed spawn is not retried until then). 1 = (re)made.
static int armor_rigid_mask(uint64_t chr, int hero, uint64_t obj[2], int mask, int *had) {
    int made = 0;
    if ((!obj[0] && !obj[1]) || (mask & ~*had)) { armor_strip(obj); armor_wear(chr, hero, obj); made = 1; }
    *had = mask;
    for (int k = 0; k < 2; k++)
        if (!((mask >> k) & 1) && obj[k]) { dc_call(fnv64("kill-entity"), 1, &obj[k]); obj[k] = 0; }
    return made;
}
// ---------------------------------------------------------------- skinned armour (re/armor-rig.md, re/armor-rattler.md)
// The helmet / vest as LOOK PARTS instead of rigid attachments. The build adds an armoured twin
// "<look>-t2r-arm" of every faction pool look (dc_data_patches.ARMOUR_LOOK_*: the base look's parts +
// the Rattler helmet slaver-male-helmet-02 (game look part) + the Rattler plate carrier slaver-vest-04-torso
// (tools/models/armour_rattler.py: slaver-male-04's torso with everything but the vest collapsed), both
// hidden at spawn; real NPC parts on base-male-skel, weighted and textured by ND). Every player spawns with the twin
// of its look: the own / puppet spawn hooks swap the look string for the spawn call only (the network
// keeps the base name), on our screen and on everyone else's. The two parts are then shown / hidden
// with set-mesh-visible(character, mesh, bool) as the armour comes and goes (ours g_armor, puppets
// MSG_ARMOR); while the helmet shows, the parts it clashes with (Seraphite hood up, WLF hats) are
