    if (lsh_off()) xlog("lshoulder: suppressed gun tilt off (t2r-no-lshoulder-supp.txt); the wrap stays for the swap hammer fix");
    if (s[0] != 0xE8 || s + 5 + *(int32_t *)(s + 1) != exe + BP_RVA_ATTACH) { hook_fail("lshoulder: shoulder-swap attach call (exe+babf2b) differs - not hooked"); return; }
    uint8_t *stub = alloc_near(s, 32);
    if (!stub) { hook_fail("lshoulder: no stub memory"); return; }
    DWORD old;
    stub[0] = 0x48; stub[1] = 0xB8; *(uint64_t *)(stub + 2) = (uint64_t)(uintptr_t)lsh_attach_hook; stub[10] = 0xFF; stub[11] = 0xE0;
    VirtualProtect(stub, 32, PAGE_EXECUTE_READ, &old);
    VirtualProtect(s, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(s + 1) = (int32_t)(stub - (s + 5));
    VirtualProtect(s, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), s, 5);
    xlog("lshoulder: shoulder-swap attach wrapped (exe+babf2b); suppressed long guns tilt on the left hand attach (t2r-lshoulder-supp.txt: id pitch yaw pivotz)");
