    static const uint8_t expect[30] = {0x48, 0x8b, 0xbc, 0x24, 0x68, 0x02, 0x00, 0x00, 0x48, 0x8b, 0xb4, 0x24,
        0x60, 0x02, 0x00, 0x00, 0x4c, 0x39, 0xbc, 0x24, 0x98, 0x01, 0x00, 0x00, 0x0f, 0x84, 0x07, 0x02, 0x00, 0x00};
    if (memcmp(f, expect, 30)) { hook_miss(f, 30, "backpack prop: exe build differs, not installed"); return; }
    bp_tables();
