    memcpy(p, f, 16); p += 16;                                    // the two movs (rdi / rsi restored)
    static const uint8_t pre[] = {0x49, 0x8b, 0x8e, 0x18, 0x01, 0x00, 0x00,          // mov rcx, [r14+118h] (player)
                                  0x48, 0x8b, 0x94, 0x24, 0x98, 0x01, 0x00, 0x00,    // mov rdx, [rsp+198h] (art)
                                  0x4d, 0x89, 0xf0,                                  // mov r8, r14 (controller)
                                  0x48, 0x83, 0xec, 0x20};                           // sub rsp, 20h
