    *p++ = 0xff; *p++ = 0x25; *(uint32_t *)p = 0; p += 4; *(uint64_t *)p = (uint64_t)(f + 30 + 0x207); p += 8;  // -> skip
    *p++ = 0xff; *p++ = 0x25; *(uint32_t *)p = 0; p += 4; *(uint64_t *)p = (uint64_t)(f + 30); p += 8;          // -> spawn
