static int bfx_defer(uint32_t slot, uint64_t ent, uint64_t w, int knife, int lethal) {
    static uint64_t at; static int off;
    uint64_t now = GetTickCount64();
    if (!at || now - at >= 2000) { at = now ? now : 1; off = GetFileAttributesA("t2r-blade-fx-local.txt") != INVALID_FILE_ATTRIBUTES; }
    if (off || slot >= T2R_MAX_PEERS || !ent) return 0;
    g_bfx_pend.slot = slot; g_bfx_pend.ent = ent; g_bfx_pend.w = w; g_bfx_pend.knife = knife; g_bfx_pend.lethal = lethal; g_bfx_pend.ms = now ? now : 1;
    return 1;
}
static void bfx_confirm(uint32_t slot) {       // melee_hitreact.c mhr_recv: slot's blow landed
    if (!g_bfx_pend.ms || g_bfx_pend.slot != slot) return;
    uint64_t now = GetTickCount64();
    if (now - g_bfx_pend.ms < 900 && puppet_handle(slot) == g_bfx_pend.ent) {      // (not on a respawned / swapped body)
        if (g_bfx_pend.knife) knife_hit_native(g_bfx_pend.ent, g_bfx_pend.lethal); else melee_hit_fx(g_bfx_pend.ent, g_bfx_pend.w);
        static int nl; if (LOGCAP(nl, 40)) xlog("blade fx: slot %u confirmed our %s blow - cut played %llu ms after the contact", slot, g_bfx_pend.knife ? "knife" : "melee", (unsigned long long)(now - g_bfx_pend.ms));
    }
    g_bfx_pend.ms = 0;
}
