static int xb_stuck_now(void) { uint64_t none = 0, r = dc_call(fnv64("player-is-arrow-stuck?"), 0, &none); return r != ~0ULL && (r & 0xff); }
// spawn-stuck-arrow does NOT return the arrow: exe 0x140428960 writes the new ProjectileArrow's +0xc0 into the result, and after the joint
// attach (0x14119b1b0) that field is the parent bound frame - the same pointer get-joint-locator returns for that joint (the log showed both equal on
// every call). That pointer was used as "the arrow handle": OnArrowStuck got a random object, the visibility fix wrote into random objects, kill-entity
// never removed the prop. The real arrow is the one the native registered as stuck in that body: get-arrow-stuck-in-character / -in-player.
static int g_xfa_quiet;       // xbs_bolt asks the registry every frame while it waits for the arrow: no log lines then
static uint64_t xb_find_arrow(uint64_t ent, uint64_t spawn_ret) {
    typedef void *(*fn_proc)(uint64_t);
    static const char *const N[] = {"get-arrow-stuck-in-character", "get-arrow-stuck-in-player"};
    uint64_t found = 0;
    {   // the spawn result first: a pointer to the script result box holding the arrow's +0xc0 (read before any other native reuses the box)
        uint64_t in0 = spawn_ret && spawn_ret != ~0ULL && !IsBadReadPtr((void *)(uintptr_t)spawn_ret, 16) ? *(uint64_t *)(uintptr_t)spawn_ret : 0;
        uint64_t in1 = in0 ? *(uint64_t *)(uintptr_t)(spawn_ret + 8) : 0;
        uint8_t *o0 = in0 && in0 != ~0ULL ? ((fn_proc)VMA(0x18000A200))(in0) : NULL;
        uint64_t c0 = o0 && !IsBadReadPtr(o0 + 0xc0, 8) ? *(uint64_t *)(o0 + 0xc0) : 0;
        if (!g_xfa_quiet) xlog("crossbow: spawn result box %llx holds %llx %llx -> object %p (+0xc0 %llx)", (unsigned long long)spawn_ret, (unsigned long long)in0, (unsigned long long)in1, (void *)o0, (unsigned long long)c0);
        if (o0 && c0 == in0) return in0;
    }
    for (int i = 0; i < 2 && !found; i++) {
        if (i == 1 && ent != SID_PLAYER) break;
        uint64_t a[2] = {ent, 0};
        uint64_t r = dc_call(fnv64(N[i]), i == 1 ? 0 : 1, a);      // get-arrow-stuck-in-player() takes no args (break-arrow-stuck-in-player script)
        uint8_t *o = r && r != ~0ULL ? ((fn_proc)VMA(0x18000A200))(r) : NULL;
        uint64_t inner = r && r != ~0ULL && !IsBadReadPtr((void *)(uintptr_t)r, 8) ? *(uint64_t *)(uintptr_t)r : 0;
        uint8_t *oi = inner && inner != ~0ULL ? ((fn_proc)VMA(0x18000A200))(inner) : NULL;
        if (!g_xfa_quiet) xlog("crossbow: %s(%llx) -> %llx (object %p; boxed %llx -> object %p); spawn result was %llx", N[i], (unsigned long long)ent, (unsigned long long)r, (void *)o,
             (unsigned long long)inner, (void *)oi, (unsigned long long)spawn_ret);
        if (o && !IsBadReadPtr(o, 0x200)) found = r;
        else if (oi && !IsBadReadPtr(oi, 0x200)) found = inner;
    }
    return found;
}
static uint64_t xb_joint_pick(uint64_t ent, int right, const char *why) {     // the arrow attach joint when the body has it, else the plain shoulder
    static const char *const R[] = {"r_shoulder_arrow_attach", "r_shoulder"}, *const L[] = {"l_shoulder_arrow_attach", "l_shoulder"};
    const char *const *c = right ? R : L;
    for (int i = 0; i < 2; i++) {
        uint64_t ja[2] = {ent, fnv64(c[i])};
        uint64_t loc = dc_call(0x6b8812bd30c5cd5dULL /* get-joint-locator */, 2, ja);
        if (loc && loc != ~0ULL) { xlog("crossbow: %s joint %s found (locator %llx)", why, c[i], (unsigned long long)loc); return fnv64(c[i]); }
        xlog("crossbow: %s joint %s not on the body (locator %llx)", why, c[i], (unsigned long long)loc);
    }
    return fnv64(c[1]);
}
static uint8_t *xb_ability(uint8_t **vt_out) {   // the player's arrow controller (player+0x3218), only when its vtable is the one decompiled
    typedef uint8_t *(*fn_pl)(void);
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    uint8_t *pl = ((fn_pl)(exe + 0xdabea0))();
    if (!pl || IsBadReadPtr(pl + 0x3218, 8)) return NULL;
    uint8_t *ab = *(uint8_t **)(pl + 0x3218);
    if (!ab || IsBadReadPtr(ab, 0x200)) return NULL;
    uint8_t *vt = *(uint8_t **)ab;
    if (!vt || IsBadReadPtr(vt + 0x178, 0x40)) return NULL;
    if (*(uint8_t **)(vt + 0x178) != exe + 0xaf4a30 || *(uint8_t **)(vt + 0x198) != exe + 0xaf69d0 || *(uint8_t **)(vt + 0x1b0) != exe + 0xaf4b70) {
        static int nl; if (LOGCAP(nl, 3)) xlog("crossbow: player+0x3218 controller vtable is not the arrow controller (+0x178 %p +0x198 %p +0x1b0 %p) - engine stick skipped",
                                         *(void **)(vt + 0x178), *(void **)(vt + 0x198), *(void **)(vt + 0x1b0));
        return NULL;
    }
    if (vt_out) *vt_out = vt;
    return ab;
}
