// 2013 has no traversal invulnerability. TLOU2's scripted
// squeeze-through (player-squeeze-through) is a scripted move; the engine turns character invincibility on our body for it (hits reach the engine and
// are swallowed, nothing logs). The ONLY invincibility we ever set on our own body is the intro guard and the friendly-fire pipe-bomb shield
// (set_invincible; g_ff_me_inv), so any other one in a running match - while we are alive, not in an execution / paired move - is the engine's
// and is cleared: at once before a hit reaches the engine (recv_hit_hook) and from the friendly-fire tick every 6 frames for the rest of the squeeze.
static void set_invincible(uint64_t who, int on);
static int g_ff_me_inv;                  // feature_friendly_fire: its pipe-bomb shield on our body is on
static int g_ff_ended;                   // the match is over (ctx+0x2ca4): teammates stay protected through the end banner / scoreboard
static int g_ig_inv_clears;
static int own_inv_clear(const char *why) {
    // the EXECUTIONER half of an execution (psync_exec_att_own) is cleared too - 2013 has no scripted invulnerability, the executioner is a normal hittable body
    // (the paired move's engine invincibility swallowed every hit: "executioner takes no damage"); the victim half / a bystander pair keep the old skip
    int xatt = psync_exec_att_own() || (g_ctx_third_hit_ms && GetTickCount64() - g_ctx_third_hit_ms < 400);   // (a third player's hit just broke our pair - it lands)
    if (match_substate() != 6 || g_intro_guard || g_ff_me_inv || g_ff_ended || g_downed || g_down_dying || g_exec_until || (!xatt && (psync_active() || gx_running())) || local_hp() <= 0.0f) return 0;
    uint64_t a = SID_PLAYER, g = dc_call(fnv64("character-get-invincibility"), 1, &a);
    if (!(g & 0xff)) return 0;
    if (xatt) xlog("exec: engine invincibility (raw %llx) found on the EXECUTIONER (us) during our execution (%s) - cleared, the executioner stays hittable", (unsigned long long)g, why);
    set_invincible(SID_PLAYER, 0);
    uint64_t a2 = SID_PLAYER, g2 = dc_call(fnv64("character-get-invincibility"), 1, &a2);
    if (LOGCAP(g_ig_inv_clears, 40)) xlog("engine invincibility on our body (%s, raw %llx) cleared -> %llx: a squeeze-through / scripted move must not make us immune (2013 has no traversal invulnerability)",
                                          why, (unsigned long long)g, (unsigned long long)g2);
    return 1;
}
