    // here with the engine's NPC melee damage (fist 20) for every weapon - dmg_probe's rescale never ran on this path (a lead-pipe
    // hit 20, no 'melee dmg:' line). Rescale by the attacker's weapon class before any rule below sees it (fists keep 20).
    // v5-dmg: a value that already is one of the class's table values (plain or upgraded: the attacker's melee_dmg_now / duel / pin blow) is kept - only a
    // raw engine value (the NPC fist 20 under a 1h blade / 2h id, a 15 fallback under a weapon id) is rescaled to the class's plain damage
    { int bk = bb_melee_kind(w, dmg); if (bk >= 0) bb_melee_note(T2R_US, bk); }   // bloodbuild: a melee blow on us - where its wound goes (victim's screen)
    if (dmg > 0 && dmg <= 25.0f && w && dmg != DC_COUNTER_DMG) {   // (the dodge counter's 20 is authored, see DC_COUNTER_DMG)
        const char *mnm = "?", *mwhy = "";
        int mcls = melee_class_of(w, &mnm);
        if (mcls >= 0 && melee_dmg_valid(mcls, dmg)) mcls = -1;
        if (mcls >= 0) {
            float nd = melee_dmg_2013(mcls, &mwhy);
            static int nm;
            if (LOGCAP(nm, 40)) xlog("melee dmg: %s hit %.0f -> %.0f on us (2013: %s)", mnm, dmg, nd, mwhy);
            dmg = nd;
        }
    }
    if (dmg > 0 && dmg < 100000.0f && g_last_hit_slot < T2R_MAX_PEERS) g_hit_by_ms[g_last_hit_slot] = GetTickCount64();   // shiv lockout (shiv_enemy_tick)
    if (dmg > 0 && dmg < 100000.0f && !(g_last_hit_slot < T2R_MAX_PEERS && is_teammate(g_last_hit_slot))) g_rv_hit_frame = g_frame ? g_frame : 1;   // (2013: damage interrupts a revive)
    if (dmg > 0 && dmg < 100000.0f) { alertsting_combat("shot / hit out of the quiet"); music_event(3.0f, "we took a hit"); g_mus_hit_rx_ms = GetTickCount64(); }
