            float s = r13_expl_mul(g_last_hit_slot, 0);
            float nd = d < NAIL_KILL13 * s ? 200.0f : d <= NAIL_R1_13 * s ? 84.0f : d <= NAIL_R2_13 * s ? 35.0f : 0.0f;
            xlog("nail bomb: slot %u burst %.2f m from us (ring scale %.1f) -> %.0f damage (relay sent %.1f)", g_last_hit_slot, d, s, nd, dmg);
            if (nd > 0) { g_burst_q_dmg = nd; burst_queue(3, g_last_hit_slot, bp, pl); }
