            // directional death clip for the shot's side before the ragdoll (deathreact.c); every other downed death is unchanged
            if (dmg < 100000.0f && w && base_weapon_is_gun(base_weapon(w)) && !psync_active() && !gx_victim_active() && !g_exec_until)
                dr_own_begin(flame_is_gun(w) ? 3 /* DR_FLAME: burning death, prone clips */ : 1 /* DR_DOWNED */, w, g_last_hit_slot, dmg, 1);
            if (dmg < 100000.0f && w && base_weapon_is_gun(base_weapon(w)) && !psync_active() && !gx_victim_active() && !g_exec_until) own_gore_kill(w, g_last_hit_slot, 0);
            g_down_dying = 1;
            downed_set(0);
            own_death_no_anim("executed by a hit while downed");
            uint64_t rk = hit_tramp(me, att, w, ammo, 250.0f, flag);
