            uint64_t rp = hp > 1.0f ? g_recv_hit_tramp(me, att, w, ammo, hp - 1.0f, flag) : 0;
            g_down_hit.me = me; g_down_hit.att = att; g_down_hit.w = w; g_down_hit.ammo = ammo; g_down_hit.flag = flag;
