    // (bodyshield.c: a held player turned into a shield takes its own team's hits - friendly fire is temporarily enabled for that victim)
    if ((uint8_t)type == 3 && (uint8_t)slot < T2R_MAX_PEERS && !g_ff_off && !dev_hit && is_teammate((uint8_t)slot) && !bs_ff_allow((uint8_t)slot)) {
        static int nff; if (LOGCAP(nff, 40)) xlog("friendly fire: damage message from teammate slot %u dropped", (unsigned)(uint8_t)slot);
        return 0;
    }
    if ((uint8_t)type == 3 && (uint8_t)slot < T2R_MAX_PEERS && buf && len >= 0x14) bs_on_hit((uint8_t)slot, *(const float *)(buf + 0x10));   // bodyshield.c: a hit on the shielder lets the victim go
    if ((uint8_t)type == 3) {      // ctx shield: during a contextual takedown of ours only the move's other half may hurt us
        int ca, cv, cr = psync_ctx_window(&ca, &cv);
        if (cr == 1 || cr == 2) {
            int partner = cr == 1 ? cv : ca;
            if ((uint8_t)slot == partner) g_ctx_partner_hit_frame = (uint32_t)g_frame;
            else if (!ctx_shield_old() && (uint8_t)slot < T2R_MAX_PEERS) {      // a third player's hit lands on either half and breaks the pair (both screens: psync ABORT)
                xlog("pair: damage message from third player slot %u during our %s half (pair slots %d / %d) - the pair is broken, the hit lands", (unsigned)(uint8_t)slot, cr == 1 ? "attacker" : "victim", ca, cv);
                g_ctx_third_hit_ms = GetTickCount64();
                psync_abort("hit by a third player", 1);      // (a running duel ends in recv_hit_hook: mdu_note_hit's third-player rule)
                if (cr == 2) cd_victim_cancel("our victim half was cut by a third player's hit");      // the pending down of the cut pin would down us standing 4 s later
            } else if (cr == 1 && psync_exec_att_own()) {      // the ATTACKER of a takedown is hittable (a third player's hit frees the victim: recv_hit_hook breaks the move); the victim keeps the shield
                static int nah; if (LOGCAP(nah, 40)) xlog("ctx shield: damage message from slot %u passes - we are the attacker of the takedown (hit breaks it)", (unsigned)(uint8_t)slot);
            } else { static int ncs; if (LOGCAP(ncs, 60)) xlog("ctx shield: damage message from slot %u dropped (our contextual takedown with slot %d runs)", (unsigned)(uint8_t)slot, partner); return 0; }
        }
    }
