            if (tg_ok && tg == me) { float mb[16]; const float *ml = player_locator(mb); if (ml && pt_v3_ok(ml, 1e6f)) { tp[0] = ml[0]; tp[1] = ml[1]; tp[2] = ml[2]; ht = 1; } }
            else if (tg_ok) ht = pt_peer_pos(tg, tp);
