    // want'). ss-hud2-dodge-reminder-prompt create-dodge-reminder calls gui2-show-attachable-widget/f(canvas.hudRoot, widget,
    // npc, 0, 0, -1, 0.20, *dodge-reminder-right-attach-params*): joint 0 (the character's origin), no offset vector, and the
    // placement is all in the attach params (gui2-game.bin: offset vector at +0x18 = (-0.6, 1.1, 1, 1) for 'right', +0.6 for
    // 'left'), i.e. 1.1 up and 0.6 to the side of the body, not on it. Same call here with our widget (it has the glyph + the
    // textAction label the dodge widget lacks).
    uint64_t out = 0;
    ((fn_show)(exe + 0x1e90ad0))(&out, fnv64("canvas.hudRoot"), "hud-interactable/world-space-button", obj, 0,
                                 NULL, -1, 0.20f, fnv64("*dodge-reminder-right-attach-params*"));
    if (!out || out == ~0ULL) {
        if (LOGCAP(nlog, 5)) xlog("world prompt: widget did not come up from %s (%llx) - text fallback", where, (unsigned long long)out);
        return;
    }
    g_wp_done_frame = g_frame; g_wp_ok_frame = g_frame;
    { static int dimmed; dui_dim_attachable(out, &dimmed); }     // death ui: fades with the black
