                        if (af) { int c; while ((c = fgetc(af)) != EOF) if (c >= '1' && c <= '9') m |= 1 << (c - '0'); fclose(af); }
                        else m = 1 << 1;      // default = 1 (ground-IK layer held at 1 %): setting 1 fixed the arm bug
