                    float dx = lp[0] - g_uc4_ov_px, dz = lp[2] - g_uc4_ov_pz, dd = __builtin_sqrtf(dx * dx + dz * dz);
                    if (dd > 0.08f) g_uc4_ov_held_at = g_frame, g_uc4_ov_px = lp[0], g_uc4_ov_pz = lp[2];
