        xlog("dmelee: strike segment %.2f-%.2f s (contact %.2f), flinch segment %.2f-%.2f s", g_dm_seg[0], g_dm_seg[2], g_dm_seg[1], g_dm_seg[3], g_dm_seg[4]);
