        press_edge = pr && !lastp && !e_blk; lastp = pr;
        e_blk_frame = e_blk;
        if (g_pg_hold_f && g_frame <= g_pg_hold_f) {      // an E execution / shiv owns this press (its path gate may still be reading rays): never a ground attack, never to the engine
            static int nhl; uint64_t none_h = 0;
            dc_call(0x0fa21391e0e4e478ULL /* player-disable-melee */, 0, &none_h);
            if (press_edge && nhl++ < 30) xlog("path gate: the press stays with the E handler (held until frame %llu) - downed-melee ground attack and the engine's melee held off", (unsigned long long)g_pg_hold_f);
            was = now; return;
        }
