static int g_fem_knife_off;        // t2r-no-female-knife.txt (feature_weapon_skeleton re-reads it)
static uint64_t g_fem_knife_spawn;   // g_spawned_frame of the life the knife unarmed weapon was given / equipped for (give_hook / female_knife_item)
