        if (fem && fem_exec_body()) { uint64_t z0 = 0; hk = dc_call(fnv64("get-player-weapon-id"), 0, &z0); exec_body = !g_fem_knife_cur || hk != g_fem_knife_cur; }
        {   static int last_eb;
            if (exec_body != last_eb && own_knife()) {
                last_eb = exec_body;
                xlog("female: 2013 paired half %s (psync role %d, unarmed exec %d, held %llx, +0x608 %u)", exec_body ? "begins - knife IsEllie / Ellie skeleton held off, the body answers as a male one" : "over - knife rules back",
                     psync_role(), g_unarm_exec, (unsigned long long)hk, me[0x608]);
            }
        }
        int now = !koff && own_knife() && !g_downed && !exec_body && g_fem_knife_mode && g_fem_knife_spawn == g_spawned_frame && (cw == 0 || cw == ~0ULL || (g_fem_knife_cur && cw == g_fem_knife_cur) || (cw == fnv64("abby-unarmed") && !g_unarm_exec));   // (fists id = the engine's fallback when a picked-up melee weapon breaks / is dropped: the knife is still selected)
        if (now != g_fem_knife_now) { g_fem_knife_now = now; xlog("female: knife %s", now ? "IsEllie half on (player+0x608 = 1 while the hands are empty; the other half is the switchblade best-melee item)" : "IsEllie half away (a weapon / downed / other body)"); }
        weapon_switch_watch();
