    static const char *const W2[] = {"rifle-vepr", "rifle-m14-semi", "rifle-burst", "rifle-galil", "pistol-revolver-taurus", "rifle-frontier"};
    static const char *const W8[] = {"rifle-remington-bolt", "rifle-milsniper", VINTAGE_ID, "pistol-el-diablo", "pistol-xcaliber", "rifle-mini-14", "rifle-tommy"};
    static const char *const W4[] = {"shotgun-remington-pump", "shotgun-baserri-over-under", "shotgun-tactical", "shotgun-shorty"};
