    case 4: cn = "weapon class shotgun (4)"; wn = "shotgun-remington-pump"; eff = knee ? "gore-shotgun-loleg/upleg (knee)" : "gore-gun-head-frontexit-center-big / gore-gun-head-eliminated / gore-shotgun-head-graze-*"; break;
