        xcam_start(h, (g_gx.until - g_t60 - 60) / 60.0f, gx_melee_side(h, 2), -1, kill_s, 2, mx_by_move(move) >= 0 ? MELEE2013[mx_by_move(move)].name : "melee-finisher");   // victim framing camera
