static uint8_t *g_large_tab;
static uint8_t *weapon_row(int slot, uint32_t i);
static const char *ammo_of_gun(const char *gun);
static void b13_fill_begin(uint64_t box, int from_open);      // supplybox.c
static void b13_fill_end(uint64_t box);
static void b13_slot_count(uint64_t box);
static int b13_take(uint64_t *item, uint64_t *count, int *kind);
static void b13_after_open(uint64_t *box, int was_opened);
static const char *b13_name(uint64_t item);
typedef void (*fn_boxfill)(uint64_t);
static fn_boxfill g_boxfill_tramp;
// Box open sound (wishlist: the box opened silently). The box fill FUN_18004ce10 is called by the
// open path FUN_18004ee40 (player at the box, call at 0x18004ef5e) and by the initial spawn
// (FUN_18004e200); only the first one gets the No Return loot crate open sounds (sfx-t2r-igc-loot-
// crate-open-latch then -lid, defined in aud-sfx2 as sfx-info), played on the player (play-sound-at-
// joint, as the F3 sound probe does). Log: 'supply box open sound: <name> -> <ret>'. t2r-no-boxsound.txt
// next to the exe: off. If the log shows ret ffff...: the sound's bank is not loaded in MP.
static void nrbox_after_open(void);
static int nrbox_open_start(uint64_t box);
static void box_open_sound(void) {
    static const char *const SFX[] = {"sfx-t2r-igc-loot-crate-open-latch", "sfx-t2r-igc-loot-crate-open-lid", "sfx-t2r-igc-loot-crate-open-hinge"};   // hinge: the third event of the NR clip (re/nr-supply-box.md)
    static int off = -1;
    if (off < 0) {
        char path[MAX_PATH];
        GetModuleFileNameA(NULL, path, MAX_PATH);
        char *sl = strrchr(path, 92);
        if (sl) strcpy(sl + 1, "t2r-no-boxsound.txt");
        off = GetFileAttributesA(path) != INVALID_FILE_ATTRIBUTES;
    }
    if (off) return;
    nrbox_after_open();
    for (int i = 0; i < 3; i++) {
        uint64_t a[5] = {fnv64(SFX[i]), SID_PLAYER, fnv64("spined"), 0, 0};
        uint64_t r = dc_call(fnv64("play-sound-at-joint"), 5, a);
        static int n;
        if (LOGCAP(n, 8)) xlog("supply box open sound: %s -> %llx", SFX[i], (unsigned long long)r);
    }
}
static void boxfill_hook(uint64_t box) {
    uint8_t *ra = (uint8_t *)__builtin_return_address(0);
    int from_open = ra >= (uint8_t *)VMA(0x18004EE40) && ra < (uint8_t *)VMA(0x18004F000);
    if (InterlockedCompareExchange(&g_box_cs_init, 1, 0) == 0) { InitializeCriticalSection(&g_box_cs); InterlockedExchange(&g_box_cs_init, 2); }
    while (g_box_cs_init != 2) Sleep(0);
    EnterCriticalSection(&g_box_cs);
    b13_fill_begin(box, from_open);
    b13_slot_count(box);
    g_box_fill_tid = GetCurrentThreadId();
    nrbox_fill_begin((uint8_t *)box);
    g_box_filling = 1;
    if (from_open && match_substate() == 6 && !nrbox_open_start(box)) box_open_sound();
    g_boxfill_tramp(box);
    g_box_filling = 0; g_box_fill_tid = 0;
    b13_fill_end(box);
    LeaveCriticalSection(&g_box_cs);
}

static void install_boxfill_hook(void) {
    uint8_t *f = (uint8_t *)VMA(0x18004CE10);
    static const uint8_t expect[17] = {0x55, 0x41, 0x57, 0x41, 0x56, 0x41, 0x55, 0x41, 0x54,
                                       0x56, 0x57, 0x53, 0xB8, 0x48, 0x2A, 0x00, 0x00};
    if (memcmp(f, expect, 17)) { hook_miss(f, 17, "boxfill hook: prologue mismatch, not installed"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 17);
    t[17] = 0xFF; t[18] = 0x25; *(uint32_t *)(t + 19) = 0;
    *(uint64_t *)(t + 23) = (uint64_t)(f + 17);
    g_boxfill_tramp = (fn_boxfill)t;
    DWORD old; VirtualProtect(f, 17, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0;
    *(uint64_t *)(f + 6) = (uint64_t)boxfill_hook;
    memset(f + 14, 0x90, 3);
    VirtualProtect(f, 17, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 17);
    xlog("boxfill hook installed (crafting plan per box)");
}
// A DOWNED player could OPEN SUPPLY BOXES. winmm's per-frame box check FUN_18004df20 reads the "interact"
// button itself (DC var, not a joypad command: joypad-disable-all-commands-except doesn't stop it) and opens the nearest
// box through FUN_18004ee40 (its only call: 0x18004e0ca). That call goes through box_open_gate: no open while downed.
static void box_open_gate(uint64_t *box) {
    if (g_downed || !actor_can_act()) {      // downed / dead (spectating) / inside a paired move: no box
        static uint64_t last;
        if (g_frame - last > 120) { last = g_frame; xlog("supply box: open blocked - we are %s", g_downed ? "downed" : "not able to act"); }
        return;
    }
    if (bo_defer(box)) return;               // supplybox.c: reach first, the real open runs at the hand contact (bod_open)
    int was = *((uint8_t *)box + 0x14);
    ((void (*)(uint64_t *))VMA(0x18004EE40))(box);
    b13_after_open(box, was);               // supplybox.c: 2013 refill time
}
static void install_box_open_gate(void) {
    uint8_t *call = (uint8_t *)VMA(0x18004E0CA);
    if (call[0] != 0xE8 || call + 5 + *(int32_t *)(call + 1) != (uint8_t *)VMA(0x18004EE40)) {
        hook_fail("box open gate: call site differs, not installed"); return;
    }
    uint8_t *stub = alloc_near((uint8_t *)g_winmm, 64);
    if (!stub) { hook_fail("box open gate: no stub memory"); return; }
    stub[0] = 0x48; stub[1] = 0xB8; *(uint64_t *)(stub + 2) = (uint64_t)box_open_gate;   // mov rax, imm64
    stub[10] = 0xFF; stub[11] = 0xE0;                                                    // jmp rax
    DWORD old;
    VirtualProtect(stub, 64, PAGE_EXECUTE_READ, &old);
    VirtualProtect(call, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(call + 1) = (int32_t)(stub - (call + 5));
    VirtualProtect(call, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), call, 5);
    xlog("box open gate installed (no supply box while downed)");
}
