    g_relg_last = (uint8_t *volatile *)(c + 0x1008);
    uint64_t rng[3][2];
    HMODULE mods[3] = {(HMODULE)exe, (HMODULE)&__ImageBase, GetModuleHandleW(L"winmm.dll")};
    for (int i = 0; i < 3; i++) {
        rng[i][0] = (uint64_t)(uintptr_t)mods[i]; rng[i][1] = 0;
        if (mods[i]) rng[i][1] = ((IMAGE_NT_HEADERS *)((uint8_t *)mods[i] + ((IMAGE_DOS_HEADER *)mods[i])->e_lfanew))->OptionalHeader.SizeOfImage;
    }
