#define JREL(...) EMIT(__VA_ARGS__, 0, 0, 0, 0)
#define IMM64(v) do { uint64_t v_ = (v); memcpy(c + n, &v_, 8); n += 8; } while (0)
#define REL_TO(t) (*(int32_t *)(c + n - 4) = (int32_t)((uint8_t *)(t) - (c + n)))
#define PATCH(arr, cnt, t) do { for (int i_ = 0; i_ < (cnt); i_++) *(int32_t *)(c + arr[i_]) = (int32_t)((uint8_t *)(t) - (c + arr[i_] + 4)); } while (0)
    EMIT(0x48, 0x8b, 0x01);                                                                   // mov rax,[rcx]
    EMIT(0x49, 0x89, 0xc3, 0x49, 0xc1, 0xeb, 0x20); JREL(0x0f, 0x84); bat[nb++] = n - 4;      // mov r11,rax ; shr r11,32 ; jz bad
    EMIT(0x49, 0x89, 0xc3, 0x49, 0xc1, 0xeb, 0x2f); JREL(0x0f, 0x85); bat[nb++] = n - 4;      // mov r11,rax ; shr r11,47 ; jnz bad
    EMIT(0x4c, 0x8b, 0x18);                                                                   // mov r11,[rax]
    for (int m = 0; m < 3; m++) {
        if (!rng[m][1]) continue;
        EMIT(0x49, 0xba); IMM64(rng[m][0]); EMIT(0x4c, 0x89, 0xda, 0x4c, 0x29, 0xd2);         // mov r10,base ; mov rdx,r11 ; sub rdx,r10
        EMIT(0x49, 0xba); IMM64(rng[m][1]); EMIT(0x4c, 0x39, 0xd2);                           // mov r10,size ; cmp rdx,r10
        JREL(0x0f, 0x82); okat[nok++] = n - 4;                                                // jb ok
    }
    JREL(0xe9); bat[nb++] = n - 4;                                                            // jmp bad
    PATCH(okat, nok, c + n);
    EMIT(0x4c, 0x8b, 0xcd, 0x4d, 0x8b, 0xc6, 0x49, 0x8b, 0xd7, 0xff, 0x10);                  // ok: mov r9,rbp ; mov r8,r14 ; mov rdx,r15 ; call [rax]
    JREL(0xe9); REL_TO(after);
    PATCH(bat, nb, c + n);
    JREL(0xf0, 0xff, 0x05); REL_TO(c + 0x1000);                                               // bad: lock inc dword [cnt]
    JREL(0x48, 0x89, 0x0d); REL_TO(c + 0x1008);                                               // mov [last],rcx
    JREL(0xe9); REL_TO(after);
#undef PATCH
#undef REL_TO
#undef IMM64
#undef JREL
#undef EMIT
    DWORD old;
    VirtualProtect(c, 0x1000, PAGE_EXECUTE_READ, &old);
    VirtualProtect(site, 14, PAGE_EXECUTE_READWRITE, &old);
    site[0] = 0xe9; *(int32_t *)(site + 1) = (int32_t)(c - (site + 5));
    memset(site + 5, 0x90, 9);
    VirtualProtect(site, 14, old, &old);
    FlushInstructionCache(GetCurrentProcess(), site, 14);
