    if (!c) { xlog("menu null guard: no memory near the exe"); return; }
    int n = 0, j1;
#define EMIT(...) do { const uint8_t b_[] = {__VA_ARGS__}; memcpy(c + n, b_, sizeof b_); n += sizeof b_; } while (0)
    EMIT(0x48, 0x85, 0xc9);                                        // test rcx, rcx
    EMIT(0x0f, 0x84, 0, 0, 0, 0); j1 = n - 4;                      // jz null
    EMIT(0x48, 0x89, 0x5c, 0x24, 0x10);                            // mov [rsp+0x10], rbx   (the stolen bytes)
    EMIT(0xe9, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((site + 5) - (c + n));        // jmp be58a5
    *(int32_t *)(c + j1) = (int32_t)((c + n) - (c + j1 + 4));
    EMIT(0x48, 0x83, 0xec, 0x28);                                  // null: sub rsp, 0x28
    EMIT(0x48, 0xb8); { uint64_t f = (uint64_t)(uintptr_t)menu_null_guard_hit; memcpy(c + n, &f, 8); n += 8; }   // mov rax, hit
    EMIT(0xff, 0xd0);                                              // call rax
    EMIT(0x48, 0x83, 0xc4, 0x28);                                  // add rsp, 0x28
    EMIT(0x31, 0xc0);                                              // xor eax, eax
    EMIT(0xc3);                                                    // ret
