// ScriptModule::Unload use-after-free (AV reading module+0x48 at exe+17b67e1,
// ScriptManager::UpdateJob -> ScriptModule::Unload 17b67c0). The engine builds each ScriptModule header
// at the start of its own load block (17b48b0: module = loader+0x458 = the block; ModuleInfo [+0x48]
// +0x60 = the same block). Unload frees that block first and then reads / writes the module's fields
// ([+0x48], +0x50, list links +8/+0x10, file handle +0x18) in the freed memory. Harmless while the
// allocator keeps the pages; it crashes when the free releases them - which the particle ModulePool's
// streamed part-module slots do (relocatable context 0x38 over a pool slot). Our blood fx groups live in
// part-blood-and-gore / part-kit-blood-and-gore, which MP levels don't load, so the pool streams that
// module in and unloads it again after the last effect goes (B's death killed the attached trail).
// Fix: the same function with the module-side work done before the block is freed.
static void __attribute__((used)) script_module_unload_fixed(uint8_t *m) {
    static uint8_t *exe;
    if (!exe) exe = (uint8_t *)GetModuleHandleW(NULL);
    uint8_t *info = *(uint8_t **)(m + 0x48);
    uint64_t handle = *(uint64_t *)(m + 0x18);
    uint8_t *next = *(uint8_t **)(m + 8), *prev = *(uint8_t **)(m + 0x10);
    *(uint64_t *)(m + 0x50) = 0;                                   // all module writes first
    *(uint8_t **)(next + 0x10) = prev;
    *(uint8_t **)(prev + 8) = next;
    *(uint64_t *)(m + 0x10) = 0;
    *(uint64_t *)(m + 8) = 0;
    uint64_t block = *(uint64_t *)(info + 0x60);
    if (block) {
        ((void (*)(uint64_t))(exe + 0x122e2f0))(block);           // frees m itself
        *(uint64_t *)(info + 0x60) = 0;
    }
    *(uint64_t *)(info + 0x48) = 0;
    *(int32_t *)(info + 0x58) += 1;
    if (handle) {                                                   // never together with a block (17b5c40)
        uint64_t mtx = (uint64_t)(exe + 0x84b6150);
        ((void (*)(uint64_t, uint64_t, uint64_t, int, uint64_t))(exe + 0x1245c50))(mtx, mtx, (uint64_t)(exe + 0x2e9c750), 0x4e2,
                                                                            (uint64_t)(exe + 0x2e9c920));
        uint64_t mgr = ((uint64_t (*)(void))(exe + 0x14b8170))();
        ((void (*)(uint64_t, uint64_t))(exe + 0x12a0610))(mgr, handle);
        ((void (*)(uint64_t))(exe + 0x1245d20))(mtx);
    }
}
static void install_script_unload_fix(void) {
    uint8_t *f = (uint8_t *)GetModuleHandleW(NULL) + 0x17b67c0;
    static const uint8_t expect[48] = {     // whole head incl. the free call (e8 0f7ba7ff -> 122e2f0) and the lock / file-close calls' leas
        0x48, 0x89, 0x5c, 0x24, 0x08, 0x57, 0x48, 0x83, 0xec, 0x40, 0x48, 0x8b, 0xd9, 0x48, 0x8b, 0x41,
        0x48, 0x48, 0x8b, 0x48, 0x60, 0x33, 0xff, 0x48, 0x85, 0xc9, 0x74, 0x11, 0xe8, 0x0f, 0x7b, 0xa7,
        0xff, 0x48, 0x8b, 0x43, 0x48, 0x48, 0x89, 0x78, 0x60, 0x48, 0x8b, 0x43, 0x48, 0x48, 0x89, 0x78};
    static const uint8_t tail[24] = {       // 17b6822..: lea rax,[func]; mov [rsp+20],rax; mov r9d,4e2; lea r8,[file]; lea rdx,[mtx]
        0x48, 0x8d, 0x05, 0xf7, 0x60, 0x6e, 0x01, 0x48, 0x89, 0x44, 0x24, 0x20, 0x41, 0xb9, 0xe2, 0x04,
        0x00, 0x00, 0x4c, 0x8d, 0x05, 0x15, 0x5f, 0x6e};
    if (memcmp(f, expect, sizeof expect) || memcmp(f + 0x62, tail, sizeof tail)) {
        hook_fail("script unload fix: ScriptModule::Unload differs, not installed"); return;
    }
    DWORD old; VirtualProtect(f, 14, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0;
    *(uint64_t *)(f + 6) = (uint64_t)script_module_unload_fixed;
    VirtualProtect(f, 14, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 14);
    xlog("script unload fix installed (ScriptModule::Unload frees its own header last)");
}
// Ragdoll controller guard (AV reading 0x14 at exe+1e15927). Stack:
// PerformAnimDataCallback -> winmm anim hook (winmm+26d60, which our pa_root_hook wraps) -> exe 1ceb380 (object anim
// callback) -> 1e096c0 -> CompositeBody::RegisterForFrameSyncEnd (1e0b6d0) -> 1e14a80 -> 1e158e0. 1e0b6d0 updates the
// body's CompositeRagdollController ([body+0x140], 0x60 bytes, created zeroed at 1e0713d / 1e089db / 1e0cf85 and bound
// to the body by its init 1e11c60 / 1e147e0: ctrl+0 = body) and 1e158e0 reads [ctrl+0]+0x14 (body count) unchecked.
// The controller's body pointer was null: a controller that was torn down (or never bound) while the body still
// pointed at it - most likely at the match end (B's t2r-ext.prev.log: A dropped while both loaded the menu world, ~2 s after B's
// test death and ragdoll). Neither the process nor the controller are in the minidump, so which object it was is not
// known yet. In another case (frame 11592): the SAME state crashed the engine's heap relocator instead - CompositeBody::Relocate (1e0a331, run by
// RelocatableHeap::MoveRecord 12a1000 before the memmove) calls 1e14040 on [body+0x140], which reads [ctrl+0]+0x14 (cmp dword [rax+0x14], r11d
// at 1e14061, rax = 0) - on a puppet whose ragdoll controller had had no body since frame 11590 (the guard fired 3 frames in a row, the
// victim half of a paired execution that had just ended). Every consumer of the controller (update 1e14a80, relocate 1e14040, reset 1e0f390,
// 1e14160 ...) assumes [ctrl+0] = the body, so skipping one consumer at a time only moves the crash. The guard now UNBINDS the controller
// from the body ([body+0x140] = 0, the 'body without a controller' state every consumer already handles; the 0x60-byte block is left alone,
// it may be a dangling pointer) in the update and at the relocate site. Which write left [ctrl+0] = 0 is still unproven (nothing in the exe
// writes 0 there; the block's other fields look like another object's data - a stale [body+0x140] after the 11589 compaction that moved the
// slot 0 puppet's record is the likely shape). A controller with no body has nothing to drive: the cave skips its update for that frame (the same path
// as a body without a controller) and records the body, and ragctl_tick logs which object it belonged to.
static volatile LONG *g_ragctl_cnt;
static uint8_t *volatile *g_ragctl_last;
static void install_ragctl_guard(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *site = exe + 0x1e0b9ec;
    static const uint8_t expect[17] = {0x49, 0x8b, 0x8f, 0x40, 0x01, 0x00, 0x00, 0x48, 0x85, 0xc9, 0x74, 0x0d,
                                       0xe8, 0x83, 0x90, 0x00, 0x00};       // mov rcx,[r15+140]; test; je 1e0ba05; call 1e14a80
    if (memcmp(site, expect, sizeof expect)) { hook_miss(site, sizeof expect, "ragdoll controller guard: site differs, not installed"); return; }
    uint8_t *c = alloc_near(exe + 0x1e00000, 0x2000);          // page 0 code (RX), page 1 counters (RW)
    if (!c) { xlog("ragdoll controller guard: no memory near the exe"); return; }
    g_ragctl_cnt = (volatile LONG *)(c + 0x1000);
    g_ragctl_last = (uint8_t *volatile *)(c + 0x1008);
    int n = 0;
#define EMIT(...) do { const uint8_t b_[] = {__VA_ARGS__}; memcpy(c + n, b_, sizeof b_); n += sizeof b_; } while (0)
    EMIT(0x49, 0x8b, 0x8f, 0x40, 0x01, 0x00, 0x00);                                                 // mov rcx, [r15+0x140]
    EMIT(0x48, 0x85, 0xc9);                                                                         // test rcx, rcx
    EMIT(0x0f, 0x84, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e0ba05) - (c + n));  // jz skip (no controller)
    EMIT(0x48, 0x83, 0x39, 0x00);                                                                   // cmp qword [rcx], 0
    EMIT(0x0f, 0x85, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e0b9f8) - (c + n));  // jnz call 1e14a80
    EMIT(0x49, 0xc7, 0x87, 0x40, 0x01, 0x00, 0x00, 0, 0, 0, 0);                                     // mov qword [r15+0x140], 0 : the body has NO controller from here on (see below)
    EMIT(0xf0, 0xff, 0x05, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1000) - (c + n)); // lock inc dword [cnt]
    EMIT(0x4c, 0x89, 0x3d, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1008) - (c + n)); // mov [last], r15
    EMIT(0xe9, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e0ba05) - (c + n));       // jmp skip
    // second cave: CompositeBody::Relocate (1e0a2e0..) at 1e0a328 - mov r9,rdi / mov r8,rsi / mov rdx,rbp / call 1e14040 (rcx = [rbx+0x140], tested non-null)
    int n2 = 0x100;
    uint8_t *site2 = exe + 0x1e0a328, *c2 = c + n2;
    static const uint8_t expect2[14] = {0x4c, 0x8b, 0xcf, 0x4c, 0x8b, 0xc6, 0x48, 0x8b, 0xd5, 0xe8, 0x0a, 0x9d, 0x00, 0x00};
    int ok2 = !memcmp(site2, expect2, sizeof expect2);
    if (!ok2) hook_miss(site2, sizeof expect2, "ragdoll controller guard (relocate): site differs, not installed");
    n = n2;
#define EMIT2(...) do { const uint8_t b_[] = {__VA_ARGS__}; memcpy(c + n, b_, sizeof b_); n += sizeof b_; } while (0)
    EMIT2(0x48, 0x83, 0x39, 0x00);                                                                  // cmp qword [rcx], 0
    EMIT2(0x75, 0x00); int jnz_at = n - 1;                                                          // jnz normal
    EMIT2(0x48, 0xc7, 0x83, 0x40, 0x01, 0x00, 0x00, 0, 0, 0, 0);                                    // mov qword [rbx+0x140], 0 : unbound controller - the body goes on without one
    EMIT2(0xf0, 0xff, 0x05, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1000) - (c + n)); // lock inc dword [cnt]
    EMIT2(0x48, 0x89, 0x1d, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1008) - (c + n)); // mov [last], rbx
    EMIT2(0xe9, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e0a357) - (c + n));      // jmp past the controller (the same exit as 'no controller')
    c[jnz_at] = (uint8_t)(n - (jnz_at + 1));
    EMIT2(0x4c, 0x8b, 0xcf, 0x4c, 0x8b, 0xc6, 0x48, 0x8b, 0xd5);                                   // the replaced mov r9,rdi / mov r8,rsi / mov rdx,rbp
    EMIT2(0xe8, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e14040) - (c + n));      // call 1e14040
    EMIT2(0xe9, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0x1e0a336) - (c + n));      // jmp back
#undef EMIT2
#undef EMIT
    (void)c2;
    DWORD old;
    VirtualProtect(c, 0x1000, PAGE_EXECUTE_READ, &old);                   // code page only; the counters page stays RW
    VirtualProtect(site, 12, PAGE_EXECUTE_READWRITE, &old);
    site[0] = 0xe9; *(int32_t *)(site + 1) = (int32_t)(c - (site + 5));
    memset(site + 5, 0x90, 7);
    VirtualProtect(site, 12, old, &old);
    FlushInstructionCache(GetCurrentProcess(), site, 12);
    if (ok2) {
        VirtualProtect(site2, 14, PAGE_EXECUTE_READWRITE, &old);
        site2[0] = 0xe9; *(int32_t *)(site2 + 1) = (int32_t)((c + n2) - (site2 + 5));
        memset(site2 + 5, 0x90, 9);
        VirtualProtect(site2, 14, old, &old);
        FlushInstructionCache(GetCurrentProcess(), site2, 14);
    }
    xlog("ragdoll controller guard installed (update%s)", ok2 ? " + heap relocation" : " only");
}
// Diagnostics for the open root cause (frame 11592: [ctrl+0] was 0 on a puppet whose record a compaction had just moved): per slot puppet
// the process, its CompositeBody ([proc+0x898]), the body's ragdoll controller ([body+0x140]) and the controller's body pointer / array pointer
// ([ctrl+0], [ctrl+8]) are logged whenever one changes, and 'BAD' whenever a controller exists whose [ctrl+0] is not its body. Called every
// frame from ragctl_tick and right before / after each heap compaction pass (cm_hook), so the next repro names the pass that broke it.
static struct { uint8_t *proc, *body, *ctrl; uint64_t c0, c8; } g_rcw[T2R_MAX_PEERS];
static void ragctl_watch(const char *when) {
    static volatile LONG lk; static LONG nlog, nbad;
    if (!g_winmm) return;      // the heap compaction hook runs before t2r_tick's winmm init (VMA() = 0: EARLY FAULT at +50fd0)
    if (InterlockedCompareExchange(&lk, 1, 0)) return;
    typedef uint8_t *(*fn_peer)(uint32_t);
    typedef uint8_t *(*fn_proc)(uint64_t);
    for (uint32_t sl = 0; sl < T2R_MAX_PEERS; sl++) {
        uint8_t *peer = ((fn_peer)t2r_peer)(sl);
        uint64_t h = peer && !IsBadReadPtr(peer, 0x68) ? *(uint64_t *)(peer + 0x60) : 0;
        uint8_t *proc = h ? ((fn_proc)VMA(0x18000A200))(h) : NULL, *body = NULL, *ctrl = NULL;
        uint64_t c0 = 0, c8 = 0;
        if (proc && !IsBadReadPtr(proc + 0x898, 8)) body = *(uint8_t **)(proc + 0x898);
        if (body && !IsBadReadPtr(body + 0x140, 8)) ctrl = *(uint8_t **)(body + 0x140);
        if (ctrl && !IsBadReadPtr(ctrl, 0x10)) { c0 = *(uint64_t *)ctrl; c8 = *(uint64_t *)(ctrl + 8); }
        int bad = ctrl && c0 != (uint64_t)body;
        int chg = proc != g_rcw[sl].proc || body != g_rcw[sl].body || ctrl != g_rcw[sl].ctrl || c0 != g_rcw[sl].c0 || c8 != g_rcw[sl].c8;
        if (proc && (bad ? nbad < 80 : (chg && nlog < 200)) && (chg || bad)) {
            xlog("ragctl watch (%s): slot %u frame %llu proc %p body %p ctrl %p [ctrl+0] %llx [ctrl+8] %llx%s | was proc %p body %p ctrl %p [ctrl+0] %llx", when, sl,
                 (unsigned long long)g_frame, (void *)proc, (void *)body, (void *)ctrl, (unsigned long long)c0, (unsigned long long)c8,
                 bad ? " - BAD: the controller does not point back at its body" : "", (void *)g_rcw[sl].proc, (void *)g_rcw[sl].body,
                 (void *)g_rcw[sl].ctrl, (unsigned long long)g_rcw[sl].c0);
            if (bad) nbad++; else nlog++;
        }
        g_rcw[sl].proc = proc; g_rcw[sl].body = body; g_rcw[sl].ctrl = ctrl; g_rcw[sl].c0 = c0; g_rcw[sl].c8 = c8;
    }
    InterlockedExchange(&lk, 0);
}
static void ragctl_tick(void) {
    ragctl_watch("frame");
    static LONG seen;
    if (!g_ragctl_cnt || *g_ragctl_cnt == seen) return;
    LONG n = *g_ragctl_cnt; seen = n;
    uint8_t *body = *g_ragctl_last;
    typedef uint8_t *(*fn_peer)(uint32_t);
    typedef uint8_t *(*fn_proc)(uint64_t);
    typedef uint8_t *(*fn_pl)(void);
    char who[64] = "not the player or a puppet";
    uint8_t *pl = ((fn_pl)((uint8_t *)GetModuleHandleW(NULL) + 0xdabea0))();
    if (pl && !IsBadReadPtr(pl + 0x898, 8) && *(uint8_t **)(pl + 0x898) == body) snprintf(who, sizeof who, "our player");
    for (uint32_t sl = 0; sl < T2R_MAX_PEERS; sl++) {
        uint8_t *peer = ((fn_peer)t2r_peer)(sl);
        uint64_t h = peer && !IsBadReadPtr(peer, 0x68) ? *(uint64_t *)(peer + 0x60) : 0;
        uint8_t *proc = h ? ((fn_proc)VMA(0x18000A200))(h) : NULL;
        if (proc && !IsBadReadPtr(proc + 0x898, 8) && *(uint8_t **)(proc + 0x898) == body)
            snprintf(who, sizeof who, "slot %u puppet %llx (dead %d)", sl, (unsigned long long)h, peer[5]);
    }
    xlog("ragdoll controller guard: body %p has a ragdoll controller with no body - controller unbound from the body, update / relocation skipped (%ld so far; %s, match state %u)",
         body, (long)n, who, match_substate());
}
// Owner-handle guard (several crash dumps: AV reading 0x31f8 at exe+b4490f). The
// chain: PlayerMoveStick::ProcessResistWalk (0x140c27bb0, called from the move-stick update 0x140b05780 with the Player as rdx) calls vfunc +0x98
// then vfunc +0x70 of the Player's look/stick object ([player+0x50c0], class created at 0x140db0807 with the 0x770 ctor 0x140b3f160). Its +0x70
// (0x140b448c0) forwards to the sub-object at [obj+0x6a8] - 0x18 bytes {vtable 0x142ca4330, +8 handle slot = player+0x80, +0x10 u32 id = player+0x94}
// set by 0x140b45960 from the Player at its creation (the NEW Player of every life; the id is the spawn id, 0x7e6d5 there, 8 below the weapon
// pids of that respawn). The method (0x140b448d0) resolves the handle ([[obj+8]+8], valid while process+0x94 == id) and reads the process's
// [+0x31f8] component unchecked - a dead Player (+0x94 cleared by the process kill 0x141341470) gives r8 = 0. In every dump rax == rdi == the
// Player itself (slot -> the live process, only its id differs), so the Player was killed while its own move-stick update still ran
// (a killed process finishes the update it is in). Every one of these deaths is a downed death whose killer's puppet was held by a paired move.
// The cave takes the dead handle to a neutral scale 1.0 (the method's result multiplies the stick vector) instead of dereferencing 0 and
// records the handle object and the process it found; ownh_tick logs both with the process' id / kill flags. t2r-no-ownh-guard.txt = off.
static volatile LONG *g_ownh_cnt;
static uint8_t *volatile *g_ownh_obj, *volatile *g_ownh_proc;
static void install_ownh_guard(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *site = exe + 0xb4490f;
    FILE *f = exe_side_open("t2r-no-ownh-guard.txt", "r");
    if (f) { fclose(f); xlog("owner handle guard: off (t2r-no-ownh-guard.txt)"); return; }
    static const uint8_t expect[17] = {0x49, 0x8b, 0x88, 0xf8, 0x31, 0x00, 0x00, 0x48, 0x8b, 0x01, 0x48, 0xff, 0xa0, 0x20, 0x02, 0x00, 0x00};   // (rex.w jmp [rax+0x220]: "site differs" without the 0x48)
    if (memcmp(site, expect, sizeof expect)) { hook_miss(site, sizeof expect, "owner handle guard: site differs, not installed"); return; }
    uint8_t *c = alloc_near(exe + 0xb40000, 0x2000);          // page 0 code (RX), page 1 counters (RW)
    if (!c) { xlog("owner handle guard: no memory near the exe"); return; }
    g_ownh_cnt = (volatile LONG *)(c + 0x1000);
    g_ownh_obj = (uint8_t *volatile *)(c + 0x1008);
    g_ownh_proc = (uint8_t *volatile *)(c + 0x1010);
    int n = 0, jz_at;
#define EMIT(...) do { const uint8_t b_[] = {__VA_ARGS__}; memcpy(c + n, b_, sizeof b_); n += sizeof b_; } while (0)
    EMIT(0x4d, 0x85, 0xc0);                                                                         // test r8, r8
    EMIT(0x74, 0x00); jz_at = n - 1;                                                                // jz dead
    EMIT(0x49, 0x8b, 0x88, 0xf8, 0x31, 0x00, 0x00);                                                 // mov rcx, [r8+0x31f8]
    EMIT(0xe9, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((exe + 0xb44916) - (c + n));        // jmp back (mov rax,[rcx]; jmp [rax+0x220])
    c[jz_at] = (uint8_t)(n - (jz_at + 1));
    EMIT(0xf0, 0xff, 0x05, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1000) - (c + n)); // lock inc dword [cnt]
    EMIT(0x48, 0x89, 0x0d, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1008) - (c + n)); // mov [obj], rcx
    EMIT(0x48, 0x89, 0x05, 0, 0, 0, 0); *(int32_t *)(c + n - 4) = (int32_t)((c + 0x1010) - (c + n)); // mov [proc], rax
    EMIT(0xb8, 0x00, 0x00, 0x80, 0x3f);                                                             // mov eax, 1.0f
    EMIT(0xc5, 0xf9, 0x6e, 0xc0);                                                                   // vmovd xmm0, eax
    EMIT(0xc3);                                                                                     // ret (as the method itself would)
#undef EMIT
    DWORD old;
    VirtualProtect(c, 0x1000, PAGE_EXECUTE_READ, &old);
    VirtualProtect(site, 7, PAGE_EXECUTE_READWRITE, &old);
    site[0] = 0xe9; *(int32_t *)(site + 1) = (int32_t)(c - (site + 5));
    site[5] = 0x90; site[6] = 0x90;
    VirtualProtect(site, 7, old, &old);
    FlushInstructionCache(GetCurrentProcess(), site, 7);
    xlog("owner handle guard installed (a dead owner handle in the move-stick scale answers 1.0)");
}
static void ownh_tick(void) {
    static LONG seen;
    static unsigned detailed;
    if (!g_ownh_cnt || *g_ownh_cnt == seen) return;
    LONG n = *g_ownh_cnt; seen = n;
    if (detailed >= 6) return;
    detailed++;
    uint8_t *obj = *g_ownh_obj, *pr = *g_ownh_proc;
    typedef uint8_t *(*fn_pl)(void);
    uint8_t *pl = ((fn_pl)VMA(0x180050390))();
    uint32_t hid = obj && !IsBadReadPtr(obj, 0x18) ? *(uint32_t *)(obj + 0x10) : 0;
    char ps[160] = "no process behind the slot";
    if (pr && !IsBadReadPtr(pr, 0x100))
        snprintf(ps, sizeof ps, "process %p (%s) id now %x, flags +a %02x +c %02x +32 %02x", (void *)pr, pr == pl ? "our player" : "another process",
                 *(uint32_t *)(pr + 0x94), pr[0xa], pr[0xc], pr[0x32]);
    xlog("owner handle guard: frame %llu - the move-stick scale met a dead owner handle (id %x, handle object %p) -> %s; our player now %p, "
         "downed death %d, local hp %.1f (%ld so far)", (unsigned long long)g_frame, hid, (void *)obj, ps, (void *)pl, g_down_dying, local_hp(), (long)n);
}
// Frame-sync-end guard (the same crash twice: respawn right after an execution death, first
// own spawn of scar-male-06 in the process). AV "WINMM.dll+2f7ec (info 0 108)": winmm's wrapper of the binding-handle resolver
// exe 0x15f9980 (it only filters handle indices >= 0x2000) read [0x108]. Chain (crash_veh stack + static RE, exe 1.6.0):
//   1cd0936 -> RigidBody::FrameSyncEndAllBodies (0x1420a5140, rigid-body-fse.cpp) walks the rigid body pool (bitmap exe+0x938ed80,
//   pointers exe+0x8f0b080, 0x2000), collects the distinct [rigidbody+0x70] = CompositeBody of the bodies it processed (0x1420a4185)
//   and calls 0x141e094b0(cb) for each (call at 0x1420a56ba) -> cb+0x10 = 1, 0x141e0d320(cb), 0x141e0e250(cb): owner = [cb+8],
//   0x141dc8b40(owner) = add rcx, 0x108 (owner's BoundFrame binding) -> 0x1415f9980 -> AV at owner 0 + 0x108.
// The "CompositeBody" in r15 was not one: owner 0, body count [cb+0x14] = 0x3f800000, +0x10..+0x48 all 1.0f - a live rigid body
// in the pool still pointed at a composite body whose memory had been freed and reused (the new life's allocations sit in the
// same heap range). Neither the rigid body nor its owner are in the crash data, so the object that left it behind is unknown.
// A real composite body always has an owner (0x141e0e250 dereferences it unchecked) and a small body count (0x141e0d320 walks
// [cb+0x60] stride 0x110 that many times), so an entry failing either is freed memory: it is skipped here - 0x141e094b0 would
// otherwise also write cb+0x10 into whatever object lives there now. fse_tick names the pool rigid bodies that point at it
// ("fse guard: ..."). t2r-no-fse-guard.txt = off.
static volatile LONG g_fse_cnt;
static uint8_t *volatile g_fse_last;
static uint8_t *g_fse_orig;
static void fse_guard(uint8_t *cb) {
    uint64_t v = (uint64_t)cb;
    if (v >= 0x10000 && v < 0x7fffffffffffULL) {
        uint64_t owner = *(uint64_t *)(cb + 8);
        uint32_t nb = *(uint32_t *)(cb + 0x14);
        if (owner >= 0x10000 && owner < 0x7fffffffffffULL && nb <= 0x1000) { ((void (*)(uint8_t *))g_fse_orig)(cb); return; }
    }
    g_fse_last = cb;
    InterlockedIncrement(&g_fse_cnt);
}
static void install_fse_guard(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *site = exe + 0x20a56ba;
    FILE *f = exe_side_open("t2r-no-fse-guard.txt", "r");
    if (f) { fclose(f); xlog("fse guard: off (t2r-no-fse-guard.txt)"); return; }
    static const uint8_t pre[4] = {0x48, 0x8b, 0x0c, 0xc1};                         // mov rcx, [rcx+rax*8]
    if (memcmp(site - 4, pre, 4) || site[0] != 0xe8 || site + 5 + *(int32_t *)(site + 1) != exe + 0x1e094b0) {
        hook_fail("fse guard: FrameSyncEndAllBodies call site differs, not installed"); return;
    }
    uint8_t *c = alloc_near(exe + 0x20a0000, 0x1000);
    if (!c) { xlog("fse guard: no memory near the exe"); return; }
    g_fse_orig = exe + 0x1e094b0;
    c[0] = 0x48; c[1] = 0xb8; *(uint64_t *)(c + 2) = (uint64_t)fse_guard;          // mov rax, fse_guard
    c[10] = 0xff; c[11] = 0xe0;                                                     // jmp rax (rax is dead after the call)
    DWORD old;
    VirtualProtect(c, 0x1000, PAGE_EXECUTE_READ, &old);
    VirtualProtect(site, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(site + 1) = (int32_t)(c - (site + 5));
    VirtualProtect(site, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), site, 5);
    xlog("fse guard installed (frame-sync-end skips freed composite bodies)");
}
static void fse_tick(void) {
    if (!g_winmm) return;                               // runs at the top of t2r_tick, before the g_winmm init block (its log path reads through VMA)
    static LONG seen;
    static unsigned detailed;
    static uint64_t next_sum;
    LONG n = g_fse_cnt;
    if (n == seen) return;
    uint8_t *cb = g_fse_last;
    if (detailed >= 8) {                                // the same stale entry comes back every frame: a summary now and then
        if (g_frame >= next_sum) { next_sum = g_frame + 600; xlog("fse guard: %ld skips so far (last %p)", (long)n, cb); }
        seen = n; return;
    }
    detailed++; seen = n;
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    typedef uint8_t *(*fn_peer)(uint32_t);
    typedef uint8_t *(*fn_proc)(uint64_t);
    typedef uint8_t *(*fn_pl)(void);
    char cbs[260] = "unreadable";
    if ((uint64_t)cb >= 0x10000 && !IsBadReadPtr(cb, 0x148)) {
        const uint64_t *q = (const uint64_t *)cb;
        snprintf(cbs, sizeof cbs, "+0 %llx +8 %llx +10 %llx +18 %llx +60 %llx +108 %llx +140 %llx", (unsigned long long)q[0], (unsigned long long)q[1],
                 (unsigned long long)q[2], (unsigned long long)q[3], (unsigned long long)q[12], (unsigned long long)q[0x21], (unsigned long long)q[0x28]);
    }
    xlog("fse guard: frame-sync-end entry %p is no composite body (owner 0 / bad body count) - skipped (#%ld, frame %llu, match state %u): %s",
         cb, (long)n, (unsigned long long)g_frame, match_substate(), cbs);
    // who still points at it: the pool's rigid bodies with [rb+0x70] == cb, and whether one lies in a known composite body's array
    struct { uint8_t *cb; char who[48]; } known[1 + T2R_MAX_PEERS];
    int nk = 0;
    uint8_t *pl = ((fn_pl)(exe + 0xdabea0))();
    if (pl && !IsBadReadPtr(pl + 0x898, 8)) { known[nk].cb = *(uint8_t **)(pl + 0x898); snprintf(known[nk].who, sizeof known[nk].who, "our player %p", pl); nk++; }
    for (uint32_t sl = 0; sl < T2R_MAX_PEERS; sl++) {
        uint8_t *peer = ((fn_peer)t2r_peer)(sl);
        uint64_t h = peer && !IsBadReadPtr(peer, 0x68) ? *(uint64_t *)(peer + 0x60) : 0;
        uint8_t *proc = h ? ((fn_proc)VMA(0x18000A200))(h) : NULL;
        if (proc && !IsBadReadPtr(proc + 0x898, 8)) { known[nk].cb = *(uint8_t **)(proc + 0x898); snprintf(known[nk].who, sizeof known[nk].who, "slot %u puppet %llx", sl, (unsigned long long)h); nk++; }
    }
    const uint64_t *bits = (const uint64_t *)(exe + 0x938ed80);
    uint8_t *const *rbs = (uint8_t *const *)(exe + 0x8f0b080);
    int found = 0;
    for (uint32_t w = 0; w < 0x80 && found < 8; w++) {
        for (uint64_t m = bits[w]; m && found < 8; m &= m - 1) {
            uint32_t i = w * 64 + (uint32_t)__builtin_ctzll(m);
            uint8_t *rb = rbs[i];
            if (!rb || IsBadReadPtr(rb, 0x110) || *(uint8_t **)(rb + 0x70) != cb) continue;
            found++;
            const char *who = "in no known composite body";
            for (int k = 0; k < nk; k++) {
                uint8_t *kc = known[k].cb;
                if (!kc || IsBadReadPtr(kc, 0x68)) continue;
                uint8_t *arr = *(uint8_t **)(kc + 0x60);
                uint32_t cnt = *(uint32_t *)(kc + 0x14);
                if (arr && cnt <= 0x1000 && rb >= arr && rb < arr + (size_t)cnt * 0x110) { who = known[k].who; break; }
            }
            xlog("fse guard:   pool rigid body #%u %p -> it: +54 %x +58 %x +60 %llx +68 %llx +88 %llx +c8 %x (%s)", i, rb,
                 *(uint32_t *)(rb + 0x54), *(uint32_t *)(rb + 0x58), (unsigned long long)*(uint64_t *)(rb + 0x60),
                 (unsigned long long)*(uint64_t *)(rb + 0x68), (unsigned long long)*(uint64_t *)(rb + 0x88), *(uint32_t *)(rb + 0xc8), who);
        }
    }
    if (!found) xlog("fse guard:   no pool rigid body points at it any more (freed / relocated this frame)");
}
// QueryVegetation guard (crash at map load: InteractiveImpl::QueryVegetation exe+13d77f0 from Player::Active::Update, on a
// level vegetation grid whose storage AND bit set are garbage - the fact-lookup guard returned "not found", the bit-set walk exe+2b4e30 then
// read through the same garbage). Before the engine walks the (up to 4) per-level grids, each grid's storage / bit-set pointers are checked:
// any garbage = "no vegetation here" (0), the whole query skipped this frame.
typedef uint32_t (*fn_vegq)(void *, void *, void *, uint32_t);
static fn_vegq g_vegq_tramp;
// The entry check is not enough (another crash: same AV exe+2b4ebd, grid 137ce00080 whose storage / bit set read
// 7cefe85c00012345 / 5af000000013 - the 0x12345 fill of freed level memory - while the menu scene loaded after a match): the query runs on a
// worker (Process::ExecuteProcessesAsync) while the level unloads on another thread, so the grid is freed AFTER the entry check passed. The two
// bit-set walks inside the query (calls at exe+13d7a1b / 13d7a63 to exe+2b4e30) now check the bit set right before they read it; a garbage one
// answers "end" for both walks (equal end markers = the engine's own "nothing in this cell" path, jump to the next grid).
typedef void *(*fn_bitwalk)(void *, void *, uint64_t);
static fn_bitwalk g_bitwalk;
// per-thread end marker via TlsAlloc, not __thread: a __thread var gives the DLL its first TLS directory (a second TLS directory) and
// vegetation queries run on job threads, so a plain global would mix two threads' markers
static DWORD g_vegq_tls = TLS_OUT_OF_INDEXES;
static void vegq_end_set(uint32_t v) {
    if (g_vegq_tls == TLS_OUT_OF_INDEXES) { DWORD i = TlsAlloc(); if (InterlockedCompareExchange((volatile LONG *)&g_vegq_tls, (LONG)i, (LONG)TLS_OUT_OF_INDEXES) != (LONG)TLS_OUT_OF_INDEXES) TlsFree(i); }
    if (g_vegq_tls != TLS_OUT_OF_INDEXES) TlsSetValue(g_vegq_tls, (void *)(uintptr_t)v);
}
static uint32_t vegq_end_get(void) { return g_vegq_tls == TLS_OUT_OF_INDEXES ? 0xffffffffu : (uint32_t)(uintptr_t)TlsGetValue(g_vegq_tls); }
static int vegq_ptr_ok(uintptr_t p);
static int vegq_bits_bad(const uint8_t *bs, uint64_t idx) {
    if (!vegq_ptr_ok((uintptr_t)bs) || IsBadReadPtr(bs - 8, 0x28)) return 1;
    uintptr_t st = *(const uintptr_t *)(bs - 8), w = *(const uintptr_t *)bs;
    uint64_t nbits = *(const uint64_t *)(bs + 8);
    if (!vegq_ptr_ok(st) || !vegq_ptr_ok(w) || nbits > (1ULL << 28)) return 1;
    if (idx < nbits && IsBadReadPtr((void *)(w + (idx >> 6) * 8), 8)) return 1;
    return 0;
}
static void *vegq_bitwalk1(void *bs, void *res, uint64_t idx) {
    if (vegq_bits_bad(bs, idx)) {
        static int n; if (LOGCAP(n, 10)) xlog("vegetation query: bit set %p freed during the query (level unloading) - cell skipped", bs);
        memset(res, 0, 32); ((uint32_t *)res)[7] = 0xffffffffu; vegq_end_set(0xffffffffu);
        return res;
    }
    void *r = g_bitwalk(bs, res, idx);
    {   // the entry loop at exe+13d7aa0 reads the cell this walk returns (storage + 0x10 + cell * 0x30, 4 pairs = 0x20 bytes) - a cell
        // outside readable storage = the grid was freed under us: same "end" answer as a freed bit set (the cell is never read)
        uint32_t cell = ((uint32_t *)r)[7];
        uint64_t nbits = *(const uint64_t *)(bs + 8);
        if (cell < nbits && IsBadReadPtr((const uint8_t *)*(const uintptr_t *)(bs - 8) + 0x10 + (size_t)cell * 0x30, 0x20)) {
            static int n; if (LOGCAP(n, 10)) xlog("vegetation query: cell %u of grid %p unreadable (storage freed during the query) - cell skipped", cell, (void *)(bs - 8));
            memset(res, 0, 32); ((uint32_t *)res)[7] = 0xffffffffu; vegq_end_set(0xffffffffu);
            return res;
        }
    }
    vegq_end_set(((uint32_t *)r)[7]);
    return r;
}
static void *vegq_bitwalk2(void *bs, void *res, uint64_t idx) {
    if (vegq_bits_bad(bs, idx)) {
        static int n; if (LOGCAP(n, 10)) xlog("vegetation query: bit set %p freed during the query (end walk) - cell skipped", bs);
        memset(res, 0, 32); ((uint32_t *)res)[7] = vegq_end_get();
        return res;
    }
    return g_bitwalk(bs, res, idx);
}
static int vegq_redirect(uint32_t site, void *hook) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *c = exe + site;
    if (c[0] != 0xE8 || c + 5 + *(int32_t *)(c + 1) != exe + 0x2b4e30) return 0;
    uint8_t *stub = alloc_near(c, 32);
    if (!stub) return 0;
    stub[0] = 0x48; stub[1] = 0xB8; *(uint64_t *)(stub + 2) = (uint64_t)hook;   // mov rax, hook
    stub[10] = 0xFF; stub[11] = 0xE0;                                            // jmp rax
    DWORD old;
    VirtualProtect(stub, 32, PAGE_EXECUTE_READ, &old);
    VirtualProtect(c, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(c + 1) = (int32_t)(stub - (c + 5));
    VirtualProtect(c, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), c, 5);
    return 1;
}
static int vegq_ptr_ok(uintptr_t p) { return p >= 0x10000 && p < 0x7fffffff0000ULL && !(p & 7); }
static uint32_t vegq_hook(void *self, void *pt, void *res, uint32_t a4) {
    uint8_t *s = (uint8_t *)self;
    uint8_t *opt = ((uint8_t *(*)(unsigned, unsigned))((uint8_t *)GetModuleHandleW(NULL) + 0x1270a80))(0xb, 0);
    // (re/crash-triage-1019.md): the singleton's table is guarded by a reader/writer lock word at [this+0] (the query takes the read side at
    // exe+13d78da, load / unload take the write side, bit 63 set = a level is being registered / unloaded: exe+13d62f5 / 13d67bb / 13d7616 / 13d7718).
    // A writer in progress = the level state is changing: skip this frame's query (0 results = no vegetation, the epilogue returns r12d = count)
    // instead of queueing behind it. A read-lock holder is not affected.
    if (s && !IsBadReadPtr(s, 8) && (*(volatile uint64_t *)s >> 63)) {
        static int n; if (LOGCAP(n, 10)) xlog("vegetation query: level table write-locked (level load / unload running) - query skipped this frame");
        return 0;
    }
    if (s && opt && !IsBadReadPtr(opt + 0x21d84, 1)) {
        uint8_t *base = s + (opt[0x21d84] == 0 ? 0xa8 : 0x4a8);
        if (!IsBadReadPtr(base, 0x400)) {          // the engine walks 64 {level, grid} slots (rdx = 0x40 at exe+13d7913, stride 0x10), not 4
            for (int i = 0; i < 64; i++) {
                uintptr_t lvl = *(uintptr_t *)(base + i * 16), g = *(uintptr_t *)(base + i * 16 + 8);
                if (!lvl) continue;
                // (a readable grid whose storage / bit set pointers are 0x3c0000003400 - plausible numbers that point nowhere: probe them too)
                int bad = !vegq_ptr_ok(g) || IsBadReadPtr((void *)g, 0x40) || !vegq_ptr_ok(*(uintptr_t *)g) || !vegq_ptr_ok(*(uintptr_t *)(g + 8)) ||
                          IsBadReadPtr((void *)*(uintptr_t *)g, 0x10) || IsBadReadPtr((void *)*(uintptr_t *)(g + 8), 8);
                if (bad) {
                    static int n; if (LOGCAP(n, 10)) xlog("vegetation query: level grid %d %p has garbage storage (%p / %p) - query skipped (no vegetation)", i, (void *)g,
                                                     vegq_ptr_ok(g) && !IsBadReadPtr((void *)g, 0x10) ? (void *)*(uintptr_t *)g : NULL,
                                                     vegq_ptr_ok(g) && !IsBadReadPtr((void *)g, 0x10) ? (void *)*(uintptr_t *)(g + 8) : NULL);
                    return 0;
                }
            }
        }
    }
    return g_vegq_tramp(self, pt, res, a4);
}
static void install_vegq_guard(void) {
    uint8_t *f = (uint8_t *)GetModuleHandleW(NULL) + 0x13d77f0;
    static const uint8_t expect[14] = {0x4c, 0x8b, 0xdc, 0x49, 0x89, 0x5b, 0x10, 0x49, 0x89, 0x73, 0x20, 0x57, 0x41, 0x54};
    if (memcmp(f, expect, 14)) { hook_miss(f, 14, "vegetation query guard: prologue mismatch, not installed"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 14);
    t[14] = 0xFF; t[15] = 0x25; *(uint32_t *)(t + 16) = 0;
    *(uint64_t *)(t + 20) = (uint64_t)(f + 14);
    g_vegq_tramp = (fn_vegq)t;
    DWORD old; VirtualProtect(f, 14, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0;
    *(uint64_t *)(f + 6) = (uint64_t)vegq_hook;
    VirtualProtect(f, 14, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 14);
    xlog("vegetation query guard installed (garbage level grids skipped)");
    g_bitwalk = (fn_bitwalk)((uint8_t *)GetModuleHandleW(NULL) + 0x2b4e30);
    int a = vegq_redirect(0x13d7a1b, (void *)vegq_bitwalk1), b = a && vegq_redirect(0x13d7a63, (void *)vegq_bitwalk2);
    // third site (exe+13d7e2a, the "next cell" walk after the entry loop): its result is consumed by the SAME continuation as the first site
    // (jmp 13d7a32: esi = result[7], then the end walk at 13d7a63 and the esi == end compare at 13d7a81) = identical contract, same hook
    int c = a && vegq_redirect(0x13d7e2a, (void *)vegq_bitwalk1);
    xlog("vegetation query: bit-set walk guard %s, third site %s", a && b ? "installed" : a ? "HALF installed (2nd site differs)" : "not installed (call site differs)",
         c ? "installed" : "not installed");
}
static void install_factlookup_guard(void) {
    uint8_t *f = (uint8_t *)GetModuleHandleW(NULL) + 0x13d5640;
    static const uint8_t expect[16] = {0x48, 0x89, 0x5C, 0x24, 0x08, 0x48, 0x89, 0x6C, 0x24, 0x10,
                                       0x48, 0x89, 0x74, 0x24, 0x18, 0x57};
    if (memcmp(f, expect, 16)) { hook_miss(f, 16, "fact lookup guard: prologue mismatch, not installed"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 16);
    t[16] = 0xFF; t[17] = 0x25; *(uint32_t *)(t + 18) = 0;
    *(uint64_t *)(t + 22) = (uint64_t)(f + 16);
    g_factlookup_tramp = (fn_factlookup)t;
    DWORD old; VirtualProtect(f, 16, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0;
    *(uint64_t *)(f + 6) = (uint64_t)factlookup_hook;
    f[14] = 0x90; f[15] = 0x90;
    VirtualProtect(f, 16, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 16);
    xlog("fact lookup guard installed");
}

static void install_spawn_kit(void) {
    uint8_t *f = (uint8_t *)VMA(0x18004C5D0);
    static const uint8_t expect[14] = {0x41, 0x57, 0x41, 0x56, 0x56, 0x57, 0x53, 0x48, 0x81, 0xEC,
                                       0x60, 0x04, 0x00, 0x00};
    if (memcmp(f, expect, 14)) { hook_miss(f, 14, "spawn kit: prologue mismatch, not installed"); return; }
    g_give_orig = hook_rec8(SID_GIVE_WEAPON, give_hook);
    g_settotal_orig = hook_rec8(SID_SET_TOTAL_AMMO, settotal_hook);
    if (!g_give_orig || !g_settotal_orig) { xlog("spawn kit: natives not found"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 14);
    t[14] = 0xFF; t[15] = 0x25; *(uint32_t *)(t + 16) = 0;
    *(uint64_t *)(t + 20) = (uint64_t)(f + 14);
    g_spawnkit_tramp = (fn_void)t;
    DWORD old; VirtualProtect(f, 14, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0;
    *(uint64_t *)(f + 6) = (uint64_t)spawnkit_hook;
    VirtualProtect(f, 14, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 14);
    xlog("spawn kit installed (guns only, limited reserve)");
}

// ---------------------------------------------------------------- no quick-throw lock-on
// Quick throws lock onto the nearest enemy. player-disable-auto-throw (no args) sets a
// short-lived global settings override (exe 0x140d1b130 -> settings 0xccf4287671807242,
// priority 100), so calling it every frame of a match keeps auto-throw off for every
// throwable. t2r-auto-throw.txt next to the exe keeps the game's lock-on.
static int g_keep_auto_throw;
static void feature_no_auto_throw(void) {
    static int logged;
    if (g_keep_auto_throw || match_substate() != 6) return;
    uint64_t none = 0;
    dc_call(0xccf4287671807242ULL /* player-disable-auto-throw */, 0, &none);
    if (!logged++) xlog("quick-throw lock-on disabled");
}

// ---------------------------------------------------------------- testing: full ingredients
#define SID_ADD_QTY 0x7258db3b9e03e625ULL   // player-inventory-add-item-quantity (direct)
static const uint64_t INGREDIENTS[] = {
    0xca07f03594c3d15dULL,  // alcohol
    0x2b671b6be1cdf4a2ULL,  // binding
    0x4b53d6abbc677791ULL,  // blade
    0xd862f1afc3053570ULL,  // canister
    0x2d98f344ea465df4ULL,  // explosive
    0x89f6d11960ff6cc1ULL,  // rag
};

static void feature_inf_ingredients(void) {
    static int logged;
    if (!g_inf_ingredients || match_substate() != 6 || g_frame % 60) return;
    for (size_t i = 0; i < sizeof INGREDIENTS / sizeof *INGREDIENTS; i++) {
        uint64_t before = dc_direct(SID_GET_QTY, INGREDIENTS[i], 0, 0);
        dc_direct(SID_ADD_QTY, INGREDIENTS[i], 10, 0);
        if (logged < 12) {
            logged++;
            xlog("ingredients: %llx %lld -> %lld", (unsigned long long)INGREDIENTS[i], (long long)(int32_t)before,
                 (long long)(int32_t)dc_direct(SID_GET_QTY, INGREDIENTS[i], 0, 0));
        }
    }
}

// ---------------------------------------------------------------- BOW AIM ARC (2013: bownew.jpg - a green arc to a ring where the arrow lands)
// TLOU2 already draws exactly that for throwables: PlayerThrowObjectController keeps a "projectile arc" per player (static array of
// 0x1d0-byte arc states at exe 0x144196f20, accessor 0x1411beae0(player index)), fills it each frame with 0x1411be410(arc, T, pose, art-
// params, 0,0,0,0,0, 0.0f, NULL, 1.0f) and RenderGrenadeArc (0x1411bf3c0, string "RenderGrenadeArc") draws the FX the art-params name
// ("general/hud/grenade-arc:Default" beam + the "throwables-indicator" landing ring, *generic-projectile-arc-art-params*, looked up with
// 0x141357750(sid)).  Only throwable bullets carry art-params (bullet-settings +0x118); the arrow bullet's is null, which is why the bow
// has no arc.  T is a "trajectory" object (0x390 bytes: start point, launch velocity, gravity point-curve, async collision-probe results).
// Static analysis (exe 10721): the engine's own bow trajectory lives in GunMoveController (vtable exe+0x2cb4f48, update = slot 0xf8 =
// 0x140bb5130, T at +0x7f0) - but that controller is NOT reachable from the player object by a pointer scan and the engine hardly runs the update in MP
// (A/B: "no GunMoveController in the player", last engine call 1303 frames ago).  So we build our OWN trajectory object, exactly the way
// the engine's update does:
//   T = engine-constructed object (ctor 0x140dd4050(T), 0x390 bytes, zeroed page we own; re-constructed per player object / match state - never freed)
//   per frame while the local player aims the plain bow:
//     1. collect  = 0x140dd4950(T, desc)      last frame's async probe results -> T+0x340.., T+0x368 (hit distance, < 0 = none yet)
//     2. arc      = 0x1411c0b70(arc,0) + 0x1411be410(arc, T, pose, generic art, ..)   (only if collect said ok and T+0x368 >= 0)
//     3. build    = 0x140dd5020(T, P, 0)      builds the flight (and submits the probe for the next frame) from the params P (0xd0 bytes):
//        P+0x00 start = point of the camera ray nearest to the muzzle (0x14117e650 = o + max(0,dot(m-o,d)/dot(d,d))*d)
//        P+0x10 launch velocity = aim direction * lerp(draw amount 0..1: settings +0x94 -> +0x160) (exe 0x140a8c742 + map-range 0x140a8a6d0)
//        P+0x20 = max(bullet-settings +0x18, 0.001)   P+0x24..0xa8 = the 0x84-byte gravity point-curve = *(bullet-settings +0x98)
//        P+0xa8 = 0x267de47d16a (probe mask)  P+0xb0 = 0x200  P+0xb8 = 0.01 (step)  P+0xbc = 100.0 (max range)  P+0xcc = -1.0  rest 0
//   Inputs (all verified, a miss logs once and draws nothing): the weapon object = 0x141184b30(0x140bdc1f0(*(player+0x2f60))), its vtable
//   +0xbf8 (must be false), +0xb88 (bullet settings, first qword must be the ProjectileArrow id 0x1b9e9b79cb7d05e7), +0xc58 (muzzle point out);
//   camera ray = 0x140c72440(*(player+0x3278), out): out+0x10 origin, out+0x20 direction.
// Not driven by the accessibility option (the producers gate on a player flag "object-arc"; we skip that gate on purpose:
// 2013 always showed it).  t2r-no-bow-arc.txt next to the exe = off.  Log lines: "bow: arc ...".
// The beam is a ribbon of constant WORLD width (art params +4 = 0.04 m), so seen from the bow it is fat near the muzzle and a
// 1-2 px "plain line" in the far half - RenderGrenadeArc (0x1411bf3c0) always draws all 50 samples of the whole flight as one ribbon (the sample
// positions are the analytic flight p(t) over [0, hit time], NOT our 1001 probe points, and its alpha only ramps in over the first 17 samples and out over
// the last 0.5 m), so there is no length / capacity limit to raise.  Fix: hook the per-sample function 0x1411beb80 (arc, idx, .., pos out, half-width
// vector out) and scale each sample's half-width by its distance from the camera, so the beam keeps one screen width along the whole arc.
// (REMOVED: the widening hook and the ribbon itself - replaced by bow_dots_*, see below.)
// The arrow arc was not 100% accurate to where the arrow lands.  Audit of the real fire path by disassembly (exe 10721):
//  * flight model = the engine's trajectory builder 0x140dd5020 (time step 0.01 s; sample k at t = k*0.01): gravity curve with exactly ONE key:
//    p = x0 + v t - 0.5 g(t) t^2 (y up); any other key count (0 = default 9.8, >= 2 keys): trapezoid integration, v.y -= (g(t_old)+g(t_new))/2 dt,
//    p += (v_old+v_new)/2 dt.  The beam renderer 0x1411beb80 ALWAYS draws the closed form p = x0 + v t - 0.5 g(t) t^2 (t = t0 + (t1-t0) idx/49),
//    so for a curve with 2+ keys the ribbon left the engine's own flight (bow_sim_pos + the sample hook below put it back: v is shifted per sample).
//  * the real arrow (Shoot 0x141183570 -> Fire vfunc +0xc70 = 0x14118cef0): spawn point = 0x1411861d0 (weapon locator + R * weapon+0xf10, the muzzle
//    offset the weapon update 0x141182xxx keeps), NOT the muzzle vfunc; launch velocity = weapon+0xf40 (flag +0xf30) written by the player bow update
//    0x140a8c510 each frame (charge = 0x140a8a260 = max(+0x478, the last frames' history), steady-aim solver), speed = |f40|, direction = normalize(f40)
//    (+ random spread only when weapon+0xdb0+0x78/+0x80 scaled by (1 - +0x70) are > 0; the check log prints them).
//  * the engine's own camera-ray point / direction come from 0x140a8a3e0 (muzzle or the player's bow joint 0x2d4583d39e2ede7e), we call it too.
// t2r-bow-arc-check.txt next to the exe: log the predicted landing at release and the real arrow's flight / impact ("bow check: ..." lines).
struct bow_snap {
    int valid, hit_ok, hit_pos_ok, ncurve, solved, used_f40, f40_ok; uint64_t frame;
    float start[3], v[3], v_ours[3], c58[3], aimpt[3], f40[3], hit_pos[3], radius, speed, charge, charge_eng, hit_t0, hit_t1, hit_dist, sim_hit[3], spread[6], set_e8, set_ec;
    int desc_mode[3]; uint8_t desc_b88; uint8_t curve[0x84], curve0[0x84]; float dtf, hit_tw, hit_tc; int hit_src; float spawn_real[3], spawn_ok_f, joint_p[3], joint_ok_f; int start_src;
    float vis_off[3];     // drawn arc only: where the nocked arrow is now vs the start point, beyond the standing relation (crouch / prone); 0 = none
};
static struct bow_snap g_bow_snap, g_bow_last;      // g_bow_last = the last valid snapshot (still there after the arc went off at release: the check log)
static int bow_finite4(const float *v, int n);
static float bow_curve_eval(const uint8_t *c, float t) {       // = exe 0x14167eb40 (point curve: int count, 16 keys, 16 values; linear between keys, clamped)
    int n = *(const int *)c;
    const float *k = (const float *)(c + 4), *v = (const float *)(c + 0x44);
    if (n <= 0 || n > 16) return 0.0f;
    if (!(k[0] < t)) return v[0];
    if (!(t < k[n - 1])) return v[n - 1];
    int j = 1;
    while (j < n - 1 && !(t < k[j])) j++;
    float k0 = k[j - 1], k1 = k[j], v0 = v[j - 1], v1 = v[j];
    if (!(k1 > k0)) return v1;
    return v0 + (t - k0) / (k1 - k0) * (v1 - v0);
}
// Position at time t of the engine's trajectory builder (see above); cv = the 0x84-byte gravity curve, v = launch velocity.
static void bow_sim_pos(const uint8_t *cv, const float *x0, const float *v, float t, float *out) {
    const float dt = 0.01f;
    int n = *(const int *)cv;
    if (n == 1) {
        float g = bow_curve_eval(cv, t);
        out[0] = x0[0] + v[0] * t; out[1] = x0[1] + v[1] * t - 0.5f * g * t * t; out[2] = x0[2] + v[2] * t;
        return;
    }
    float p[3] = {x0[0], x0[1], x0[2]}, vel[3] = {v[0], v[1], v[2]}, tc = 0.0f;
    int k = (int)(t / dt + 1e-4f);
    if (k < 0) k = 0;
    if (k > 20000) k = 20000;
    for (int i = 0; i <= k; i++) {
        float h = i < k ? dt : t - k * dt;
        if (h <= 1e-7f) break;
        float go = n > 0 ? bow_curve_eval(cv, tc) : 9.8f;
        tc = i < k ? (i + 1) * dt : t;
        float gn = n > 0 ? bow_curve_eval(cv, tc) : 9.8f;
        float vy1 = vel[1] - 0.5f * (go + gn) * h;
        p[0] += vel[0] * h; p[1] += 0.5f * (vel[1] + vy1) * h; p[2] += vel[2] * h;
        vel[1] = vy1;
    }
    out[0] = p[0]; out[1] = p[1]; out[2] = p[2];
}
// The throw ribbon (RenderGrenadeArc 0x1411bf3c0) could not give an even line - the ribbon's width is
// world units, so it was a blinding slab at the bow and thin far away (and the per-sample widening hook only traded one for the other), and its texture V
// fades with metres.  The aim arc is now our own: a pool of small HUD dots, evenly spaced on the SCREEN (like 2013's dotted aim line), drawn along the
// engine's simulated flight (bow_sim_pos - the accuracy work above stays) from 3 m along the flight's spawn point to the landing point, plus a small
// ring of dots at the landing.  bow_dots_build (from bow_arc_tick) stores the world path; bow_dots_draw (HUD draw hook) projects and draws it.
#define BOW_DOTS_MAX 1500
static float g_bow_dots[BOW_DOTS_MAX][3];
static int g_bow_dots_n, g_bow_dots_land;       // path samples; 1 = g_bow_dots_pos is the engine's landing point
static float g_bow_dots_pos[3];
static uint64_t g_bow_dots_frame;               // g_frame of the last build (the draw stops 3 frames after the tick stops feeding it)
static uint8_t *g_bow_aimo; static float g_bow_dir_tick[3];   // aim helper + the camera direction the tick used (render-timing diag)
static int g_bow_land_char;                     // 1 = the predicted landing is on a character: bright dot instead of the engine ring (2013 bow3.png)
static void bow_dots_build(const struct bow_snap *sp) {
    const float dt = 0.01f;
    float tmax = sp->hit_t1;
    g_bow_dots_n = 0;
    if (!(tmax > 0.02f && tmax < 14.0f) || !bow_finite4(sp->start, 3) || !bow_finite4(sp->v, 3)) return;
    int n = *(const int *)sp->curve, kmax = (int)(tmax / dt);
    float p[3] = {sp->start[0], sp->start[1], sp->start[2]}, vel[3] = {sp->v[0], sp->v[1], sp->v[2]}, tc = 0.0f;
    for (int k = 0; k <= kmax + 1 && g_bow_dots_n < BOW_DOTS_MAX; k++) {
        float t = k <= kmax ? k * dt : tmax;
        if (k > 0) {                 // the engine's trapezoid step (bow_sim_pos), kept incremental
            float h = t - tc;
            if (h > 1e-7f) {
                float go = n > 0 ? bow_curve_eval(sp->curve, tc) : 9.8f, gn = n > 0 ? bow_curve_eval(sp->curve, t) : 9.8f;
                float vy1 = vel[1] - 0.5f * (go + gn) * h;
                p[0] += vel[0] * h; p[1] += 0.5f * (vel[1] + vy1) * h; p[2] += vel[2] * h; vel[1] = vy1;
            }
            tc = t;
        }
        float q[3];
        if (n == 1) bow_sim_pos(sp->curve, sp->start, sp->v, t, q); else memcpy(q, p, 12);
        memcpy(g_bow_dots[g_bow_dots_n++], q, 12);
    }
    g_bow_dots_land = sp->hit_pos_ok && bow_finite4(sp->hit_pos, 3);
    if (g_bow_dots_land) {
        memcpy(g_bow_dots_pos, sp->hit_pos, 12);
        if (g_bow_dots_n < BOW_DOTS_MAX) memcpy(g_bow_dots[g_bow_dots_n++], sp->hit_pos, 12);
    } else if (g_bow_dots_n) memcpy(g_bow_dots_pos, g_bow_dots[g_bow_dots_n - 1], 12);
    g_bow_dots_frame = g_frame;
}
// ---- BOW ARC RIBBON, REWORK
// . What broke, from the code + A/B logs of:
//  * ground / short arcs: the start (and the hit probe) was the engine "spawn function" point 0x1411861d0, which while aiming sits at the player's FEET
//    (A log: y 7.23 constant while the muzzle moved 8.44 -> 8.57 and the camera ray was at 8.80 - 1.2..1.5 m below the bow), so the probe ran
//    along the floor and stopped on the first low box / the ground in front of the player (the Bookstore screenshot: a short streak + the landing
//    blob on a crate).  The start is now selectable at run time (t2r-bow-arc-start.txt, re-read every 2 s) and the check log measures every
//    candidate against the real arrow (bow_check_tick "start candidate" lines).
//  * the blob on walls: the engine's landing ring ("throwables-indicator", art params +0x10) is a world FX projected on the hit surface; it is never
//    drawn now - the landing marker is a small screen-space dot (bow_dots_draw).
//  * "doesn't show": a probe with no hit (sky, past 100 m) or a one-frame probe gap turned the arc off; with no hit the line now runs to 100 m and
//    fades out, and a hit is held for a few frames across probe gaps.
//  * thin stale line (the Interrogation screenshot): when our feed stopped, the renderer kept drawing its OWN copy of the last arc with the stock
//    world width (the width hook was gated off) - the throw ribbon is not drawn at all now while the bow is held and our arc is not live (g_bow_rib_hide).
//  * zigzag: the renderer computed every sample itself (closed form p = x0 + v t - g t^2 / 2 with our per-sample velocity patch for the 5-key gravity
//    curve, applied only when its velocity pointer matched) and its own camera-facing width vector, which twists where the flight runs nearly along
//    the view ray (a bow shot from behind the shoulder).  Now the tick computes all 50 samples (bow_rib_build: positions on the exact flight,
//    bow_sim_pos, and a width vector perpendicular to the view ray and the flight with sign continuity, for a constant SCREEN width) and the hook only
//    copies them in.  The renderer's own maths no longer reaches the screen.
static uint64_t g_bow_fade_t0;                  // g_t60 the arc fade-in started (0 = arc not showing)
static float g_bow_cam[3]; static int g_bow_cam_ok; static void *g_bow_arc_ptr;
static float g_bow_ppm1;                        // HUD px (1280x720 space) per metre at 1 m from the camera (focal length), measured in the HUD draw (tag_screen)
#define BOW_RIB_N 50
struct bow_rib { float t1; float pos[BOW_RIB_N][4]; float wid[BOW_RIB_N][4]; };
static struct bow_rib g_bow_rib[2];
static volatile LONG g_bow_rib_cur = -1;        // the published buffer (-1 = none)
static float g_bow_wscale = -1.0f;              // t2r-bow-arc-width.txt: width scale (default 1.0)
static float bow_dist3(const float *a, const float *b) {
    return __builtin_sqrtf((a[0] - b[0]) * (a[0] - b[0]) + (a[1] - b[1]) * (a[1] - b[1]) + (a[2] - b[2]) * (a[2] - b[2]));
}
// Flight time at which this tick's path is D metres (straight line) from its start: 0.01 s steps of the exact flight, then linear between the two
// steps around D (the old 0.01 s quantisation moved the end point in 0.6 m jumps at full draw).  -1 = not reached within 14 s.
static float bow_t_at_dist(const struct bow_snap *sp, float D) {
    float prev = 0.0f;
    for (int k = 1; k <= 1400; k++) {
        float q[3]; bow_sim_pos(sp->curve, sp->start, sp->v, k * 0.01f, q);
        float d = bow_dist3(q, sp->start);
        if (d >= D) { float u = d > prev ? (D - prev) / (d - prev) : 1.0f; return (k - 1 + u) * 0.01f; }
        prev = d;
    }
    return -1.0f;
}
// The 50 ribbon samples of this tick's flight over [0, t1].  fade_end = 1: the flight has no hit (sky / out of range): the line fades out over its last
// metres; 0: it ends at the landing marker.  Screen width 1.6 px at the bow -> 2.6 px at the end (1280x720 space), faded in over the first 1.2 m.
static void bow_rib_build(const struct bow_snap *sp, float t1, int fade_end) {
    if (g_bow_wscale < 0.0f) {
        g_bow_wscale = 1.0f;
        FILE *wf = exe_side_open("t2r-bow-arc-width.txt", "r");
        if (wf) { float v; if (fscanf(wf, "%f", &v) == 1 && v > 0.05f && v < 20.0f) g_bow_wscale = v; fclose(wf); }
        xlog("bow: arc ribbon: width scale %.2f", g_bow_wscale);
    }
    if (!g_bow_cam_ok || !(g_bow_ppm1 > 50.0f && g_bow_ppm1 < 20000.0f) || !(t1 > 0.005f && t1 < 30.0f) || !bow_finite4(sp->start, 3) || !bow_finite4(sp->v, 3)) {
        g_bow_rib_cur = -1;
        return;
    }
    struct bow_rib *r = &g_bow_rib[g_bow_rib_cur == 0 ? 1 : 0];
    float P[BOW_RIB_N][3], s[BOW_RIB_N];
    for (int i = 0; i < BOW_RIB_N; i++) bow_sim_pos(sp->curve, sp->start, sp->v, t1 * (float)i / (float)(BOW_RIB_N - 1), P[i]);
    s[0] = 0.0f;
    for (int i = 1; i < BOW_RIB_N; i++) {
        float dx = P[i][0] - P[i - 1][0], dy = P[i][1] - P[i - 1][1], dz = P[i][2] - P[i - 1][2];
        s[i] = s[i - 1] + __builtin_sqrtf(dx * dx + dy * dy + dz * dz);
    }
    float L = s[BOW_RIB_N - 1];
    if (!(L > 0.05f)) { g_bow_rib_cur = -1; return; }
    float lin = L * 0.3f < 1.2f ? L * 0.3f : 1.2f, lout = fade_end ? (L * 0.4f < 10.0f ? L * 0.4f : 10.0f) : (L * 0.08f < 0.15f ? L * 0.08f : 0.15f);
    float pw[3] = {0, 0, 0}; int havew = 0;
    for (int i = 0; i < BOW_RIB_N; i++) {
        int a = i > 0 ? i - 1 : 0, b = i < BOW_RIB_N - 1 ? i + 1 : BOW_RIB_N - 1;
        float T[3] = {P[b][0] - P[a][0], P[b][1] - P[a][1], P[b][2] - P[a][2]};
        float V[3] = {P[i][0] - g_bow_cam[0], P[i][1] - g_bow_cam[1], P[i][2] - g_bow_cam[2]};
        float d = __builtin_sqrtf(V[0] * V[0] + V[1] * V[1] + V[2] * V[2]), tl = __builtin_sqrtf(T[0] * T[0] + T[1] * T[1] + T[2] * T[2]);
        float W[3] = {V[1] * T[2] - V[2] * T[1], V[2] * T[0] - V[0] * T[2], V[0] * T[1] - V[1] * T[0]};
        float wl = __builtin_sqrtf(W[0] * W[0] + W[1] * W[1] + W[2] * W[2]);
        if (wl > 1e-4f * (d * tl + 1e-6f)) {
            W[0] /= wl; W[1] /= wl; W[2] /= wl;
            if (havew && W[0] * pw[0] + W[1] * pw[1] + W[2] * pw[2] < 0.0f) { W[0] = -W[0]; W[1] = -W[1]; W[2] = -W[2]; }   // no flip between samples
        } else if (havew) { memcpy(W, pw, 12); }
        else {                                   // flight straight along the view ray: any direction across it (horizontal)
            float hl = __builtin_sqrtf(V[0] * V[0] + V[2] * V[2]);
            W[0] = hl > 1e-4f ? -V[2] / hl : 1.0f; W[1] = 0.0f; W[2] = hl > 1e-4f ? V[0] / hl : 0.0f;
        }
        memcpy(pw, W, 12); havew = 1;
        float fi = s[i] / lin, fo = (L - s[i]) / lout;
        fi = fi < 0.0f ? 0.0f : fi > 1.0f ? 1.0f : fi; fo = fo < 0.0f ? 0.0f : fo > 1.0f ? 1.0f : fo;
        fi = fi * fi * (3.0f - 2.0f * fi); fo = fo * fo * (3.0f - 2.0f * fo);
        float px = (1.6f + 1.0f * s[i] / L) * g_bow_wscale;
        float hw = d > 0.3f ? 0.5f * px * d / g_bow_ppm1 * fi * fo : 0.0f;
        r->pos[i][0] = P[i][0]; r->pos[i][1] = P[i][1]; r->pos[i][2] = P[i][2]; r->pos[i][3] = 1.0f;
        r->wid[i][0] = W[0] * hw; r->wid[i][1] = W[1] * hw; r->wid[i][2] = W[2] * hw; r->wid[i][3] = 0.0f;
    }
    r->t1 = t1;
    g_bow_rib_cur = r == &g_bow_rib[0] ? 0 : 1;
}
typedef void (*fn_bsamp)(void *, int, const float *, const float *, const float *, float *, float *);
static fn_bsamp g_bsamp_orig;
// RenderGrenadeArc's per-sample function 0x1411beb80 (arc, idx 0..49, .., pos out, half-width vector out): the engine's sample is replaced by ours.
static void bow_beam_sample_hook(void *arc, int idx, const float *a2, const float *a3, const float *a4, float *pos, float *wid) {
    static int ncalls, nmiss;
    g_bsamp_orig(arc, idx, a2, a3, a4, pos, wid);
    if (ncalls < 3) { ncalls++; xlog("bow: arc ribbon: sample hook called (arc %p, ours %p, fade %llu, buffer %ld)", arc, g_bow_arc_ptr, (unsigned long long)g_bow_fade_t0, (long)g_bow_rib_cur); }
    if (!g_bow_fade_t0 || !pos || !wid) return;
    LONG c = g_bow_rib_cur;
    if (c < 0 || c > 1 || idx < 0 || idx >= BOW_RIB_N) {
        if (c >= 0 && LOGCAP(nmiss, 6)) xlog("bow: arc ribbon: sample index %d outside our %d samples - engine sample kept", idx, BOW_RIB_N);
        if (c < 0) { wid[0] = wid[1] = wid[2] = 0.0f; }       // live arc but no published path this frame: nothing visible rather than the engine's own
        return;
    }
    const struct bow_rib *r = &g_bow_rib[c];
    float fd = (float)(g_t60 - g_bow_fade_t0) / 10.0f; fd = fd < 0.0f ? 0.0f : fd > 1.0f ? 1.0f : fd;
    pos[0] = r->pos[idx][0]; pos[1] = r->pos[idx][1]; pos[2] = r->pos[idx][2];
    wid[0] = r->wid[idx][0] * fd; wid[1] = r->wid[idx][1] * fd; wid[2] = r->wid[idx][2] * fd;
}
static void install_bow_beam_widen(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    uint8_t *f = exe + 0x11beb80;
    // mov rax,rsp; mov [rax+0x10],rbx; mov [rax+0x18],rbp; push rsi; push rdi; push r12
    static const uint8_t pro[15] = {0x48, 0x8B, 0xC4, 0x48, 0x89, 0x58, 0x10, 0x48, 0x89, 0x68, 0x18, 0x56, 0x57, 0x41, 0x54};
    if (IsBadReadPtr(f, 15) || memcmp(f, pro, 15)) { hook_miss(f, 15, "bow: arc beam: sample function prologue differs, shaping not installed"); return; }
    uint8_t *t = (uint8_t *)VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 15);
    t[15] = 0xFF; t[16] = 0x25; *(uint32_t *)(t + 17) = 0; *(uint64_t *)(t + 21) = (uint64_t)(f + 15);
    FlushInstructionCache(GetCurrentProcess(), t, 32);
    g_bsamp_orig = (fn_bsamp)t;
    DWORD old;
    if (!VirtualProtect(f, 15, PAGE_EXECUTE_READWRITE, &old)) { g_bsamp_orig = NULL; return; }
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0; *(uint64_t *)(f + 6) = (uint64_t)bow_beam_sample_hook; f[14] = 0x90;
    VirtualProtect(f, 15, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 15);
    xlog("bow: arc ribbon: per-sample hook installed (0x1411beb80) - every ribbon sample is ours (bow_rib_build)");
}
static void install_bow_options(void);
static int g_bow_arc_on;
static volatile int32_t g_mp_ui_off;          // MP option DISABLE MP UI (OPTIONS > MULTIPLAYER, t2r-settings.txt 8th field): 1 = every MP HUD element hidden in a match (mp_ui_off_tick)
// the stock OPTIONS > HUD design (HEALTH AND WEAPON + its child rows) for DISABLE MP UI: child rows DISABLE RADAR / DISABLE LIVES COUNTER /
// DISABLE SUPPLIES / PARTS (t2r-settings.txt fields 9-11, 1 = that element hidden in a match; mpui_sync / mpui_child_tick)
static volatile int32_t g_mp_hide[4];           // [3] = DISABLE CHAT (chat, t2r-settings.txt 15th field; chat.c ch_enabled) - its own row, the DISABLE MP UI parent leaves it alone
static int g_mpui_hid[3];                      // applied this frame: radar, lives counter, supplies / parts (the radar draws read [0])
static volatile int32_t g_bow_arc_pref = 1;   // MP option BOW AIM ARC (OPTIONS > MULTIPLAYER, t2r-settings.txt 6th field): 1 on (default), 0 off; read live by bow_arc_tick
static void install_bow_arc(void) {
    FILE *nf = exe_side_open("t2r-no-bow-arc.txt", "r");
    if (nf) { fclose(nf); xlog("bow: aim arc OFF (t2r-no-bow-arc.txt)"); return; }
    g_bow_arc_on = 1;
    install_bow_beam_widen();
    xlog("bow: aim arc ON (own trajectory object, the throw arc fed with the held bow's arrow flight)");
}
static void install_melee_arc_hide(void) {
    FILE *nf = exe_side_open("t2r-no-melee-arc-hide.txt", "r");
    if (nf) { fclose(nf); xlog("melee arc: throw-arc hide OFF (t2r-no-melee-arc-hide.txt)"); return; }
    uint8_t *f = (uint8_t *)GetModuleHandleW(NULL) + 0x11bf3c0;
    // RenderGrenadeArc: mov rax,rsp; mov [rax+0x18],rbx; mov [rax+0x20],rsi; push rdi; push r12 (14 bytes, whole instructions)
    static const uint8_t pro[14] = {0x48, 0x8B, 0xC4, 0x48, 0x89, 0x58, 0x18, 0x48, 0x89, 0x70, 0x20, 0x57, 0x41, 0x54};
    if (IsBadReadPtr(f, 14) || memcmp(f, pro, 14)) { hook_miss(f, 14, "melee arc: RenderGrenadeArc prologue differs, hide not installed"); return; }
    uint8_t *t = (uint8_t *)VirtualAlloc(NULL, 128, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    int n = 0;
    t[n++] = 0x48; t[n++] = 0xB8; *(uint64_t *)(t + n) = (uint64_t)&g_arc_hide[0]; n += 8;   // mov rax, &flags
    t[n++] = 0x66; t[n++] = 0x83; t[n++] = 0x38; t[n++] = 0x00;                           // cmp word [rax], 0 (melee hide | bow ribbon hide)
    t[n++] = 0x74; t[n++] = 0x03;                                                         // je run
    t[n++] = 0x31; t[n++] = 0xC0; t[n++] = 0xC3;                                          // xor eax,eax; ret
    memcpy(t + n, pro, 14); n += 14;                                                      // run: the displaced prologue
    t[n++] = 0xFF; t[n++] = 0x25; *(uint32_t *)(t + n) = 0; n += 4; *(uint64_t *)(t + n) = (uint64_t)(f + 14); n += 8;
    FlushInstructionCache(GetCurrentProcess(), t, (SIZE_T)n);
    DWORD old;
    if (!VirtualProtect(f, 14, PAGE_EXECUTE_READWRITE, &old)) return;
    f[0] = 0xFF; f[1] = 0x25; *(uint32_t *)(f + 2) = 0; *(uint64_t *)(f + 6) = (uint64_t)t;
    VirtualProtect(f, 14, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 14);
    xlog("melee arc: RenderGrenadeArc (0x1411bf3c0) detour installed - the throw arc is not drawn while a melee weapon is held");
}
