static int tag_project(const float *p, float *x, float *y, int *edge) {
    float depth = 1.0f, cp[3] = {0}, cd[3] = {0};
    if (edge) {
        if (cam_pos_dir(cp, cd)) {
            float v[3] = {p[0] - cp[0], p[1] - cp[1], p[2] - cp[2]};
            depth = v[0] * cd[0] + v[1] * cd[1] + v[2] * cd[2];
            float tx0, ty0;
            if (depth < 0.5f || !tag_screen(p, &tx0, &ty0)) {     // behind, or a projection that fails off-screen
                // beside / behind the camera: compass placement. Horizontal camera right vector
                // (sign checked by projecting a point to that side), then the screen direction is
                // (right component, -forward component): right -> right edge, behind -> bottom.
                float rt[3] = {cd[2], 0.0f, -cd[0]};
                float rl = __builtin_sqrtf(rt[0] * rt[0] + rt[2] * rt[2]);
                if (rl < 1e-3f) return 0;
                rt[0] /= rl; rt[2] /= rl;
                float probe[3] = {cp[0] + cd[0] * 10.0f + rt[0], cp[1] + cd[1] * 10.0f, cp[2] + cd[2] * 10.0f + rt[2]};
                float sx, sy;
                if (tag_screen(probe, &sx, &sy) && sx < 640.0f) { rt[0] = -rt[0]; rt[2] = -rt[2]; }
                float r = v[0] * rt[0] + v[2] * rt[2];
                *x = 640.0f + r * 100.0f;
                *y = 360.0f - depth * 100.0f;       // behind (depth < 0) -> below the centre
                goto pin;
            }
        }
    }
    if (!tag_screen(p, x, y)) return 0;
    if (*x >= hud_x0() && *x <= hud_x1() && *y >= 0 && *y <= 720.0f) { if (edge) *edge = 0; return 1; }
    if (!edge) return 0;
pin:;
    const float m = 48.0f, cx = 640.0f, cy = 360.0f;
    float dx = *x - cx, dy = *y - cy;
    if (dx * dx + dy * dy < 1.0f) { dx = 0; dy = 1.0f; }
    float tx = dx != 0 ? (cx + g_text_xoff - m) / __builtin_fabsf(dx) : 1e9f, ty = dy != 0 ? (cy - m) / __builtin_fabsf(dy) : 1e9f;
    float t = tx < ty ? tx : ty;
    *x = cx + dx * t; *y = cy + dy * t;
    *edge = 1;
    return 1;
}
