    if (g_mhw_miss) return 0;
    if (g_mhw_h[0][0]) return 1;
    static const char K[6] = {'T', 'G', 'A', 'R', 'C', 'K'};
    for (int s = 0; s < T2R_MAX_PEERS; s++) for (int k = 0; k < 6; k++) {
        char n[16]; snprintf(n, sizeof n, "t2rMh%c%d", K[k], s);
        g_mhw_h[s][k] = hudw(n);
        if (!g_mhw_h[s][k]) { g_mhw_miss = 1; memset(g_mhw_h, 0, sizeof g_mhw_h); xlog("mate hp: widget %s not in hud-root (old gui2-widgets.pak) - glyph bar fallback", n); return 0; }
    }
    xlog("mate hp: health bars are the widgets t2rMh*0-%d (track + colour fill + ticks, placed per frame)", T2R_MAX_PEERS - 1);
