    stub[0] = 0x48; stub[1] = 0xB8; *(uint64_t *)(stub + 2) = (uint64_t)locator_hook;   // mov rax, hook
    stub[10] = 0xFF; stub[11] = 0xE0;                                                   // jmp rax
    DWORD old;
    VirtualProtect(stub, 32, PAGE_EXECUTE_READ, &old);
    VirtualProtect(c, 5, PAGE_EXECUTE_READWRITE, &old);
    *(int32_t *)(c + 1) = (int32_t)(stub - (c + 5));
    VirtualProtect(c, 5, old, &old);
    FlushInstructionCache(GetCurrentProcess(), c, 5);
    xlog("fling: locator hook installed (dead puppets no longer moved by the net position)");
