    VirtualProtect(st, 64, PAGE_EXECUTE_READ, &old);
    VirtualProtect(site, 6, PAGE_EXECUTE_READWRITE, &old);
    site[0] = 0xE9; *(int32_t *)(site + 1) = (int32_t)(st - (site + 5)); site[5] = 0x90;
    VirtualProtect(site, 6, old, &old);
