static volatile int g_pad_mode;                // 1 while the last input was the controller (ui_input_mode_tick): pages show the pad prompts / hints, 0 = keyboard / mouse
// pad / keyboard hint switch of a page's widget pair: keyboard widget (key text) and pad widget (bumper glyphs + words), written only when the mode changes; *last = -1 on a page's entry
static void ui_pad_hint(int *last, const char *kb, const char *pad) {
    if (*last == g_pad_mode) return;
    *last = g_pad_mode;
    ui_visible(kb, !g_pad_mode); ui_visible(pad, g_pad_mode);
}
