static int menu_edge(uint64_t sid, int *held) {   // 1 on the frame the menu action goes down
    int on = ((char (*)(uint64_t))VMA(0x180068AF0))(sid) != 0;
    int e = on && !*held;
    *held = on;
    return e;
}
//: L1 / R1 never changed the CUSTOMIZE / CLAN / achievements / friends tabs. The pages asked for "menu-prev" /
// "menu-next", which are no engine commands (the stock tab bars send menu-prev-tab / menu-next-tab; "menu:prev" / "menu:next" are only
// the GLYPH names), so only the Q / E keys the pages read themselves worked. menu_edge_pad = the command (keyboard and pad) OR its pad
// buttons on the joypad (padinj_raw_down): winmm's menu lock on the MP menu can disable the command while the button is held.
static int padinj_raw_down(const char *name);   // padinject.c (included later)
static int menu_edge_pad(const char *name, int *held) {
    int on = ((char (*)(uint64_t))VMA(0x180068AF0))(fnv64_rt(name)) != 0 || padinj_raw_down(name);
    int e = on && !*held;
    *held = on;
    return e;
}
#define MENU_PREV_TAB(h) menu_edge_pad("menu-prev-tab", h)
#define MENU_NEXT_TAB(h) menu_edge_pad("menu-next-tab", h)
// Same fix as for the flickering timers: on the R3 gear up pages alpha / visibility / pivot were written every frame
// too (rows, pills, icons, rules) - the same engine trait as the per-frame text writes (missed draws) and it restarted the rows' focus fades. While an R3
// page is up these three skip a write that repeats the widget's last value (per widget handle, re-asserted every 5 s; the cache restarts on page changes
// like ui_text's). Other pages keep writing every frame (some re-assert against the engine's own animations).
static int lo_r3(void);
static int ui_prop_due(int kind, uint64_t w, uint64_t h) {
    static ui_wc_t C[3][UI_WC_N];
    static uint64_t cache_top, cache_root; static unsigned cache_gen;
    if (!lo_r3() && !g_gu13_up && !g_cl13_up && !g_fr13_up) return 1;           // (the 2013 GEAR UP page, gearup13.c, and the CLAN page, clan13.c, are deduped the same way)
    uint64_t tp = top_page(), rw = ui_w("anim-group");
    if (tp != cache_top || rw != cache_root || g_ui_gen != cache_gen) { cache_top = tp; cache_root = rw; cache_gen = g_ui_gen; memset(C, 0, sizeof C); }
    return ui_wc_due(C[kind], w, h, GetTickCount64(), 0);
}
static void w_alpha(uint64_t w, float a) {
    if (!w) return;
    { union { float f; uint32_t u; } q = {a}; if (!ui_prop_due(0, w, 0x100000000ULL | q.u)) return; }
    if (a < 0.05f && match_substate() != 6) {    // UI-invisible hunt: who zeroes a menu page
        static uint64_t last_ms; uint64_t now = GetTickCount64();
        if (now - last_ms > 1000) { last_ms = now; xlog("ui alpha 0: widget %llx from ext+%llx", (unsigned long long)w,
            (unsigned long long)((uint8_t *)__builtin_return_address(0) - (uint8_t *)GetModuleHandleA("t2r-ext.dll"))); }
    }
    union { float f; uint32_t u; } v = {a};
    uint64_t args[2] = {w, v.u};
    dc_call(0x48d6c1859a4eba13ULL /* gui2-set-widget-alpha */, 2, args);
}
static void w_visible(uint64_t w, int on) {
    if (!w) return;
    if (!ui_prop_due(1, w, 0x200000000ULL | (uint64_t)(on != 0))) return;
    uint64_t a[2] = {w, (uint64_t)on};
    dc_call(0xccf99aa7589d1af9ULL /* gui2-set-widget-visible */, 2, a);
}
// Moving a widget at runtime (re/gui2-runtime.md): gui2-set-widget-pivot is NOT an engine native
// (no registration in tlou-ii.exe - it is a DC script helper that is not loaded with our
// modules, so the old calls did nothing and every dot stayed at its template spot). The natives
// are gui2-get-widget-transform(widget) -> the widget's rect transform (widget + 0x188) and
// gui2-rxfm-set-pivot-as(transform, vector2*) (as ss-hud2-weapon-cross-v2 moves its cross), which
// copies the 8 bytes (x, y) to transform + 0x20 (the layout's pivotAs, anchor space) and marks
// the transform dirty. The vector is read at once: a local one is fine.
#define SID_GUI2_GET_WIDGET_TRANSFORM 0xe2883ec3b0795b47ULL   // gui2-get-widget-transform
#define SID_GUI2_RXFM_SET_PIVOT_AS    0xe85e01d3bbca99b9ULL   // gui2-rxfm-set-pivot-as
static void w_pivot(uint64_t w, float x, float y) {
    static int logged;
    if (!w) return;
    { union { float f; uint32_t u; } qx = {x}, qy = {y}; if (!ui_prop_due(2, w, ((uint64_t)qx.u << 32) | qy.u)) return; }
    uint64_t g[1] = {w};
    uint64_t xf = dc_call(SID_GUI2_GET_WIDGET_TRANSFORM, 1, g);
    if (!xf || xf == ~0ULL || IsBadReadPtr((void *)(uintptr_t)xf, 0x28)) {
        if (logged < 4) { logged++; xlog("clan: dot pivot - no transform for widget %llx (%llx)", (unsigned long long)w, (unsigned long long)xf); }
        return;
    }
    __attribute__((aligned(16))) float v[4] = {x, y, 0.0f, 0.0f};
    uint64_t a[2] = {xf, (uint64_t)(uintptr_t)v};
    dc_call(SID_GUI2_RXFM_SET_PIVOT_AS, 2, a);
    if (logged < 4) {                               // read-back of the first dots (transform + 0x20)
        logged++;
        const float *p = (const float *)(uintptr_t)(xf + 0x20);
        xlog("clan: dot pivot set (%.1f, %.1f) via gui2-rxfm-set-pivot-as, xfm %llx reads (%.1f, %.1f)", x, y,
             (unsigned long long)xf, p[0], p[1]);
    }
}

// Detail title fit: the weapon/skill name in the DETAILS panel (perkName: left 360, box 800 of the 1180-wide panel,
// pointSize 40, left aligned) ran out of the panel for long names (EN "SUPPRESSED VARIABLE RIFLE", PL "KARABIN ZMIENNY Z TLUMIKIEM").
// gui2-rxfm-set-scale-ps (impl 141e8d210 -> 142003770: copies the vector2 to transform + 0x30, dirty flag 4) scales the widget
// about its pivot; _at() gives pivotN 0,0, so the text shrinks toward its own left edge. ~32.2 units per character (measured
// from a screenshot: 27 chars = 870 units), available 780 (360 .. panel edge 1180 minus a 40 margin).
#define SID_GUI2_RXFM_SET_SCALE_PS    0xf5835b65cca9a9ceULL   // gui2-rxfm-set-scale-ps
static void w_scale(uint64_t w, float sx, float sy) {
    if (!w) return;
    uint64_t g[1] = {w};
    uint64_t xf = dc_call(SID_GUI2_GET_WIDGET_TRANSFORM, 1, g);
    if (!xf || xf == ~0ULL || IsBadReadPtr((void *)(uintptr_t)xf, 0x40)) return;
    __attribute__((aligned(16))) float v[4] = {sx, sy, 0.0f, 0.0f};
    uint64_t a[2] = {xf, (uint64_t)(uintptr_t)v};
    dc_call(SID_GUI2_RXFM_SET_SCALE_PS, 2, a);
}
static void detail_title(const char *t) {
    static uint64_t lw, lt; static float ls = -1.0f;
    if (!t) t = "";
    ui_text("anim-group.detailPanel.perkName", t);
    const char *tr = loc_tr(t);
    int n = 0;
    for (const unsigned char *p = (const unsigned char *)(tr ? tr : t); *p; p++) if ((*p & 0xC0) != 0x80) n++;
    float s = 1.0f, est = (float)n * 32.2f;
    if (est > 780.0f) s = 780.0f / est;
    if (s < 0.6f) s = 0.6f;
    uint64_t w = ui_w("anim-group.detailPanel.perkName");
    uint64_t now = GetTickCount64();
    if (w == lw && s == ls && now - lt < 1000) return;      // re-asserted each second: a rebuilt page reusing the handle
    if (s != ls || w != lw) xlog("detail title: \"%s\" scale %.2f", tr ? tr : t, s);
    lw = w; ls = s; lt = now;
    w_scale(w, s, s);
}

// Detail description fit (in GEAR UP the 4-skill preset classes ran the DETAILS text out of the panel, PL worst).
// perkDesc is pointSize 34 (~57 layout units a line, ~26.5 units a character) with pivotN 0,0, so scaling it shrinks the whole
// block toward its top-left corner; the box scales with it, so the wrap (characters per line) stays the same and only the line
// count decides. avail = layout units from the box top to where the text must end; box_w = the box width. avail 0 = scale 1
// (the same widget is shared by pages that don't fit, e.g. picker-skill: the loadout list and the skill picker).
static void detail_desc(const char *t, float avail, float box_w) {
    static uint64_t lw, lt; static float ls = -1.0f;
    if (!t) t = "";
    ui_text("anim-group.detailPanel.perkDesc", t);
    float s = 1.0f;
    if (avail > 0.0f) {
        const char *tr = loc_tr(t);
        const unsigned char *p = (const unsigned char *)(tr ? tr : t);
        int cpl = (int)(box_w / 26.5f), lines = 0, col = 0, tag = 0;
        if (cpl < 10) cpl = 10;
        for (;; p++) {
            if (*p == '<') { tag = 1; continue; }
            if (tag) { if (*p == '>') tag = 0; if (*p) continue; }
            if (!*p || *p == '\n') { lines += col ? (col + cpl - 1) / cpl : 1; col = 0; if (!*p) break; continue; }
            if ((*p & 0xC0) != 0x80) col++;
        }
        float need = (float)lines * 57.0f;
        if (need > avail) s = avail / need;
        if (s < 0.6f) s = 0.6f;
    }
    uint64_t w = ui_w("anim-group.detailPanel.perkDesc");
    uint64_t now = GetTickCount64();
    if (w == lw && s == ls && now - lt < 1000) return;
    if (s != ls && s < 1.0f) xlog("detail desc: fit scale %.2f (avail %.0f)", s, avail);
    lw = w; ls = s; lt = now;
    w_scale(w, s, s);
}

// --- to1/clan-side: 2013 first launch (intro card, then CHOOSE YOUR SIDE)
// The faction figures are mod images (gtex1/streaming/t2r/clan, rendered from the MP character
// models by tools/models/figures). The widget layout names them too; set again by path the way
// the DETAILS panel sets its streaming icons, in case the static path is not resolved.
static void side_images(void) {
    static const char *const K[2] = {"W", "S"}, *const N[2] = {"wlf", "ser"};
    char p[96], img[64];
    for (int k = 0; k < 2; k++) {
        snprintf(img, sizeof img, "streaming/t2r/clan/fig-%s.png", N[k]);
        snprintf(p, sizeof p, "anim-group.side.fig%s.fig%sBody", K[k], K[k]);
        ui_image(p, img);
        snprintf(p, sizeof p, "anim-group.side.fig%s.fig%sDim", K[k], K[k]);
        ui_image(p, img);
        snprintf(p, sizeof p, "anim-group.intro.intro%s", K[k]);
        ui_image(p, img);
        snprintf(img, sizeof img, "streaming/t2r/clan/glow-%s.png", N[k]);
        snprintf(p, sizeof p, "anim-group.side.fig%s.fig%sGlow", K[k], K[k]);
        ui_image(p, img);
    }
}
static void ch_focus(int f);                       // choose.c: the redesigned pick
static int ch_active(void);
static void side_focus(int f) {
    static const char *const K[2] = {"W", "S"};
    char p[96];
    if (ch_active()) { ch_focus(f); return; }        // (the key art on: the old frames + figures stay hidden)
    for (int k = 0; k < 2; k++) {
        int on = k == f;
        const char *parts_on[] = {"Glow", "Body"};    // figure images (clan_widgets.py _figure)
        for (int j = 0; j < 2; j++) {
            snprintf(p, sizeof p, "anim-group.side.fig%s.fig%s%s", K[k], K[k], parts_on[j]);
            ui_visible(p, on);
        }
        snprintf(p, sizeof p, "anim-group.side.fig%s.fig%sDim", K[k], K[k]);
        ui_visible(p, !on);
        snprintf(p, sizeof p, "anim-group.side.frame%s", K[k]);
        ui_visible(p, on);
        snprintf(p, sizeof p, "anim-group.side.frameBg%s", K[k]);
        ui_visible(p, on);
    }
    ui_text("anim-group.side.sideName", SIDE_NAME[f + 1]);
    ui_text("anim-group.side.sideDesc", SIDE_DESC[f + 1]);
}
