static int g_ms_fade_st;   // (tentative: defined with the menu scene fade)
// The clan page eases in and out instead of popping. Every layer of the page JSON starts at alpha 0 (clan_widgets.build_side_page);
// side_tick ramps the backdrop (to SIDE_BG_A) over SIDE_IN_MS and the content SIDE_STAGGER_MS later, smootherstep. After the pick the page fades out
// (SIDE_OUT_MS) and is popped only then. Log: 'clan page: ...'.
#define SIDE_BG_A 0.90f                              // = clan_widgets.SIDE_BG_A
#define SIDE_IN_MS 560
#define SIDE_STAGGER_MS 140
#define SIDE_OUT_MS 300
#define SIDE_PICK_OUT_MS 1800                         // after a confirmed pick (a slower fade-out)
// Hover / highlight voice: one line of the faction's pool through the engine's native `say` on the menu world's player (the same records and
// path as the match-start lines; the player object exists on the MP menu: ms_player_exists), subtitles as the engine draws them. >= 1 s between starts, the
// previous line is stopped when a new one starts, never the same line twice in a row per faction. Pools = clan_select_vox_pools.DEFAULT_*, {kind, n} of VX_LINES.
// Logs: 'clan page: voice ...'.
static const uint8_t SIDE_VOX_SER[][2] = {{VX_INTRORSP, 1}, {VX_INTRORSP, 2}, {VX_INTRORSP, 6}, {VX_INTRORSP, 8}, {VX_INTRORSP, 9}, {VX_INTRORSP, 12},
                                          {VX_XSTMT, 3}, {VX_XSTMT, 8}, {VX_XSTMT, 10}, {VX_INTRORSP, 3}};
static const uint8_t SIDE_VOX_WLF[][2] = {{VX_INTRORSP, 1}, {VX_INTRORSP, 2}, {VX_INTRORSP, 4}, {VX_INTRORSP, 5}, {VX_INTRORSP, 8}, {VX_INTRORSP, 11},
                                          {VX_XCOMM, 6}, {VX_XCOMM, 7}, {VX_INTRO, 4}};
static uint64_t vox_stop(uint64_t ent);
static int ms_player_exists(void);
static void side_vox(int focus) {       // focus 0 = WLF, 1 = Seraphites
    static int last[2] = {-1, -1}, v = -1;
    int fac = focus == 0 ? 1 : 0;
    const uint8_t (*P)[2] = fac ? SIDE_VOX_WLF : SIDE_VOX_SER;
    int n = fac ? (int)(sizeof SIDE_VOX_WLF / sizeof *SIDE_VOX_WLF) : (int)(sizeof SIDE_VOX_SER / sizeof *SIDE_VOX_SER);
    if (v < 0) v = (int)(t2r_rand() & 3u);
    if (!ms_player_exists()) { xlog("clan page: voice skipped - no player object in the menu world yet"); return; }
    int k;
    do k = (int)(t2r_rand() % (uint32_t)n); while (n > 1 && k == last[fac]);
    last[fac] = k;
    if (P[k][1] > VX_RANGE[fac][P[k][0]][1]) return;
    int j = VX_RANGE[fac][P[k][0]][0] + P[k][1] - 1;
    vox_stop(SID_PLAYER);
    uint64_t a[4] = {SID_PLAYER, (uint64_t)VX_LINES[j].h[v], 2, 0};
    uint64_t r = dc_call(fnv64("say"), 4, a);
    xlog("clan page: voice %s kind %d n %d voice %c line %llx -> say %llx", fac ? "WLF" : "Seraphites", P[k][0], P[k][1], 'a' + v, (unsigned long long)VX_LINES[j].h[v], (unsigned long long)r);
}
static float side_ease(float u) { u = u < 0 ? 0 : u > 1 ? 1 : u; return u * u * u * (u * (u * 6.0f - 15.0f) + 10.0f); }
// One-time faction re-choice (re/clan-rechoose-1115.md): while the state says rc=1 the living clan gets this page as on first launch (intro card, then
// the pick; Esc pops it but the veiled MP menu brings it straight back, see feature_clan), and the warning line under the pick becomes this note
// (PL row in loc_pl.h). Both widgets: chWarn (the key art, choose.c sets CH_WARN in ch_show) and sideWarn (the old look).
static const char SIDE_RC_NOTE[] = "New look. Choose your side again - your clan keeps its progress.";
static void side_rc_note(const clan_t *c, int log_it) {
    if (!c->rc) return;
    ui_text("anim-group.side.chUi.chWarn", SIDE_RC_NOTE);
    ui_text("anim-group.side.sideWarn", SIDE_RC_NOTE);
    if (log_it) xlog("clan: one-time re-choice - note shown (faction %d, day %d, %d survivors kept)", c->fac, c->day, c->h + c->hu + c->s);
}
static void side_tick(int entered, const clan_t *c) {
    static int stage, focus, h_sel, h_left, h_right, h_back, h_prev, h_next, hint_dev = -1, h_hov = -1;
    static uint64_t back_at, fade_at, enter_at, exit_at, gl_t, vox_at, pick_t;
    static int pick_side = -1, pick_demo, pick_started;           // the exit after a confirmed pick (stage 6 -> 3): slow fade to black, then the reload
    static float gl[2];
    static int vox_want, was1;
    static const char *from_grp = "anim-group.intro";             // the group the faction pick crossfades from (the intro card / the end screens)
    static int fade_ms = 220;                                         // that crossfade: 220 ms from the intro card, 800 ms eased from the end screens
    static clan_t tc; static int ce_test;                            // t2r-ce-test.txt: a demo end screen over a living clan
    if (entered) { ce_test = ce_test_read(&tc); if (ce_test) xlog("clanend: test end screen (t2r-ce-test.txt)"); }
    if (ce_test) c = &tc;
    if (entered) {
        from_grp = "anim-group.intro"; fade_ms = 220;
        stage = 0; focus = 0; back_at = 0; enter_at = GetTickCount64(); gl[0] = gl[1] = 0.0f; vox_want = 0; was1 = 0; vox_at = 0;
        w_alpha(ui_w("anim-group.intro"), 0.003f);
        w_alpha(ui_w("anim-group.bgDark"), 0.003f);
        h_sel = h_left = h_right = h_back = h_prev = h_next = 1;         // whatever is held when the page opens
        hint_dev = -1;
        ui_visible("anim-group.intro", 1);
        ui_visible("anim-group.side", 0);
        ui_text("anim-group.intro.introText", c->st == 2 || c->st == 3 ? INTRO_TEXT[c->st] : INTRO_TEXT[0]);
        if (c->st == 2 || c->st == 3) {                 // end page: the finished run's stats
            char b[200];
            int d = c->day < 83 ? c->day : 83;          // (the clan has won once 83 days are done)
            ui_text("anim-group.intro.introTitle", c->st == 3 ? "<font color=\"#5dc0dc\">YOUR CLAN SURVIVED</font>"
                                                              : "<font color=\"#e04848\">YOUR CLAN IS GONE</font>");
            snprintf(b, sizeof b, "DAYS SURVIVED: %d (WEEK %d)\nMOST SURVIVORS: %d\nCLANS SURVIVED: %d   CLANS LOST: %d",
                     d, c->st == 3 ? 12 : d / 7, c->mx, c->rw, c->rl);
            ui_text("anim-group.intro.introStats", b);
            ui_text("anim-group.intro.introNextText", "START A NEW CLAN");
        } else {
            ui_text("anim-group.intro.introTitle", "");
            ui_text("anim-group.intro.introStats", "");
            ui_text("anim-group.intro.introNextText", "NEXT");
        }
        side_images();
        ch_reset();
        side_focus(0);
        xlog("clan: CHOOSE YOUR SIDE page up (status %d%s)", c->st, c->rc ? ", one-time re-choice of a living clan" : "");
        if ((c->st == 2 || c->st == 3) && ce_enabled()) {             // the end screens (clanend.c) instead of the old end card
            stage = 10; from_grp = "anim-group.end";
            ce_enter(c, ce_test);
            w_alpha(ui_w("anim-group.bgDark"), 0.003f);
        } else if (ch_enabled() && chi_enabled()) {                   // the key art + its intro cinematic (choose.c chi_*) replace the old intro card: the first-launch path
            ui_visible("anim-group.intro", 0);                        // (no side yet, incl. the server's re-choice) plays it unskippable; the page shows black (the tarp)
            w_alpha(ui_w("anim-group.side"), 1.0f);
            ui_visible("anim-group.side", 1);
            ch_show(0);
            chi_start(0);
            stage = 1;
        }
    }
    if (stage == 10) {
        g_side_stage_now = 0;
        int r = ce_tick(c);
        if (r == 2) {                                                // back after the stats: close the page
            ce_away(0);
            g_side_closed_at = GetTickCount64();
            pop_page();
            stage = 4;
            xlog("clanend: page closed (%s)", r == 2 ? "back" : "test");
            return;
        }
        if (r == 1) {                                                // START A NEW CLAN: the faction pick, as after the old end card
            ui_sfx("sfx-select");
            stage = 2; fade_at = GetTickCount64();
            enter_at = fade_at - (SIDE_IN_MS + SIDE_STAGGER_MS + 100);   // (no entrance ramp: the dark behind the faction pick is set here)
            fade_ms = 800;
            w_alpha(ui_w("anim-group.bgDark"), 1.0f);                // (under the opaque end page; eased to SIDE_BG_A with the crossfade)
            w_alpha(ui_w("anim-group.side"), 0.0f);
            ui_visible("anim-group.side", 1);
            ch_show(0);
            chi_start(1);                                             // the intro cinematic again, with a SKIP prompt (choose.c)
            menu_edge(0x6695c5b7921bb5ddULL /* menu-select */, &h_sel);   // (the press that got here does not pick a side)
            CE.ph = 0;
        }
        else return;
    }
    g_side_stage_now = stage;
    {   // entrance / exit ramps (real widget alpha)
        uint64_t nm = GetTickCount64();
        int out_ms = pick_side >= 0 ? SIDE_PICK_OUT_MS : SIDE_OUT_MS;
        float eo = stage == 3 ? 1.0f - side_ease((float)(nm - exit_at) / out_ms) : 1.0f;
        if (stage == 3 || nm - enter_at < SIDE_IN_MS + SIDE_STAGGER_MS + 60) {
            float bgv = SIDE_BG_A * side_ease((float)(nm - enter_at) / SIDE_IN_MS) * eo;
            if (stage == 3 && pick_side >= 0) bgv = SIDE_BG_A + (1.0f - SIDE_BG_A) * (1.0f - eo);   // a pick: the content fades to BLACK (the TWELVE WEEKS page comes up over it)
            float ct = side_ease((float)((int64_t)(nm - enter_at) - SIDE_STAGGER_MS) / SIDE_IN_MS) * eo;
            w_alpha(ui_w("anim-group.bgDark"), bgv < 0.003f ? 0.003f : bgv);
            if (stage == 0 || stage == 3) w_alpha(ui_w(stage == 0 ? "anim-group.intro" : "anim-group.side"), ct < 0.003f ? 0.003f : ct);
            if (stage == 3) w_alpha(ui_w("anim-group.intro"), 0.003f);
            if (enter_at && nm - enter_at < 40) xlog("clan page: fade-in start (%d ms, content +%d ms)", SIDE_IN_MS, SIDE_STAGGER_MS);
        }
        {   // mood lights of the focused faction: 300 ms ramps, cross-fading when the focus moves
            float dt = gl_t && nm - gl_t < 200 ? (float)(nm - gl_t) / 1000.0f : 0.016f, stp = dt / 0.3f;
            gl_t = nm;
            for (int k = 0; k < 2; k++) {
                float tg = (stage == 1 || stage == 2) && k == focus ? 1.0f : 0.0f, d = tg - gl[k];
                float old = gl[k];
                gl[k] += d > stp ? stp : d < -stp ? -stp : d;
                if (gl[k] != old || stage == 3) {
                    float al = side_ease(gl[k]);
                    w_alpha(ui_w(k ? "anim-group.side.glowS" : "anim-group.side.glowW"), al < 0.003f ? 0.003f : al);
                }
            }
        }
        if ((stage >= 1 && stage <= 3) || stage == 6) ch_tick(&hint_dev);   // the key art camera (choose.c; no-op with the old look)
        if (stage == 6 && chp_done()) {                              // the select payoff (logo slam, NR sound, red chalk) is over: the page's own fade out
            stage = 3; exit_at = nm; pick_side = CHP.side; pick_started = 0;
            xlog("clan page: pick fade out (%d ms, to black)%s", SIDE_PICK_OUT_MS, pick_demo ? " - demo" : "");
        }
        if (stage >= 3) {
            if (stage == 3 && nm - exit_at >= (uint64_t)out_ms) {
                // The TWELVE WEEKS page was pushed on the TITLE stack, which the MP menu
                // does not draw - the page was never seen. It goes on the MENU stack now, in the same tick as the pop (the queue keeps the order), black at once.
                if (pick_side >= 0 && !pick_started) { pick_started = 1; pick_t = nm; ms_pick_start(pick_side + 1, pick_demo); }
                if (pick_side < 0 || ms_pick_covered() || nm - pick_t > 2500) {   // (a pick: popped once the TWELVE WEEKS screen is up over it - dev23: the loading widget)
                    pop_page(); stage = 4; xlog("clan page: faded out (%d ms), popped", out_ms);
                    pick_side = -1; pick_demo = 0;
                }
            }
            return;
        }
    }
    int sel = menu_edge(0x6695c5b7921bb5ddULL /* menu-select */, &h_sel);
    int left = menu_edge(fnv64("menu-left"), &h_left), right = menu_edge(fnv64("menu-right"), &h_right);
    int back = menu_edge(fnv64("menu-back"), &h_back);
    left |= MENU_PREV_TAB(&h_prev); right |= MENU_NEXT_TAB(&h_next);      // the bumpers (LB / RB, L1 / R1) switch the side too: the pad hint shows them
    if ((stage == 1 || stage == 2) && !ch_active()) ui_pad_hint(&hint_dev, "anim-group.side.sideHint", "anim-group.side.sideHintPad");
    static ULONGLONG ce_pick_at;                      // a demo: when the faction pick took input (the intro cinematic over)
    if (!ce_test || stage != 1) ce_pick_at = 0;
    else if (!ce_pick_at && GetTickCount64() - fade_at > (uint64_t)fade_ms && (!ch_active() || chi_input_ok(GetTickCount64()))) ce_pick_at = GetTickCount64();
    static ULONGLONG ce_in_at;                        // a demo: the last input on the pick (keys, mouse, a camp focused) - the page holds while someone uses it
    if (ce_test && stage == 1 && ce_pick_at) {
        static POINT lp; POINT cp; static int lfoc = -2;
        int moved = GetCursorPos(&cp) && (cp.x != lp.x || cp.y != lp.y); lp = cp;
        int foc = ch_active() ? CH.focus : focus;
        float ccx, ccy; static int lhov = -2;                       // a hover over an unfocused window was not input
        int hv = ch_active() ? CHA.hov : -1;
        if (left || right || sel || back || (moved && (game_focused() || ui_cursor_canvas(&ccx, &ccy))) || foc != lfoc || hv != lhov) ce_in_at = GetTickCount64();
        lfoc = foc; lhov = hv;
    } else ce_in_at = 0;
    if (ce_test && stage == 1 && ce_pick_at && GetTickCount64() - (ce_in_at > ce_pick_at ? ce_in_at : ce_pick_at) > 90000) {   // a demo plays the intro, shows the faction pick, closes 90 s after the last input (never sends a side)
        g_side_closed_at = GetTickCount64(); pop_page(); stage = 4; ce_test = 0;
        xlog("clanend: page closed (test, after the faction pick)");
        return;
    }
    if (g_test_autofind && !ce_test) {                // A/B test aid: an unattended instance picks its side (intro, then the focused side) 1.5 s apart
        static ULONGLONG af_next;
        ULONGLONG now_ = GetTickCount64();
        if (!af_next) af_next = now_ + 3000;
        if (now_ >= af_next && stage != 2) {
            af_next = now_ + 1500;
            // the key art screen (choose.c) focuses nothing until left / right: an unattended select there did nothing, forever. Focus a camp first.
            if (stage == 1 && ch_active() && CH.focus < 0 && chi_input_ok(now_)) { right = 1; xlog("test autofind: CHOOSE YOUR SIDE - nothing focused, right first"); }
            else { sel = 1; xlog("test autofind: CHOOSE YOUR SIDE select (stage %d)", stage); }
        }
    }
    // Esc / B / right click during the intro or the side pick closed the page (our pop below) and feature_clan pushed it
    // again from the intro. A clan with no side has nothing to go back to: back only closes the page over a living clan (a demo end screen).
    // A focused camp still goes back to the overview (ch_back, stage 1).
    if (back && !back_at && (ce_test || c->st == 1)) back_at = g_frame;
    if (back_at && g_frame - back_at > 6) {           // the menu didn't close it itself
        back_at = 0;
        g_side_closed_at = GetTickCount64();
        pop_page();
        xlog("clan: CHOOSE YOUR SIDE closed (back)");
        return;
    }
    if (stage == 0) {
        if (sel) {
            // intro -> faction pick: the stock page-push sound (menu2 'pushed' = sfx-select, gui2-game.bin
            // *menu2-default-sounds*) and a short crossfade (it was silent and instant)
            uint64_t sa[2] = {fnv64("sfx-select"), 0};
            uint64_t sr = dc_call(fnv64("play-sound"), 2, sa);
            xlog("clan: intro -> side, sfx-select -> %llx", (unsigned long long)sr);
            stage = 2; fade_at = GetTickCount64();
            w_alpha(ui_w("anim-group.side"), 0.0f);
            ui_visible("anim-group.side", 1);
            ch_show(focus);
            side_rc_note(c, 1);                         // (after ch_show: it writes the usual warning)
        }
        return;
    }
    if (c->rc && (stage == 1 || stage == 2) && !(g_frame % 30)) side_rc_note(c, 0);   // (kept: nothing may put the usual warning back while the re-choice runs)
    if (stage == 2) {                                   // 220 ms crossfade, then the intro is hidden
        float t = (GetTickCount64() - fade_at) / (float)fade_ms;
        if (t >= 1.0f) {
            t = 1.0f; stage = 1;
            ui_visible(from_grp, 0);
            w_alpha(ui_w(from_grp), 1.0f);
            if (fade_ms > 220) xlog("clanend: crossfade to the faction pick done (%d ms)", fade_ms);
        }
        float e = fade_ms > 220 ? side_ease(t) : t;
        if (t < 1.0f) w_alpha(ui_w(from_grp), 1.0f - e);
        w_alpha(ui_w("anim-group.side"), e);
        if (fade_ms > 220) w_alpha(ui_w("anim-group.bgDark"), 1.0f + (SIDE_BG_A - 1.0f) * e);
    }
    if (ch_active() && !chi_input_ok(GetTickCount64())) {   // the intro cinematic runs: select = SKIP (when it may be skipped), nothing else
        if (sel) chi_skip();
        sel = 0;
    } else if (ch_active()) {                           // the key art (choose.c ch_input / ch_mouse / ch_back): overview -> a camp focused -> SELECT
        float mx, my;
        int live = (stage == 1 || stage == 2) && ui_cursor_canvas(&mx, &my);
        int zone = !live ? -2 : ui_mouse_over("anim-group.side.chHovW", 1) ? 0 : ui_mouse_over("anim-group.side.chHovS", 1) ? 1 : -1;
        // Hovering over just the faction name text of a selected, enlarged name moved it (a recording at 30 fps:
        // the focused big name jumped ~60 units sideways every few frames under the cursor): the names were ARMED hoverable (gui2-set-widget-hoverable,
        // here and in the click gate), and the engine's own hover handling on that Text fought the pivot ch_tick writes every frame. The names are now
        // tested by their rect only (arm 0: never made hoverable). The logos too (a recording, 51-53 s: after the pick the chosen logo, under the
        // cursor, vanished on random frames while the payoff wrote its pivot every frame).
        int tab = !live ? -1 : ui_mouse_over("anim-group.side.chUi.chLogoW", 0) || ui_mouse_over("anim-group.side.chUi.chNameW", 0) ? 0
                             : ui_mouse_over("anim-group.side.chUi.chLogoS", 0) || ui_mouse_over("anim-group.side.chUi.chNameS", 0) ? 1 : -1;
        int on_sel = live && (ui_mouse_over("anim-group.side.chUi.chSelText", 1) || ui_mouse_over("anim-group.side.chUi.chSelIcon", 1));
        int click = sel && ui_select_is_mouse();        // a click's select edge goes by what is under the cursor; Space / Enter / pad select stay the plain pick
        if (click) sel = 0;
        static int rb_held;
        int rclick = live && ne_key_edge(VK_RBUTTON, &rb_held);
        ch_input(left && (stage == 1 || stage == 2), right && (stage == 1 || stage == 2), zone, live);
        if (ch_mouse(tab, zone, on_sel, click && stage == 1, live ? mx : -1.0f, live ? my : -1.0f)) sel = 1;
        if ((back || rclick) && stage == 1 && ch_back()) { back = 0; back_at = 0; }   // a focused camp: back = the overview, not the page's close
        if (CH.focus >= 0) focus = CH.focus;
    } else {
    if (left || right) {
        focus ^= 1;
        side_focus(focus);
        if (stage == 1 || stage == 2) vox_want = 1;
    }
    if (stage == 1) {                                   // mouse: hovering a figure focuses that side, a click picks it
        int hv = ui_mouse_over("anim-group.side.figW", 1) ? 0 : ui_mouse_over("anim-group.side.figS", 1) ? 1 : -1;
        if (hv != h_hov) { h_hov = hv; if (hv >= 0 && hv != focus) { focus = hv; side_focus(focus); vox_want = 1; } }
        if (!was1) { was1 = 1; vox_want = 1; }   // the first highlight (WLF) speaks when the page shows
    }
    }
    if (vox_want && stage == 1 && GetTickCount64() - vox_at >= 1000) { vox_want = 0; vox_at = GetTickCount64(); if (!ch_vox_on()) side_vox(focus); }   // (the key art on: choose.c plays the camp take itself)
    if (ch_active()) { if (CH.focus < 0) sel = 0; else focus = CH.focus; }   // (nothing focused: nothing to pick)
    if (sel && ce_test) {                               // a demo over a living clan: select plays the payoff (logo slam, chalk), nothing is sent. (It zeroed sel
        if (stage == 1 && ch_active()) {                //  before the SKIP and the mouse saw it: the demo's SKIP and clicks did nothing)
            chp_start(focus); stage = 6; ce_test = 0; g_side_closed_at = GetTickCount64(); pick_demo = 1;
            xlog("clanend: test - select payoff for %s (no side sent)", SIDE_NAME[focus + 1]);
            return;
        }
        sel = 0;
    }
    if (sel) {
        uint8_t f = (uint8_t)(focus + 1), fx[2] = {f, CLAN_CAP_RECHOOSE};   // [faction][caps]: with rc pending the daemon changes only the living clan's faction
        if (clan_send(0xE4, fx, 2)) {
            ui_sfx("sfx-select"); xlog("clan: side %s chosen%s", SIDE_NAME[f], c->rc ? " (one-time re-choice: the clan keeps its progress)" : "");
            g_side_closed_at = GetTickCount64();   // not asked again while the reply is on its way
            g_side_wait_until = g_side_closed_at + 8000;
            ch_music_leave();
            stage = 3; exit_at = g_side_closed_at;   // fades out, then pops (stage 3 above)
            if (ch_active()) { chp_start(focus); stage = 6; pick_demo = 0; }   // the key art: the select payoff first (choose.c chp_*), then stage 3
        }
    }
}

// --- to1/main-menu clanPanel: 2013 survivors panel with the dot circle
#define CLAN_DOTS 60
#define CLAN_R 148.0f                               // dot centre range inside the 340 circle
typedef struct {                                    // a circle of survivor dots (menu panel, post-match page)
    uint64_t g[CLAN_DOTS], c[CLAN_DOTS][3];         // dot groups and their healthy / hungry / sick ellipses
    float px[CLAN_DOTS], py[CLAN_DOTS], vx[CLAN_DOTS], vy[CLAN_DOTS];
    int shown, state[CLAN_DOTS];
    uint64_t last_tick;
    float r, mid;                                   // drift radius, circle centre (widget units)
} clan_dots_t;
static struct { uint64_t panel; clan_dots_t d; } g_cw = {0, {.shown = -1, .r = CLAN_R * 0.78f, .mid = 170.0f * 0.78f}};   // (CLAN_SCALE)
static void clan_dots(clan_dots_t *D, const clan_t *c, int reset) {
    static uint32_t rng = 0x2013f;
    float *px = D->px, *py = D->py, *vx = D->vx, *vy = D->vy, R = D->r;
    int n = c->h + c->hu + c->s;
    int dn = n < CLAN_DOTS ? n : CLAN_DOTS;
    int dh = n ? (c->h * dn + n / 2) / n : 0, du = n ? (c->hu * dn + n / 2) / n : 0;
    if (dh + du > dn) du = dn - dh;
    if (c->s && dh + du >= dn && dn) { if (du) du--; else dh--; }   // keep a red dot when anyone is sick
    #define RND() ((rng = rng * 1664525u + 1013904223u) >> 8 & 0xffff)
    if (reset) D->shown = -1;
    for (int k = 0; k < CLAN_DOTS; k++) {
        int st = k >= dn ? -1 : k < dh ? 0 : k < dh + du ? 1 : 2;
        if (D->shown < 0 || st != D->state[k]) {
            if (st >= 0 && (D->shown < 0 || D->state[k] < 0)) {   // a new dot: random place and drift
                float a = RND() / 65536.0f * 6.2832f, r = R * sqrtf(RND() / 65536.0f);
                px[k] = r * cosf(a); py[k] = r * sinf(a);
                float va = RND() / 65536.0f * 6.2832f, sp = 7.0f + RND() / 65536.0f * 9.0f;   // px/s (4K)
                vx[k] = sp * cosf(va); vy[k] = sp * sinf(va);
            }
            w_visible(D->g[k], st >= 0);
            for (int j = 0; j < 3; j++) w_visible(D->c[k][j], st == j);
            D->state[k] = st;
        }
    }
    D->shown = dn;
    uint64_t now = GetTickCount64();
    float dt = D->last_tick && now - D->last_tick < 200 ? (now - D->last_tick) / 1000.0f : 0.016f;
    D->last_tick = now;
    for (int k = 0; k < dn; k++) {
        if (!(RND() & 63)) {                             // now and then a small turn
            float t = (RND() / 65536.0f - 0.5f) * 1.2f, cs = cosf(t), sn = sinf(t);
            float x = vx[k] * cs - vy[k] * sn; vy[k] = vx[k] * sn + vy[k] * cs; vx[k] = x;
        }
        px[k] += vx[k] * dt; py[k] += vy[k] * dt;
        float d2 = px[k] * px[k] + py[k] * py[k];
        if (d2 > R * R) {                                // bounce off the rim
            float d = sqrtf(d2), nx = px[k] / d, ny = py[k] / d, dot = vx[k] * nx + vy[k] * ny;
            if (dot > 0) { vx[k] -= 2 * dot * nx; vy[k] -= 2 * dot * ny; }
            px[k] = nx * R; py[k] = ny * R;
        }
        w_pivot(D->g[k], D->mid + px[k], D->mid + py[k]);
    }
    #undef RND
}
// The clan UI's widgets are looked up through the menu stack (the page on top = to1/main-menu, as the veil and
// the side page do), NOT by the fixed MP-menu key 0x5e9c...: after a scene switch (task-play-debug wipes the page
// stack, to1/main-menu is pushed again) that key kept resolving the page built at boot while the live one stayed
// empty (clan widget / title / dots gone). Fallback to the key only if the stack lookup finds nothing.
static int g_ms_cur, g_ms_scene_ok[3];         // (tentative; defined with feature_menu_scene)
static int ms_switching(void);
static int g_ms_main_pending, g_ms_main_late; static uint64_t g_ms_main_pending_at;   // (late: the switch ended on the 30 s cap, the world may not be up)    // after a scene switch: to1/main-menu still to push (feature_missions)
static int g_ms_gen;                                // bumped by feature_menu_scene when it re-pushes to1/main-menu
#define CLAN_SCALE 0.78f                            // clanPanel group scale (clan_widgets.py PANEL_SCALE)
static uint64_t cw_w(const char *path) {
    uint64_t w = ui_w(path);
    return w ? w : ((fn_widget_t)VMA(0x18000E180))(path, CLAN_KEY_MP);
}
// --- clan feed line (see the section above clan_worker). One message at a time: text + shade fade in together (the group's alpha), hold
// 4 s + 60 ms per character, fade out together, gap, next. The text is set while the group is at alpha 0 / hidden (a changed gui2 text
// draws nothing for a frame or two), the shade's x scale is set to the sentence width BEFORE the fade-in starts.
// Text width: the engine has no measuring native we know, so it is an estimate from per-glyph em widths of the menu face (calibrated on
// the detail-title measurement, 32.2 units per capital at 40 pt, i.e. ~0.8 em; lower case ~0.62 em). t2r-feed-test.txt "#scale <f>"
// multiplies it (tune in game: shade too wide -> smaller). The shade runs past the text by the fade tail, so a +-8 % error is invisible.
#define FEED_PT 30.0f                              // = clan_widgets.FEED_PT
#define FEED_TRACK 1.5f                            // = clan_widgets.FEED_TRACK
#define FEED_PAD 20.0f                             // = clan_widgets.FEED_PAD (the text a bit closer to the shade's soft left edge than the old 34)
#define FEED_SHADE_W0 1000.0f                      // = clan_widgets.FEED_SHADE_W0
#define FEED_GAIN 1.08f
// feed layout (clan_widgets.py FEED_*): the text starts at the footer separator's left end (x 180 = FEED_X + FEED_PAD) and its centre is
// midway between the clan box bottom and the separator (y 1980); the box is taller while the mission strip shows (g_feed_box_bottom).
#define FEED_X 160.0f   // shade box left edge (soft fade-in); the text stays at x 180 = FEED_X + FEED_PAD
#define FEED_H 90.0f
#define FEED_SEP_Y 1980.0f
#define BOX_BOTTOM_NOMIS 1790.2f                   // = clan_widgets.BOX_BOTTOM (PANEL_Y 1369 + PANEL_H 540 * 0.78)
#define BOX_BOTTOM_MIS 1914.2f                     // + MIS_H 124
// (enoughspace.png, overlap.png): w_pivot positions are screen page units (3840 x 2160; the footer separator is at y 1977, measured
// at 1440p on A's GEAR UP page, whose list panel ends at 1880). The box + mission strip end at 1880 (the same line as the GEAR UP panels) and
// the feed line's centre sits midway between that and the separator (1928.5), so the text has a little air above and below. Without a mission
// the box moves down by the strip's height so its bottom is where the strip's would be. The groups are top-left anchored, pivotAs = their
// position (clan_widgets PANEL_X / PANEL_H * PANEL_SCALE = 421.2 / MIS_H 124).
#define CLAN_PANEL_X 176.0f
#define CLAN_STACK_BOTTOM 1880.0f
#define CLAN_BOX_H 421.2f
#define CLAN_MIS_H 124.0f
#define CLAN_FEED_CY 1928.5f
static float g_feed_box_bottom = BOX_BOTTOM_MIS;
static float feed_text_w(const char *s, float scale) {
    float w = 0.0f;
    int tag = 0;
    for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
        unsigned char c = *p;
        if (c == '<') { tag = 1; continue; }
        if (tag) { if (c == '>') tag = 0; continue; }
        if ((c & 0xC0) == 0x80) continue;           // UTF-8 continuation
        float em;
        if (c == ' ') em = 0.34f;
        else if (strchr(".,:;'!|`", c)) em = 0.30f;
        else if (strchr("ilIjtfr()-/", c)) em = 0.40f;
        else if (c == 'm' || c == 'w') em = 0.92f;
        else if (c == 'M' || c == 'W') em = 1.00f;
        else if (c >= 'A' && c <= 'Z') em = 0.80f;
        else if (c >= '0' && c <= '9') em = 0.72f;
        else if (c >= 0x80) em = 0.66f;
        else em = 0.64f;
        w += em * FEED_PT * FEED_GAIN * scale + FEED_TRACK;
    }
    return w;
}
static void feed_alpha(uint64_t w, float a) {       // (w_alpha logs every near-zero alpha write on the menu: this one is a plain call)
    if (!w) return;
    union { float f; uint32_t u; } v = {a};
    uint64_t args[2] = {w, v.u};
    dc_call(0x48d6c1859a4eba13ULL /* gui2-set-widget-alpha */, 2, args);
}
// The texts fade in and out instead of appearing abruptly: a slow 1.2 s fade, and the alpha goes to the text and
// the shade themselves as well as the group (a group alpha alone is not known to reach its children on this page).
#define FEED_FADE_MS 1200
// The launcher clan messages are synced to in-game: one wall-clock schedule for the game AND the launcher (release/launcher/src/feed.js
// FEED_SLOT_S / FEED_LINE_S): the daemon's batch is a pure function of (clan, 60 s slot, language) (clan_story.menu_lines); line i of the slot's batch
// shows during seconds [i * 20, i * 20 + 20) of that slot - the same line at the same moment on both. The batch is asked 2 s into each slot.
#define FEED_SLOT_S 60
#define FEED_LINE_S 20
static int feed_lang(void) {                       // the language byte of op 0xB4: 1 = the game's text language is Polish, else 0 (English)
    int l = g_loc_cur;
    return l >= 0 && l < LOC_NLANG && !strcmp(LOC_LANGS[l].code, "pl") ? 1 : 0;
}
static void feed_fade(uint64_t grp, uint64_t shade, uint64_t txt, float a) { feed_alpha(grp, a); feed_alpha(shade, a); feed_alpha(txt, a); }
// the feed does not reset on a tab switch. All state (line index, phase, timers, current text) is global to the process; a new
// page instance just gets the widgets looked up again and the current phase re-applied (a line mid-hold shows at full alpha at once, a fade
// continues). Pages where the strip y 1880..1977 is taken (GEAR UP edit list, MP options, ...) are simply not in feed_page_ok: the line
// fades out in 0.3 s there (timers frozen) and resumes where it was when a fitting page is back. re/clan-feed-pages.md has the table.
// Widget handles are never kept across ticks without a fresh cw_w lookup (a popped page's widgets are freed).
#define FEED_VIS_MS 300.0f
static int feed_page_ok(uint64_t top) {
    static uint64_t ids[4];      // not on any GEAR UP page (loadout list, gun / skill pickers)
    static const char *const N[4] = {"main-menu", "find-match-menu", "leaderboard", "map-select"};
    if (!ids[0]) for (int i = 0; i < 4; i++) ids[i] = page_id(N[i]);
    for (int i = 0; i < 4; i++) if (top == ids[i]) return 1;
    return 0;
}
static float feed_ss(float x) { if (x < 0.0f) x = 0.0f; if (x > 1.0f) x = 1.0f; return x * x * (3.0f - 2.0f * x); }
static void feed_tick(int ok, uint64_t top, uint64_t now) {
    static uint64_t grp, shade, txt, t0, next_at, hold, ask_at, file_at, fr0, last_now, last_top;
    static int st, idx, fn, asked_lang = -1, last_gen = -1, inited;
    static LONG ask_ver;
    static long long feed_slot = -1, asked_slot = -1, last_key = -1;
    static char last_shown[FEED_LEN], cur[FEED_LEN];
    static char fl[12][FEED_LEN];
    static float fscale = 1.0f, vis, cur_sx = 1.0f, last_a = -1.0f;
    if (!inited) { inited = 1; next_at = now + 2500; }
    uint64_t dt = last_now && now > last_now ? now - last_now : 0;
    last_now = now;
    int force = 0;
    if (top != last_top || g_ms_gen != last_gen) { last_top = top; last_gen = g_ms_gen; force = 1; }
    if (!ok) { t0 += dt; next_at += dt; }                 // frozen while no fitting page is up
    {   // fade in / out as pages come and go (0.3 s)
        float step = (dt ? (float)dt : 16.0f) / FEED_VIS_MS;
        if (ok) vis = vis + step > 1.0f ? 1.0f : vis + step;
        else vis = vis - step < 0.0f ? 0.0f : vis - step;
    }
    if (!ok && vis <= 0.0f) { grp = shade = txt = 0; last_a = -1.0f; return; }   // nothing drawn: handles dropped, re-applied on return
    uint64_t g = cw_w("anim-group.clanFeed");
    if (g != grp || force) {                              // a new page instance (or the first look): widgets again, current phase re-applied
        grp = g;
        shade = grp ? cw_w("anim-group.clanFeed.feedShade") : 0;
        txt = grp ? cw_w("anim-group.clanFeed.feedText") : 0;
        last_a = -1.0f;
        if (grp && shade && txt) {
            w_pivot(grp, FEED_X, CLAN_FEED_CY - FEED_H * 0.5f);
            if (cur[0]) {
                ((fn_settext_t)VMA(0x180064450))(txt, cur);
                w_scale(shade, cur_sx / FEED_SHADE_W0, 1.0f);
            }
            w_visible(grp, cur[0] != 0);
        }
        else if (ok) { static int warned; if (!warned++) xlog("feed: page %llx has no clanFeed (widgets not patched?)", (unsigned long long)top); }
    }
    if (!grp || !shade || !txt) return;
    if (ok) {
        if (now >= file_at) {                           // dev lines (t2r-feed-test.txt): re-read every 3 s
            file_at = now + 3000;
            fn = 0;
            FILE *f = exe_side_open("t2r-feed-test.txt", "r");
            if (f) {
                char ln[FEED_LEN + 8];
                while (fn < 12 && fgets(ln, sizeof ln, f)) {
                    ln[strcspn(ln, "\r\n")] = 0;
                    if (!strncmp(ln, "#scale ", 7)) { float v = (float)atof(ln + 7); if (v > 0.3f && v < 3.0f) fscale = v; continue; }
                    if (!ln[0] || ln[0] == '#') continue;
                    snprintf(fl[fn++], FEED_LEN, "%s", ln);
                }
                fclose(f);
            }
        }
        time_t tt = time(NULL);
        long long tslot = (long long)tt / FEED_SLOT_S; int tsec = (int)((long long)tt % FEED_SLOT_S);
        if (!fn && g_loc_probed && !g_clan_busy && (((tslot != asked_slot && tsec >= 2) || (feed_slot != tslot && now >= ask_at)) || feed_lang() != asked_lang)) {
            uint8_t lb = (uint8_t)feed_lang();
            if (clan_send(0xB4, &lb, 1)) { asked_slot = tslot; ask_at = now + 5000; asked_lang = lb; ask_ver = g_feed_ver; }   // the slot's batch (re-asked every 5 s until it came)
        }
        if (asked_slot >= 0 && g_feed_ver != ask_ver) { feed_slot = asked_slot; ask_ver = g_feed_ver; }
        if (st == 0) {
            if (now >= next_at) {
                char m[FEED_LEN];
                int n = 0;
                long long rem_ms = 0;
                if (fn) { n = fn; snprintf(m, sizeof m, "%s", fl[idx % fn]); }
                else if (g_feed_ver && feed_slot == tslot && tslot * 8 + tsec / FEED_LINE_S != last_key) {    // the clock's line of this slot, once
                    rem_ms = ((long long)(tsec / FEED_LINE_S + 1) * FEED_LINE_S - tsec) * 1000 - 2 * FEED_FADE_MS - 700;
                    EnterCriticalSection(&g_clan_cs);
                    n = rem_ms >= 4000 ? g_feed.n : 0;      // (less than 4 s of its window left: wait for the next line)
                    if (n) snprintf(m, sizeof m, "%s", g_feed.tx[(tsec / FEED_LINE_S) % n]);
                    LeaveCriticalSection(&g_clan_cs);
                    if (n || rem_ms < 4000) last_key = tslot * 8 + tsec / FEED_LINE_S;
                }
                if (!n) next_at = now + 250;
                else {
                    size_t len = strlen(m);              // bounded: 120 characters (the group is 2600 units wide)
                    int ch = 0;
                    for (size_t i = 0; i < len; i++) {
                        if ((m[i] & 0xC0) != 0x80 && ++ch > 120) { m[i] = 0; len = i; break; }
                    }
                    snprintf(cur, sizeof cur, "%s", m);
                    ((fn_settext_t)VMA(0x180064450))(txt, m);
                    cur_sx = (FEED_PAD + feed_text_w(m, fscale)) * 1.22f + 40.0f;
                    w_scale(shade, cur_sx / FEED_SHADE_W0, 1.0f);
                    feed_fade(grp, shade, txt, 0.0f); last_a = 0.0f;
                    w_visible(grp, 1);
                    hold = 9000 + 90 * (uint64_t)ch;     // (they should stay way longer - was 4 s + 60 ms/char)
                    if (hold > 16000) hold = 16000;
                    if (!fn) hold = (uint64_t)rem_ms;    // the schedule: held to the end of its 20 s window (both fades inside it)
                    snprintf(last_shown, sizeof last_shown, "%s", m);
                    fr0 = g_frame; st = 1;
                    static int lg; if (LOGCAP(lg, 12)) xlog("feed: \"%s\" (%d chars, shade %.0f units, shown %d s)", m, ch, cur_sx, (int)(hold / 1000));
                }
            }
        }
        else if (st == 1) { if (g_frame - fr0 >= 6) { st = 2; t0 = now; } }
        else if (st == 2) { if (now - t0 >= FEED_FADE_MS) { st = 3; t0 = now; } }
        else if (st == 3) { if (now - t0 >= hold) { st = 4; t0 = now; } }
        else if (now - t0 >= FEED_FADE_MS) {              // st 4 done
            feed_fade(grp, shade, txt, 0.0f); last_a = 0.0f;
            w_visible(grp, 0);
            cur[0] = 0;
            int n = fn ? fn : g_feed.n;
            idx++;
            st = 0;
            next_at = fn ? now + 2800 : now;             // dev lines: a short gap; the schedule waits for the next window by itself
            (void)n;
        }
    }
    float pa = st == 2 ? feed_ss((now - t0) / (float)FEED_FADE_MS) : st == 3 ? 1.0f : st == 4 ? feed_ss(1.0f - (now - t0) / (float)FEED_FADE_MS) : 0.0f;
    float a = pa * feed_ss(vis);
    if (g_frame % 30 == 0) last_a = -1.0f;                // safety net: re-assert twice a second
    if (a != last_a) { feed_fade(grp, shade, txt, a); last_a = a; }
}
// Mission strip under the clan box (anim-group.clanMission, clan_widgets.py add_main_panel): the loading screen's mission block
// (same meta: mi / mp / ml / mg, see mf_loading_fill) as a compact strip on every page that carries the clan panel (main menu, find match).
// Hidden while no mission runs. Refilled when the meta (0xE9) changes and on every panel repaint (reset / force).
#define MIS_BAR_W0 1.0f
static void mission_strip_tick(int reset, int force) {
    static uint64_t grp, nm, ct, fl, pnl;
    static int last_ver = -1, last_on = -1, warned_ver = -1, pnl_on = -1;
    static char l_nm[64], l_ct[96];
    static float l_fr = -1.0f;
    if (reset) {
        grp = cw_w("anim-group.clanMission");
        nm = grp ? cw_w("anim-group.clanMission.misName") : 0;
        ct = grp ? cw_w("anim-group.clanMission.misCount") : 0;
        fl = grp ? cw_w("anim-group.clanMission.misBarFill") : 0;
        pnl = cw_w("anim-group.clanPanel"); pnl_on = -1;
        last_ver = -1; last_on = -1; l_nm[0] = l_ct[0] = 0; l_fr = -1.0f;
        if (!grp) { static int warned; if (!warned++) xlog("mission strip: page has no clanMission (widgets not patched?) - skipped"); }
        else xlog("mission strip: found (group %llx, name %d count %d bar %d)", (unsigned long long)grp, nm != 0, ct != 0, fl != 0);
    }
    if (!grp || !nm || !ct || !fl) return;
    if (force) { last_on = -1; l_nm[0] = l_ct[0] = 0; l_fr = -1.0f; }
    if (!reset && !force && last_ver == (int)g_meta_ver && last_on >= 0) return;
    last_ver = (int)g_meta_ver;
    meta_t mt = meta_get();
    int on = mt.ok && MIS_VALID(mt.mi);
    if (pnl && on != pnl_on) {
        w_pivot(pnl, CLAN_PANEL_X, CLAN_STACK_BOTTOM - CLAN_BOX_H - (on ? CLAN_MIS_H : 0.0f));
        if (on) w_pivot(grp, CLAN_PANEL_X, CLAN_STACK_BOTTOM - CLAN_MIS_H);
        pnl_on = on;
    }
    if (!on) {
        if (last_on != 0) { w_visible(grp, 0); last_on = 0; }
        g_feed_box_bottom = BOX_BOTTOM_MIS;        // (the box moved down: its bottom is where the strip's would be)
        return;
    }
    g_feed_box_bottom = BOX_BOTTOM_MIS;
    int i = mt.mi;
    int top = mis_goal_m(&mt, i, 2), nx = top;
    for (int k = 2; k >= 0; k--) if (mt.mp < mis_goal_m(&mt, i, k)) nx = mis_goal_m(&mt, i, k);
    int done = mt.mp >= top;
    int day = 3 - mt.ml + 1; if (day < 1) day = 1; if (day > 3) day = 3;
    char name[64], cnt[96];
    snprintf(name, sizeof name, "%s", MIS[i].name);
    for (char *p = name; *p; p++) *p = (char)toupper((unsigned char)*p);
    if (done) snprintf(cnt, sizeof cnt, "<font color=\"#3fa9f5\">%d/%d</font>  DONE", top, top);
    else snprintf(cnt, sizeof cnt, "<font color=\"#3fa9f5\">%d/%d</font>  DAY %d/3", mt.mp, nx, day);
    float fr = top > 0 ? (float)(mt.mp < top ? mt.mp : top) / (float)top : 0.0f;
    if (fr < 0.002f) fr = 0.002f;
    if (strcmp(name, l_nm)) { ((fn_settext_t)VMA(0x180064450))(nm, name); strcpy(l_nm, name); }
    if (strcmp(cnt, l_ct)) { ((fn_settext_t)VMA(0x180064450))(ct, cnt); strcpy(l_ct, cnt); }
    if (fr != l_fr) { w_scale(fl, fr * MIS_BAR_W0, 1.0f); l_fr = fr; }
    if (last_on != 1) w_visible(grp, 1);
    last_on = 1;
    if (warned_ver != (int)g_meta_ver) { warned_ver = (int)g_meta_ver; xlog("mission strip: %s %s (bar %.2f)", name, cnt, fr); }
}
static void panel_tick(const clan_t *c, int fresh_day) {
    static char last[6][160];
    static uint64_t shown_until;
    uint64_t now = GetTickCount64();
    uint64_t panel = cw_w("anim-group.clanPanel");
    int reset = 0, force = 0;
    static int last_gen;
    static uint64_t refresh_at;
    if (g_ms_gen != last_gen) { last_gen = g_ms_gen; g_cw.panel = 0; }   // to1/main-menu pushed again: a new page instance
    if (panel != g_cw.panel) {                          // page (re)built: look the widgets up again
        char p[128];
        g_cw.panel = panel;
        for (int k = 0; k < CLAN_DOTS && panel; k++) {
            snprintf(p, sizeof p, "anim-group.clanPanel.clanCircle.clanDot%d", k);
            g_cw.d.g[k] = cw_w(p);
            for (int j = 0; j < 3; j++) {
                snprintf(p, sizeof p, "anim-group.clanPanel.clanCircle.clanDot%d.clanDot%d%c", k, k, "HUS"[j]);
                g_cw.d.c[k][j] = cw_w(p);
            }
        }
        memset(last, 0, sizeof last);
        reset = 1;
        if (panel) {                                    // the real game icons (clan_widgets CLAN_PERSON_ICON / CLAN_SUPPLY_ICON), by path again
            uint64_t iw = cw_w("anim-group.clanPanel.clanPerson");
            if (iw) ((fn_settext_t)VMA(0x180068260))(iw, "streaming/t2r/icons/fig-us.png");
            iw = cw_w("anim-group.clanPanel.clanSupply");
            if (iw) ((fn_settext_t)VMA(0x180068260))(iw, "streaming/t2r/icons/hud-supplies.png");
        }
        if (panel) {
            int found = 0;
            for (int k = 0; k < CLAN_DOTS; k++) found += g_cw.d.g[k] != 0;
            xlog("clan: survivors panel found (dot 0 %llx, %d/%d dot widgets resolved)", (unsigned long long)g_cw.d.g[0], found, CLAN_DOTS);
        }
        else { static int warned; if (!warned++) xlog("clan: main menu has no clanPanel (widgets not patched?)"); }
    }
    if (!panel) return;
    if (reset) w_visible(panel, 1);
    if (!reset && now >= refresh_at) {                  // safety net (a page instance at the same address): repaint every 3 s
        force = 1;
        w_visible(panel, 1);
        if (g_cw.d.shown >= 0)
            for (int k = 0; k < CLAN_DOTS; k++) {
                int st = g_cw.d.state[k];
                w_visible(g_cw.d.g[k], st >= 0);
                for (int j = 0; j < 3; j++) w_visible(g_cw.d.c[k][j], st == j);
            }
    }
    if (reset || force) { refresh_at = now + 3000; memset(last, 0, sizeof last); }
    if (fresh_day) shown_until = now + 60000;
    char t[6][160];
    int d = c->day < 84 ? c->day : 83;
    snprintf(t[0], sizeof t[0], "WEEK %d: DAY %d", d / 7 + 1, d % 7 + 1);
    if (shown_until > now) {                            // the day just played, 2013 summary in short
        int k = snprintf(t[1], sizeof t[1], "%s  -  DAILY SUPPLIES: <font color=\"#3fa9f5\">+%d</font>   SURVIVORS GAINED: %d",
                         c->lleft ? "LEFT EARLY" : "DAY DONE", c->lsup, c->lgain);
        if (c->ldied && k < (int)sizeof t[1]) snprintf(t[1] + k, sizeof t[1] - k, "   <font color=\"#fd6d51\">%d DIED</font>", c->ldied);
        if (c->lsick > 0 && k < (int)sizeof t[1]) k += snprintf(t[1] + k, sizeof t[1] - k, "   <font color=\"#fd6d51\">%d FELL SICK</font>", c->lsick);
        if (c->lhungry > 0 && k < (int)sizeof t[1]) k += snprintf(t[1] + k, sizeof t[1] - k, "   %d HUNGRY", c->lhungry);
        (void)k;                                        // (the clan events have their own screens: to1/clan-event, ev_tick)
    } else {
        snprintf(t[1], sizeof t[1], "%s", SIDE_FULL[c->fac >= 1 && c->fac <= 2 ? c->fac : 0]);   // (the yellow EVENT: line is gone: the 2013 event screen announces the day's event)
    }
    snprintf(t[2], sizeof t[2], "%d SURVIVORS", c->h + c->hu + c->s);
    snprintf(t[3], sizeof t[3], "HEALTHY: %d", c->h);
    snprintf(t[4], sizeof t[4], "HUNGRY: %d", c->hu);
    snprintf(t[5], sizeof t[5], "SICK: %d", c->s);
    static const char *const W[6] = {"anim-group.menuTitle", "anim-group.gameTitle", "anim-group.clanPanel.clanCount",
        "anim-group.clanPanel.clanHealthy", "anim-group.clanPanel.clanHungry", "anim-group.clanPanel.clanSick"};
    static uint64_t PFM;
    if (!PFM) PFM = page_id("find-match-menu");
    int on_fm = PFM && top_page() == PFM;                // FINDING MATCH keeps its own MATCHMAKING title
    for (int k = on_fm ? 2 : 0; k < 6; k++) {
        if (!strcmp(t[k], last[k])) continue;
        uint64_t w = cw_w(W[k]);
        if (w) ((fn_settext_t)VMA(0x180064450))(w, t[k]);
        strcpy(last[k], t[k]);
    }
    static int last_need = -1;
    if (reset || force) last_need = -1;
    if (c->need != last_need) {
        char b[96];
        snprintf(b, sizeof b, "NEEDED PER DAY: <font color=\"#3fa9f5\">%d</font>", c->need);
        uint64_t w = cw_w("anim-group.clanPanel.clanNeeded");
        if (w) ((fn_settext_t)VMA(0x180064450))(w, b);
        last_need = c->need;
    }
    clan_dots(&g_cw.d, c, reset);
    mission_strip_tick(reset, force);
}
static void panel_hide(void) {
    if (!g_cw.panel) return;
    uint64_t panel = cw_w("anim-group.clanPanel");
    if (panel == g_cw.panel) { w_visible(panel, 0); w_visible(cw_w("anim-group.clanMission"), 0); }
    g_cw.panel = 0;
}

