// The table has a SECOND inserter (FUN at exe+0x13acea0..0x13ad1d0, the image-set / mip variant: same scan loop, lea r9 = table, ecx = free slot or 32,
// "movsxd rbx, ecx; xor edx, edx; shl rbx, 4; add rbx, r9" at exe+0x13ad16e). a5df55ce only bounded the first one, so build 91 crashed again at
// exe+0x13ac870 on the clan page (two reports; no "load table full" line was ever logged = the first inserter was never the one that overflowed).
// Same fix: ecx == 32 -> evict the oldest slot and continue with its index. rdx is dead at the hook (xor edx, edx follows), rbx is overwritten
// by the next original instruction, so rdx carries the jump and rbx the saved rsp (the function's stack alignment is not known: align dynamically).
static void gui2_slot_guard2(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *f = exe + 0x13ad16e;
    static const uint8_t P[12] = {0x48, 0x63, 0xd9, 0x33, 0xd2, 0x48, 0xc1, 0xe3, 0x04, 0x49, 0x03, 0xd9};
    if (memcmp(f, P, 12) || *(int32_t *)(exe + 0x13ad13d + 3) != (int32_t)(G2T_RVA - 0x13ad144)) { hook_miss(f, 12, "gui2 slot guard 2: code differs, not patched"); return; }
    uint8_t *s = VirtualAlloc(NULL, 128, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!s) return;
    static const uint8_t A[] = {
        0x83, 0xf9, 0x20,                               // 0  cmp ecx, 32
        0x75, 0x3e,                                     // 3  jne orig (67)
        0x50, 0x51, 0x52, 0x41, 0x50, 0x41, 0x51, 0x41, 0x52, 0x41, 0x53,   // 5  push rax rcx rdx r8 r9 r10 r11
        0x48, 0x89, 0xe3,                               // 16 mov rbx, rsp
        0x48, 0x83, 0xe4, 0xf0,                         // 19 and rsp, -16
        0x48, 0x83, 0xec, 0x20,                         // 23 sub rsp, 0x20
        0x48, 0xb9, 0, 0, 0, 0, 0, 0, 0, 0,             // 27 mov rcx, table
        0x49, 0xbb, 0, 0, 0, 0, 0, 0, 0, 0,             // 37 mov r11, gui2_slot_full
        0x41, 0xff, 0xd3,                               // 47 call r11
        0x48, 0x89, 0xdc,                               // 50 mov rsp, rbx
        0x89, 0x43, 0x28,                               // 53 mov [rbx+0x28], eax  (the saved rcx = the slot)
        0x41, 0x5b, 0x41, 0x5a, 0x41, 0x59, 0x41, 0x58, 0x5a, 0x59, 0x58,   // 56 pop r11 r10 r9 r8 rdx rcx rax
        0x48, 0x63, 0xd9, 0x33, 0xd2, 0x48, 0xc1, 0xe3, 0x04, 0x49, 0x03, 0xd9,   // 67 orig
        0x49, 0xba, 0, 0, 0, 0, 0, 0, 0, 0,             // 79 mov r10, f + 12 (dead: the next original call clobbers it)
        0x41, 0xff, 0xe2};                              // 89 jmp r10
    memcpy(s, A, sizeof A);
    *(uint64_t *)(s + 29) = (uint64_t)(exe + G2T_RVA);
    *(uint64_t *)(s + 39) = (uint64_t)gui2_slot_full;
    *(uint64_t *)(s + 81) = (uint64_t)(f + 12);
    DWORD old; VirtualProtect(f, 12, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0x48; f[1] = 0xba; *(uint64_t *)(f + 2) = (uint64_t)s; f[10] = 0xff; f[11] = 0xe2;   // mov rdx, stub; jmp rdx
    VirtualProtect(f, 12, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 12);
    xlog("gui2 slot guard 2: second image loader bounded too");
}
