// The match timer still flickered (clip: 9:05 -> one blank frame -> 9:04, every second). The banner on screen in a
// match is winmm's HUD copy (w_scoreBanner under canvas.hudRoot), and winmm writes ITS texts from a second updater, FUN_1800623d0 (the HUD
// block 0x180035386, every frame while not paused): allyLives / enemyLives / allyLabel / enemyLabel / matchTimer through
// FUN_1800677f0(leaf) = gui2-build-widget-path(w_scoreBanner, "fader", "teamPanel", leaf) - the same handles sb_w resolves - and a
// DIFFERENT settext, FUN_18000de90(handle, text). Only FUN_180064450 (the menu-stack copy's writes, FUN_180063020) was hooked, so the
// on-screen timer got winmm's raw write: a changed string blanks the text for a frame while its glyphs are rebuilt (the matchTimerB twin
// in the page was never used). Also why the lives writes were "never equal ours". Here FUN_18000de90 goes through the same banner
// routing (sb_route: on change only, into the hidden twin, swapped once built); every other caller passes straight through.
// t2r-no-hud-settext-twin.txt = off.
typedef void (*fn_hudtext_raw)(uint64_t, const char *);
static fn_hudtext_raw g_hudtext_tramp;
static void hudtext_hook(uint64_t w, const char *t) {
    if (t && !IsBadReadPtr(t, 1)) t = loc_tr(t);
    if (!g_settext_in && w && t && match_substate() == 6) {
        sb_resolve_tick();
        if (sb_route(w, t)) {
            static int n;
            if (n < 6 && w == g_sb[4].w) { n++; xlog("hud text twin: winmm's HUD timer write '%s' double-buffered (twin %s)", t, g_sb[4].b ? "yes" : "none - deduped only"); }
            return;
        }
    }
    g_hudtext_tramp(w, t);
}
static void install_hudtext_twin(void) {
    FILE *off = exe_side_open("t2r-no-hud-settext-twin.txt", "r");
    if (off) { fclose(off); xlog("hud text twin: off (t2r-no-hud-settext-twin.txt)"); return; }
    uint8_t *f = (uint8_t *)VMA(0x18000DE90);
    // push rsi; push rdi; push rbx; sub rsp, 0x230; mov rdi, rdx  (13 bytes, no rip-relative operand)
    static const uint8_t P[13] = {0x56, 0x57, 0x53, 0x48, 0x81, 0xec, 0x30, 0x02, 0x00, 0x00, 0x48, 0x89, 0xd7};
    if (memcmp(f, P, 13)) { hook_miss(f, 13, "hud text twin: FUN_18000de90 prologue differs, not hooked"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 13);
    t[13] = 0xff; t[14] = 0x25; *(uint32_t *)(t + 15) = 0; *(uint64_t *)(t + 19) = (uint64_t)(f + 13);
    g_hudtext_tramp = (fn_hudtext_raw)t;
    DWORD old; VirtualProtect(f, 13, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0x48; f[1] = 0xb8; *(uint64_t *)(f + 2) = (uint64_t)hudtext_hook; f[10] = 0xff; f[11] = 0xe0; f[12] = 0x90;   // mov rax, hook; jmp rax; nop
    VirtualProtect(f, 13, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 13);
    xlog("hud text twin: winmm HUD settext FUN_18000de90 hooked (in-match timer / lives double-buffered)");
}
// Crash
// cover ik: ...".
