static fn_hik g_hik_tramp;
static void hik_hook(void *self, float dt, const float *loc, void *cover, float w) {
    int bad = !loc || IsBadReadPtr(loc, 32);
    for (int i = 0; !bad && i < 8; i++) bad |= !(__builtin_fabsf(loc[i]) < 1e6f);
    if (bad) {
        static int n;
        if (LOGCAP(n, 20)) xlog("cover ik: non-finite hand locator - hand IK skipped this frame (NaN ray crash guard)");
        return;
    }
    g_hik_tramp(self, dt, loc, cover, w);
}
