// MeshRayCaster::CastRayJob (exe 0x1415b2100..): the engine's own int3 on a NaN start / end ('User pass a NaN start pos to
// MeshRayCaster, check callstack!'). 3 crash dumps (no stack in them) - the ray comes from engine code (puppet /
// NPC probes), not from our kicks (those are guarded by ray_bad). The two non-finite branches are redirected: the bad point is
// replaced by (0, -10000, 0) - a ray far below the world that hits nothing - and the job carries on. Counted in g_nan_rays.
static volatile LONG g_nan_rays;
static void install_nan_ray_guard(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    static const struct { uint32_t site, back, slot; } S[2] = {{0x15b2204, 0x15b2291, 0x2b0}, {0x15b22c7, 0x15b2354, 0x2c0}};
    static const uint8_t pre1[] = {0x0f, 0x84, 0x95, 0x00, 0x00, 0x00};      // je +0x95 (start finite) right before site 1
    static const uint8_t pre2[] = {0x0f, 0x84, 0x8d, 0x00, 0x00, 0x00};      // je +0x8d (end finite) right before site 2
    if (memcmp(exe + 0x15b21fe, pre1, 6) || memcmp(exe + 0x15b22c1, pre2, 6) || exe[0x15b2204] != 0xe8 || exe[0x15b22c7] != 0xe8 ||
        exe[0x15b2287] != 0xcc) { hook_fail("nan ray guard: CastRayJob bytes differ, not installed"); return; }
    uint8_t *cave = VirtualAlloc(NULL, 256, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!cave) return;
    for (int k = 0; k < 2; k++) {
        uint8_t *c = cave + k * 96, *q = c;
        uint32_t o = S[k].slot, vals[3] = {0, 0xC61C4000u /* -10000.0f */, 0};
        for (int i = 0; i < 3; i++) {                                  // mov dword [rsp + slot + 4i], v
            *q++ = 0xc7; *q++ = 0x84; *q++ = 0x24; *(uint32_t *)q = o + 4 * i; q += 4; *(uint32_t *)q = vals[i]; q += 4;
        }
        *q++ = 0x48; *q++ = 0xb8; *(uint64_t *)q = (uint64_t)&g_nan_rays; q += 8;   // mov rax, &g_nan_rays
        *q++ = 0xf0; *q++ = 0xff; *q++ = 0x00;                                       // lock inc dword [rax]
        *q++ = 0xff; *q++ = 0x25; *(uint32_t *)q = 0; q += 4; *(uint64_t *)q = (uint64_t)(exe + S[k].back); q += 8;
        uint8_t *f = exe + S[k].site;
        DWORD old; VirtualProtect(f, 14, PAGE_EXECUTE_READWRITE, &old);
        f[0] = 0xff; f[1] = 0x25; *(uint32_t *)(f + 2) = 0; *(uint64_t *)(f + 6) = (uint64_t)c;
        VirtualProtect(f, 14, old, &old);
        FlushInstructionCache(GetCurrentProcess(), f, 14);
    }
    xlog("nan ray guard: installed (a non-finite ray start / end is replaced, no int3)");
}
