        *q++ = 0xf0; *q++ = 0xff; *q++ = 0x00;                                        // lock inc dword [rax]
        *q++ = 0xff; *q++ = 0x25; *(uint32_t *)q = 0; q += 4; *(uint64_t *)q = (uint64_t)(exe + S[k].back); q += 8;
