static void install_adelta_guard(void) {
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL), *f = exe + 0xaefc40;
    // mov rax,rsp; mov [rax+10h],rbx; push rsi; push rdi; push r12; push r14; push r15 (15 bytes, no rip-relative operand)
    static const uint8_t P[15] = {0x48, 0x8b, 0xc4, 0x48, 0x89, 0x58, 0x10, 0x56, 0x57, 0x41, 0x54, 0x41, 0x56, 0x41, 0x57};
    static const uint8_t CALL[5] = {0xe8, 0xcb, 0x05, 0xd2, 0xff};   // exe+dcf670: call 0x140aefc40 (its only caller, the player anim-delta step)
    if (memcmp(f, P, 15) || memcmp(exe + 0xdcf670, CALL, 5)) { hook_miss(f, 15, "anim delta guard: 0x140aefc40 prologue / caller differs, not installed"); return; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return;
    memcpy(t, f, 15);
    t[15] = 0xff; t[16] = 0x25; *(uint32_t *)(t + 17) = 0; *(uint64_t *)(t + 21) = (uint64_t)(f + 15);
    g_adelta_tramp = (fn_adelta)t;
    DWORD old; VirtualProtect(f, 15, PAGE_EXECUTE_READWRITE, &old);
    f[0] = 0xff; f[1] = 0x25; *(uint32_t *)(f + 2) = 0; *(uint64_t *)(f + 6) = (uint64_t)adelta_hook;
    f[14] = 0x90;
    VirtualProtect(f, 15, old, &old);
    FlushInstructionCache(GetCurrentProcess(), f, 15);
    xlog("anim delta guard: installed (a player anim / move delta to a non-finite target or one outside +-%.0f m is refused before the locomotion uses it; teleports inside the world pass)", (double)ANIMDELTA_WORLD_M);
}
