uint8_t g_rcam_cap;                     // read by the asm thunk: capture the render camera every frame
uint8_t g_mcam_watch;                   // read by the asm thunk: MP menu camera filter (feature_menu_cam)
void *g_icam_tramp;                     // FUN_141477750 trampoline (asm thunk jumps here)
static uint8_t *volatile g_icam_mgr;    // local player's camera manager
static int64_t g_icam_q0, g_icam_qf;    // QueryPerformanceCounter at the intro start, frequency
static float g_icam_anchor[3], g_icam_dir[3], g_icam_gdir[3];
static volatile float g_icam_scale = 1.0f;   // last spring-arm target (log)
// spring arm (the camera clipped through the map): every 2 frames rays from above the
// team's heads to the shot position (+ two 0.4 m side rays for the near plane, + one straight up
// for ceilings); the camera sits at head + (shot - head) * arm, arm eased toward the free fraction
// minus 0.35 m (pull-in fast, push-out slow). Arm < 1.5 m: the swoop into the gameplay camera starts
// right away (g_icam_swoop).
static volatile float g_icam_arm = 1.0f, g_icam_arm_tgt = 1.0f, g_icam_ceil = 1e9f;
static volatile float g_icam_swoop = 3650.0f;   // ms: swoop start (ICAM_SWOOP_FROM or earlier)
#define ICAM_HEAD 1.6f                  // ray origin: the team anchor's eye height ...
#define ICAM_HEAD_BACK 0.5f             // ... 0.5 m back toward the camera
static volatile int g_icam_sign;        // camera forward axis: +1 = +Z, -1 = -Z, 0 = not checked yet
static volatile int g_icam_fail;        // the filter gave up (reason code, logged by the tick)
static volatile uint32_t g_icam_hits[2];
static volatile float g_icam_gpos[3];   // game camera position seen by the filter (log)
static volatile float g_icam_trace[60][7];   // ms, rendered xyz, game xyz (first 60 frames)
static volatile int g_icam_trace_n;
#define ICAM_WIDE_FROM 450              // ms from the intro start: fade starts (clip 0.85 s)
// DECODED from the 2013 EBOOT's ss-respawn-intro script (re/factions2013/intro-camera-2013.md): camera-enable x2,
// wait 3.0, camera-disable, wait 0.1, camera-fade-out 1.0 s, wait 0.25, control given. From the camera start
// (ICAM_WIDE_FROM): fade-out (our swoop) at +3.1 s, lasting 1.0 s; the player gets control at +3.35 s.
#define ICAM_SWOOP_FROM (ICAM_WIDE_FROM + 3100)   // swoop into the gameplay camera = 2013 camera-fade-out call
#define ICAM_SWOOP_MS 1000                        // 2013 camera-fade-out 1.0 s (curve inferred: smootherstep, ~0.6 s visible = clip 0.55-0.6 s)
#define ICAM_CTRL (ICAM_WIDE_FROM + 3350)         // 2013: control given 0.25 s after the fade-out call
#define ICAM_MAX_UP 3.5f                // m above the team anchor, never higher
#define ICAM_ARM0 0.55f                 // spring arm before the first ray result (eases out from here)
#define ICAM_END (ICAM_SWOOP_FROM + ICAM_SWOOP_MS)
#define RVA_RCAM_SET 0x1477750          // FUN_141477750(RenderCamera*, CameraLocation*, ...)
__asm__(
    ".text\n"
    ".globl t2r_icam_thunk\n"
    "t2r_icam_thunk:\n"
    "    cmpb $0, g_icam_on(%rip)\n"
    "    jne 2f\n"
    "    cmpb $0, g_rcam_cap(%rip)\n"        // (on once installed: the render camera is captured for the 3D audio listener, rcam_capture)
    "    je 1f\n"
    "2:  push %rcx\n"
    "    push %rdx\n"
    "    push %r8\n"
    "    push %r9\n"
    "    sub $0x68, %rsp\n"
    "    movdqu %xmm0, 0x20(%rsp)\n"
    "    movdqu %xmm1, 0x30(%rsp)\n"
    "    movdqu %xmm2, 0x40(%rsp)\n"
    "    movdqu %xmm3, 0x50(%rsp)\n"
    "    call icam_filter\n"
    "    movdqu 0x20(%rsp), %xmm0\n"
    "    movdqu 0x30(%rsp), %xmm1\n"
    "    movdqu 0x40(%rsp), %xmm2\n"
    "    movdqu 0x50(%rsp), %xmm3\n"
    "    add $0x68, %rsp\n"
    "    pop %r9\n"
    "    pop %r8\n"
    "    pop %rdx\n"
    "    pop %rcx\n"
    "    mov %rax, %rdx\n"
    "1:  jmp *g_icam_tramp(%rip)\n");
void t2r_icam_thunk(void);
static void q_rot(const float *q, const float *v, float *o) {     // o = q v q*
    float tx = 2.0f * (q[1] * v[2] - q[2] * v[1]), ty = 2.0f * (q[2] * v[0] - q[0] * v[2]), tz = 2.0f * (q[0] * v[1] - q[1] * v[0]);
    o[0] = v[0] + q[3] * tx + (q[1] * tz - q[2] * ty);
    o[1] = v[1] + q[3] * ty + (q[2] * tx - q[0] * tz);
    o[2] = v[2] + q[3] * tz + (q[0] * ty - q[1] * tx);
}
// The game's render camera, captured every frame by the render-camera hook (the thunk now always routes here): position + forward
// of the main view AFTER our own filters (so a scripted execution camera is what the listener hears from). The forward axis of the
// camera quaternion is +Z (xcam / intro cam calibration, "sign 1"). rcam_get: 0 = nothing fresh (older than 300 ms).
static volatile float g_rcam_pos[3], g_rcam_fwd[3];
static volatile uint32_t g_rcam_seq;
static volatile uint64_t g_rcam_t;
static int rcam_get(float *pos, float *fwd) {
    for (int tries = 0; tries < 4; tries++) {
        uint32_t s0 = g_rcam_seq;
        if ((s0 & 1) || !g_rcam_t) continue;
        float p[3] = {g_rcam_pos[0], g_rcam_pos[1], g_rcam_pos[2]}, f[3] = {g_rcam_fwd[0], g_rcam_fwd[1], g_rcam_fwd[2]};
        uint64_t t = g_rcam_t;
        if (s0 != g_rcam_seq) continue;
        if (GetTickCount64() - t > 300) return 0;
        memcpy(pos, p, 12); memcpy(fwd, f, 12);
        return 1;
    }
    return 0;
}
static uint8_t *icam_manager(void);
static void rcam_capture(const uint8_t *dst, const float *r) {
    uint8_t *m = icam_manager();
    if (!m || dst != m + 0x130 || !r || IsBadReadPtr(r, 32)) return;
    const float *q = r + 4;
    float ql = q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3];
    if (!(__builtin_fabsf(r[0]) < 1e6f) || !(__builtin_fabsf(r[2]) < 1e6f) || !(__builtin_fabsf(r[1]) < 1e6f) || !(ql > 0.9f && ql < 1.1f)) return;
    static const float Z[3] = {0, 0, 1};
    float f[3];
    q_rot(q, Z, f);
    g_rcam_seq++;
    g_rcam_pos[0] = r[0]; g_rcam_pos[1] = r[1]; g_rcam_pos[2] = r[2];
    g_rcam_fwd[0] = f[0]; g_rcam_fwd[1] = f[1]; g_rcam_fwd[2] = f[2];
    g_rcam_t = GetTickCount64();
    g_rcam_seq++;
}
static void q_from_basis(const float *X, const float *Y, const float *Z, float *q) {   // columns X Y Z
    float m00 = X[0], m10 = X[1], m20 = X[2], m01 = Y[0], m11 = Y[1], m21 = Y[2], m02 = Z[0], m12 = Z[1], m22 = Z[2];
    float tr = m00 + m11 + m22, s;
    if (tr > 0) { s = __builtin_sqrtf(tr + 1.0f) * 2.0f; q[3] = 0.25f * s; q[0] = (m21 - m12) / s; q[1] = (m02 - m20) / s; q[2] = (m10 - m01) / s; }
    else if (m00 > m11 && m00 > m22) { s = __builtin_sqrtf(1.0f + m00 - m11 - m22) * 2.0f; q[3] = (m21 - m12) / s; q[0] = 0.25f * s; q[1] = (m01 + m10) / s; q[2] = (m02 + m20) / s; }
    else if (m11 > m22) { s = __builtin_sqrtf(1.0f + m11 - m00 - m22) * 2.0f; q[3] = (m02 - m20) / s; q[0] = (m01 + m10) / s; q[1] = 0.25f * s; q[2] = (m12 + m21) / s; }
    else { s = __builtin_sqrtf(1.0f + m22 - m00 - m11) * 2.0f; q[3] = (m10 - m01) / s; q[0] = (m02 + m20) / s; q[1] = (m12 + m21) / s; q[2] = 0.25f * s; }
}
static float icam_smooth(float x) { x = x < 0 ? 0 : x > 1 ? 1 : x; return x * x * (3.0f - 2.0f * x); }
// 2013 camera SPEED profiles (ours felt "binary" - a near-still wide shot, then a jump), measured off factionsclip.mp4 with
// optical flow (median px / frame at 320x180, camera motion only): {ms, speed}. Progress = the integral of the speed, normalised to 1.
// Wide shot (ms from ICAM_WIDE_FROM = the fade start): still for 0.5 s, ramps up over 0.7 s, a steady drift to 2 s, then slows to
// ~55 % by the fade-out call and keeps drifting under the swoop (not measurable there: eased to 0 at the swoop's end).
static const float ICAM_V_WIDE[][2] = {{0, 0}, {500, 0.02f}, {600, 0.07f}, {700, 0.18f}, {800, 0.55f}, {900, 0.84f}, {1000, 1.13f},
    {1100, 1.35f}, {1200, 1.46f}, {1400, 1.57f}, {2000, 1.48f}, {2300, 1.31f}, {2600, 1.13f}, {2900, 0.92f}, {3100, 0.85f},
    {3400, 0.6f}, {4100, 0.0f}};
// Swoop into the gameplay camera (ms from the fade-out call; the wide drift subtracted): slow first 0.15 s, accelerating to its peak at
// ~0.5 s, then a short hard settle - the whole visible move is 0.7 s of the 1.0 s camera-fade-out
static const float ICAM_V_SWOOP[][2] = {{0, 0}, {100, 0.25f}, {200, 2.4f}, {300, 6.9f}, {400, 9.4f}, {500, 11.0f}, {600, 4.2f}, {700, 0.0f}};
static float icam_prof(const float (*v)[2], int n, float x) {
    float tot = 0, acc = 0;
    for (int i = 1; i < n; i++) {
        float a = v[i - 1][0], b = v[i][0], seg = (v[i - 1][1] + v[i][1]) * 0.5f * (b - a);
        tot += seg;
        if (x >= b) acc += seg;
        else if (x > a) { float u = (x - a) / (b - a), vx = v[i - 1][1] + (v[i][1] - v[i - 1][1]) * u; acc += (v[i - 1][1] + vx) * 0.5f * (x - a); }
    }
    return tot > 0 ? acc / tot : 1.0f;
}
#define ICAM_PROF(tab, x) icam_prof(tab, (int)(sizeof tab / sizeof *tab), x)
static float icam_ms(void) {
    LARGE_INTEGER q;
    QueryPerformanceCounter(&q);
    return g_icam_qf ? (float)((double)(q.QuadPart - g_icam_q0) * 1000.0 / (double)g_icam_qf) : 0.0f;
}
// the shot at time t (ms): camera position + look target, before the swoop
static void icam_shot(float t, float sc, float *cam, float *tgt) {
    float w = ICAM_PROF(ICAM_V_WIDE, t - ICAM_WIDE_FROM);       // the 2013 drift speed (keeps moving under the swoop)
    // kept inside the level's volume (the first ~0.85 s of A's shot, 6+ m back / 5 m
    // up, rendered nothing but the character - likely out of the region's bounds): 4.5 m back /
    // 3.4 m up (~29 deg down) easing to 4.6 / 2.6 (~14 deg), height never above ICAM_MAX_UP
    float back = (4.5f + (4.6f - 4.5f) * w) * sc, up = (3.4f + (2.6f - 3.4f) * w) * sc;
    float ahead = 1.0f + (3.5f - 1.0f) * w, look = 0.3f + (0.6f - 0.3f) * w;
    if (up > ICAM_MAX_UP) up = ICAM_MAX_UP;
    const float *a = g_icam_anchor, *d = g_icam_dir;
    cam[0] = a[0] - d[0] * back; cam[1] = a[1] + up; cam[2] = a[2] - d[2] * back;
    tgt[0] = a[0] + d[0] * ahead; tgt[1] = a[1] + look; tgt[2] = a[2] + d[2] * ahead;
}
// the shot with the ceiling cap (raw) and with the spring arm applied
static void icam_raw(float t, float *cam, float *tgt) {
    icam_shot(t, 1.0f, cam, tgt);
    float hy = g_icam_anchor[1] + ICAM_HEAD, cy = g_icam_ceil;
    if (cam[1] > cy) cam[1] = cy > hy ? cy : hy;
}
static void icam_armed(float t, float *cam, float *tgt) {
    icam_raw(t, cam, tgt);
    float h[3] = {g_icam_anchor[0] - g_icam_dir[0] * ICAM_HEAD_BACK, g_icam_anchor[1] + ICAM_HEAD, g_icam_anchor[2] - g_icam_dir[2] * ICAM_HEAD_BACK}, a = g_icam_arm;
    for (int i = 0; i < 3; i++) cam[i] = h[i] + (cam[i] - h[i]) * a;
}
// MP menu camera (feature_menu_cam): records the game's menu camera (manager+0x130 build) and,
// when g_mcam_on, renders ours instead (position + quaternion; the rest of the location as is)
static uint8_t *volatile g_mcam_mgr;
static volatile int g_mcam_on;
static volatile float g_mcam_pos[3], g_mcam_q[4];
static volatile float g_mcam_seen[16];     // last game camera location (pos vec4, quat, +0x20..)
static volatile uint32_t g_mcam_hits, g_mcam_done;
static int g_ms_show_player;               // t2r-menu-show-player.txt: don't hide the menu world's player
static int g_cz_cam_on;                    // customize.c (CUSTOMIZE page up): the menu camera looks at the menu world's player (the live model)
static float g_cz_cam[6];                  //   its pose: x y z yaw pitch fov (feature_menu_cam takes it over every pose but the F9 edit)
static int g_ms_pose_on;                   // feature_menu_cam has a pose this frame (g_ms_pose: x y z yaw pitch fov)
static float g_ms_pose[6];
