static volatile float g_xcam_pos[3], g_xcam_look[3], g_xcam_w, g_xcam_gdir[3];
static volatile float g_xcam_piv[3]; static volatile int g_xcam_piv_ok, g_xcam_out;   // blend-out orbit pivot (our head) / blend-out phase
static volatile float g_xcam_gfwd[3];    // the game's own render camera forward (live, before our override): the victim camera's yaw source
static volatile int g_xcam_gfwd_ok, g_xcam_axis_fail;
static volatile float g_xcam_gpos[3];     // the game's render camera position at the first filtered frame (T1 start 0x2c1340: theta = yaw(root -> camera))
static volatile int g_xcam_gpos_ok;       // 0 none, 1 captured (render thread), 2 used (xcam_tick)
