        int inside = 0;
        for (int i = 0; i < n; i++) if (xcam_seg_dist(C, cap[i].a, cap[i].b) < cap[i].r) { inside = 1; break; }
        if (!inside) break;
        for (int i = 0; i < 3; i++) C[i] += dir[i] * 0.05f;
