static double g_xcam_ms0;     // psync_ms() at the start: the blend weights run on this (high resolution), not on the 1/60 s ticks
static int g_xcam_iw;         // the fist interrogation's camera: the authored track runs on CLIP time, the slowed hold (intwarp.c) stretches real time
static float g_xcam_trk_off;  // s added to the authored track's clock (ctxdown: a takedown that starts into its push / intro; 0 for everything else)
static int g_xcam_ray_state, g_xcam_off = -1, g_xcam_role = 1, g_xcam_snap, g_xcam_scope, g_xcam_scope_free;   // scope = the window (native ADS or free close-up); scope_free = the free close-up is allowed
static uint64_t g_xcam_miss;     // g_t60 when a body first went missing (0 = none)
static float g_xcam_kill, g_xcam_sc;   // kill time (s) of the pair; scope close-up blend 0..1 (hunting rifle / sniper attacker)
static char g_xcam_name[48];
static int g_xcam_shiv;          // the pair is a 2013 shiv kill (logs "xcam shiv:")
