static void q_rot(const float *q, const float *v, float *o);
static uint64_t world_ray_kick(const float *a, const float *b);
static float ray_t(uint64_t job);
static int xcam_cam_ix(const xcam_track *t) { return t && t->cam ? t->cam : 1; }
static int xcam_preferred(const xcam_track *t) { return t && (t->pref >> xcam_cam_ix(t) & 1); }
// a track's camera / look point / owner align at move time t in world space (1 = ok)
static float g_xcam_ap[7]; static int g_xcam_ap_ok;      // the pair's ap, latched once: psync ends at the clip's end, the camera
                                                          // runs on through its 1.5 s blend-out on the same ap (no mode switch)
static int xcam_track_eval_o(const xcam_track *tr, float t, float *cam, float *look, float *fov, float *roll, float *own) {
    if (!tr || tr->n < 1) return 0;
    if (!g_xcam_ap_ok) { if (!psync_ap(g_xcam_ap)) return 0; g_xcam_ap_ok = 1; }
    const float *ap = g_xcam_ap;
    int i = 0;
    while (i + 1 < tr->n && tr->k[i + 1].t <= t) i++;
    const xcam_key *a = &tr->k[i], *b = &tr->k[i + 1 < tr->n ? i + 1 : i];
    float u = b->t > a->t ? (t - a->t) / (b->t - a->t) : 0.0f;
    u = u < 0.0f ? 0.0f : u > 1.0f ? 1.0f : u;
    float c[3], l[3], o[3], wc[3], wl[3], wo[3];
    for (int j = 0; j < 3; j++) {
        c[j] = a->cam[j] + (b->cam[j] - a->cam[j]) * u; l[j] = a->look[j] + (b->look[j] - a->look[j]) * u;
        o[j] = a->own[j] + (b->own[j] - a->own[j]) * u;
    }
    q_rot(ap + 3, c, wc); q_rot(ap + 3, l, wl); q_rot(ap + 3, o, wo);
    for (int j = 0; j < 3; j++) { cam[j] = ap[j] + wc[j]; look[j] = ap[j] + wl[j]; if (own) own[j] = ap[j] + wo[j]; }
    *fov = a->fov + (b->fov - a->fov) * u;
    // the 2013 scoped-in period (hunting rifle, 70 mm key = 28.8 deg) is REMOVED: no zoom, the authored camera track goes on at the normal FOV
    if (*fov < tr->k[0].fov * 0.9f) *fov = tr->k[0].fov;      // (a zoom key = more than 10 % tighter than the track's own opening FOV)
    if (roll) *roll = a->roll + (b->roll - a->roll) * u;
    return 1;
}
static int xcam_track_eval_k(const xcam_track *tr, float t, float *cam, float *look, float *fov, float *roll) {
    return xcam_track_eval_o(tr, t, cam, look, fov, roll, NULL);
}
// pull-out hand-off (melee_pullout.c pul_cam_swap): the drag pair's camera runs on into the outcome pair's - a NEW ap (the outcome pair is solved on the victim's body where the drag left it,
// ~0.2 m / 29 deg off the drag's ap) and a new track, so the shot is crossfaded from the last output pose over XPH_S (smoothstep, real time) instead of cutting
#define XPH_S 0.40
static struct { int on, last_ok; double t0; float c[3], l[3], f, r; float lc[3], ll[3], lf, lr; } g_xph;
static int xcam_track_eval(float t, float *cam, float *look, float *fov) {
    float r = 0.0f;
    if (g_xcam_iw) t = (float)(iw_clip_ms((double)t * 1000.0) / 1000.0);
    int ok = xcam_track_eval_k(g_xcam_trk, t + g_xcam_trk_off, cam, look, fov, &r);
    if (ok && g_xph.on) {
        double u = (psync_ms() - g_xph.t0) * (1.0 / XPH_S);
        if (u >= 1.0) g_xph.on = 0;
        else {
            float w = u <= 0.0 ? 0.0f : (float)u; w = w * w * (3.0f - 2.0f * w);
            for (int i = 0; i < 3; i++) { cam[i] = g_xph.c[i] + (cam[i] - g_xph.c[i]) * w; look[i] = g_xph.l[i] + (look[i] - g_xph.l[i]) * w; }
            *fov = g_xph.f + (*fov - g_xph.f) * w; r = g_xph.r + (r - g_xph.r) * w;
        }
    }
    if (ok) { memcpy(g_xph.lc, cam, 12); memcpy(g_xph.ll, look, 12); g_xph.lf = *fov; g_xph.lr = r; g_xph.last_ok = 1; }
    g_xcam_roll = ok ? r : 0.0f;
    return ok;
}
static int g_xcam_shivatk;       // the running attacker camera is a stealth shiv kill's authored 2013 track (xcam_tracks_shiv.h)
static void xcam_track_pick(const char *name, int role) {
    // (there should be a cinematic camera for both, with SP's framing of the face): the victim of a duel finisher shows the ATTACKER's authored
    // shot - the track is relative to the pair's shared apReference (psync_ap), so it is the same world camera the attacker sees. t2r-fin-victim-duel-cam.txt = old.
    int trole = role;
    if (role == 2 && name && !strncmp(name, "ctxdown:mf-", 11) && !xcam_side_flag("t2r-fin-victim-duel-cam.txt")) trole = 1;
    if (role == 2 && name && !strncmp(name, "ctxdown:pu-", 11)) trole = 1;      // the prone pull-out: SP's player-half shot, in the pair's ap space - the same world camera for both screens (melee_pullout.c)
    g_xcam_trk = NULL; g_xcam_ncand = 0; g_xcam_choice_state = 2; g_xcam_roll = 0.0f; g_xcam_nrq = 0; g_xcam_ap_ok = 0;
    if (role == 2 && (g_xv_framing || g_xcam_shivcine)) return;      // victim: t2r-xcam-victim-framing.txt = our pair-framing camera instead of 2013's (shiv: the cinematic framing, g_xcam_shivcine)
#if defined(XCAM_HAVE_TRACKS) || defined(XCAM_HAVE_PS4) || defined(XCAM_HAVE_SHIVATK) || defined(XCAM_HAVE_INT)
#ifdef XCAM_HAVE_INT
    if (name && strstr(name, "interrogate-enter") && !xcam_side_flag("t2r-no-int-cam.txt"))
        for (size_t i = 0; i < sizeof XCAM_TRACKS_INT / sizeof XCAM_TRACKS_INT[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
            if (XCAM_TRACKS_INT[i].move && !strcmp(XCAM_TRACKS_INT[i].move, name) && XCAM_TRACKS_INT[i].role == trole)
                g_xcam_cands[g_xcam_ncand++] = &XCAM_TRACKS_INT[i];
#endif
#ifdef XCAM_HAVE_TRACKS
    for (size_t i = 0; i < sizeof XCAM_TRACKS / sizeof XCAM_TRACKS[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
        if (XCAM_TRACKS[i].move && name && !strcmp(XCAM_TRACKS[i].move, name) && XCAM_TRACKS[i].role == trole)
            g_xcam_cands[g_xcam_ncand++] = &XCAM_TRACKS[i];
#endif
#ifdef XCAM_HAVE_PS4
    for (size_t i = 0; i < sizeof XCAM_TRACKS_PS4 / sizeof XCAM_TRACKS_PS4[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
        if (XCAM_TRACKS_PS4[i].move && name && !strcmp(XCAM_TRACKS_PS4[i].move, name) && XCAM_TRACKS_PS4[i].role == trole)
            g_xcam_cands[g_xcam_ncand++] = &XCAM_TRACKS_PS4[i];
#endif
#ifdef XCAM_HAVE_SHIVATK
    g_xcam_shivatk = 0;
    if (role == 1 && name && !xcam_side_flag("t2r-no-shiv-atk-cam.txt"))
        for (size_t i = 0; i < sizeof XCAM_TRACKS_SHIV / sizeof XCAM_TRACKS_SHIV[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
            if (XCAM_TRACKS_SHIV[i].move && !strcmp(XCAM_TRACKS_SHIV[i].move, name) && XCAM_TRACKS_SHIV[i].role == trole) {
                g_xcam_cands[g_xcam_ncand++] = &XCAM_TRACKS_SHIV[i]; g_xcam_shivatk = 1;
            }
#endif
    for (int i = 1; i < g_xcam_ncand; i++)      // by camera index (2013 scans 1..8; ties keep the earlier one)
        for (int j = i; j > 0 && xcam_cam_ix(g_xcam_cands[j]) < xcam_cam_ix(g_xcam_cands[j - 1]); j--) {
            const xcam_track *x = g_xcam_cands[j]; g_xcam_cands[j] = g_xcam_cands[j - 1]; g_xcam_cands[j - 1] = x;
        }
    if (g_xcam_ncand) { g_xcam_trk = g_xcam_cands[0]; g_xcam_choice_state = 0; g_xcam_ray_next = -1; }
#else
    (void)name; (void)role;
#endif
#ifdef XCAM_HAVE_CTX
    for (size_t i = 0; i < sizeof CTX_XCAM_TRACKS / sizeof CTX_XCAM_TRACKS[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
        if (CTX_XCAM_TRACKS[i].move && name && !strcmp(CTX_XCAM_TRACKS[i].move, name) && CTX_XCAM_TRACKS[i].role == trole)
            g_xcam_cands[g_xcam_ncand++] = &CTX_XCAM_TRACKS[i];
#ifdef XCAM_HAVE_PESC
    for (size_t i = 0; i < sizeof PESC_XCAM_TRACKS / sizeof PESC_XCAM_TRACKS[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
        if (PESC_XCAM_TRACKS[i].move && name && !strcmp(PESC_XCAM_TRACKS[i].move, name) && PESC_XCAM_TRACKS[i].role == trole)
            g_xcam_cands[g_xcam_ncand++] = &PESC_XCAM_TRACKS[i];
#endif
#ifdef XCAM_HAVE_PUL
    for (size_t i = 0; i < sizeof PUL_XCAM_TRACKS / sizeof PUL_XCAM_TRACKS[0] && g_xcam_ncand < XCAM_MAX_CANDS; i++)
        if (PUL_XCAM_TRACKS[i].move && name && !strcmp(PUL_XCAM_TRACKS[i].move, name) && PUL_XCAM_TRACKS[i].role == trole)
            g_xcam_cands[g_xcam_ncand++] = &PUL_XCAM_TRACKS[i];
#endif
    if (g_xcam_ncand && !g_xcam_trk) {
        for (int i = 1; i < g_xcam_ncand; i++)
            for (int j = i; j > 0 && xcam_cam_ix(g_xcam_cands[j]) < xcam_cam_ix(g_xcam_cands[j - 1]); j--) {
                const xcam_track *x = g_xcam_cands[j]; g_xcam_cands[j] = g_xcam_cands[j - 1]; g_xcam_cands[j - 1] = x;
            }
        g_xcam_trk = g_xcam_cands[0]; g_xcam_choice_state = 0; g_xcam_ray_next = -1;
    }
#endif
}
// the same segment kicked both ways from ONE pair of locators (one camera-locator read per batch, not per ray): a static-world ray does
// not hit a surface it starts inside or a face seen from behind, so a camera placed inside / behind a wall passes C -> X untouched (A/B
// B 172503: the bomb-downed victim lay against a wall, camera 4 sat 0.2 m behind the wall face its neighbours' rays hit at
// x -111.46 - chosen with 0 blocked rays, the victim watched the inside of the wall). X -> C hits that wall from the open side.
static int xcam_kick_both(const float *a, const float *b, uint64_t cam, const float *c, const float *q, uint64_t *jf, uint64_t *jr) {
    *jf = *jr = 0;
    for (int i = 0; i < 3; i++) if (!(__builtin_fabsf(a[i]) < 1e7f) || !(__builtin_fabsf(b[i]) < 1e7f)) return 0;     // NaN ray crash guard
    uint64_t la = loc_at(cam, c, q, a), lb = loc_at(cam, c, q, b);
    if (!la || !lb) return 0;
    uint64_t f[4] = {la, lb, SID_PLAYER, g_world_ray_mask}, r[4] = {lb, la, SID_PLAYER, g_world_ray_mask};
    uint64_t j = dc_call(0x45d27e0a200ebe59ULL /* kick-raycast */, 4, f);
    *jf = j == ~0ULL ? 0 : j;
    j = dc_call(0x45d27e0a200ebe59ULL /* kick-raycast */, 4, r);
    *jr = j == ~0ULL ? 0 : j;
    return *jf || *jr;
}
// 2013's camera choice (melee chooser 0x5fd840, exec-cameras.md):
//  base at frame 0: victim 1.0; attacker cos(angle between the candidate's view and the gameplay camera's view) (-dot(candidate +Z,
//    live camera +Z), +Z = -view for the authored camera), a candidate with base < 0 dropped;
//  rays, asynchronous: per candidate per source frame (XCAM_RAY_HZ over the track): from the camera C toward X = the point on its
//    view line nearest the screen owner's align at that frame, stopping 0.2 m short; ANY hit (except our own collision: the ray
//    ignores SID_PLAYER) drops the candidate; ours also casts X -> C (a camera inside / behind a wall: see xcam_kick_both) and keeps
//    testing a dropped candidate's frames, counting its blocked frames;
//  winner = argmax over the survivors of base + 100 if preferred, strict '>' (ties keep the lower index); none = no animated
//    camera (the procedural fallback). Nothing is shown until it is decided (2013 too starts the camera frames after the move).
//    No survivor / attacker side rule: the candidate with the FEWEST blocked frames, then base + 100 if preferred.
#define XCAM_LENS_BODY 0.55f     // v5-cam7: a body this close in front of the lens covers the shot
#define XCAM_SIDE_BASE 0.30f     // v5-cam7: the attacker right-side rule keeps a right camera only this close to the gameplay view (tester pipe-execute-left cam2 0.36 R still kept)
#define XCAM_TOPDOWN_DEG -58.0f  // v5-fb2: an attacker camera looking down steeper than this at any frame = a top-down shot over his head (never used)
#define XCAM_PREF_BASE 0.45f    // v5-cam7: the 2013 preferred-camera bonus (+100) / the attacker right-side rule need a view at least this close to the gameplay view
static int g_xcam_nrays_lens;
static int xcam_pref_ok(int i) { return xcam_preferred(g_xcam_cands[i]) && g_xcam_cand_base[i] >= XCAM_PREF_BASE; }
// ps41 V (A 16.13-18.3 s: 9856 'exec cam: ctxdown:mf-fist-right-haymaker-kill role 1: 2013 AUTHORED camera (..., 2 candidates ...)', the victim
// behind our own back + a pillar over 40 % of the frame, 9940 'ps25 frame check ... the PARTNER HIDDEN behind our own body / geometry'; A 118.47-119.70
// mf-machete-slash-5-finisher the same): the chooser's rays run lens -> the look axis and treat both bodies as the subject - a track whose lens stands
// behind OUR back with the victim on the far side of us, or with a pillar between the lens and the victim, survived. For the attacker of a takedown /
// finisher (ctxdown:) every candidate's first S41V_T s is now also tested lens -> the VICTIM's head: our own torso capsule (root -> head, 0.30 m) on that
// line, else a world ray (the victim ignored: geometry or our own body). The bodies are taken where they stand at the choice (weight 0, the move's
// start) - their later clip placement is not sampled. A candidate hidden on more than S41V_MAX of those samples is not used by any path; none left =
// the existing side-on rig fallback (g_s32_fb_req), requested here before a camera shows. t2r-ps41-cam-vis-old.txt (melee_spcam.c s41b_tick's cfg read).
#define S41V_T 1.0f               // s (at least the first second of the track)
#define S41V_MAX 0.5f             // [TUNING ps41]: the hidden part of those samples above which a candidate is rejected
static volatile int g_ps41v = 1;
