            if (!j) continue;
            g_xcam_rq[g_xcam_nrq].job = j; g_xcam_rq[g_xcam_nrq].cand = ci; g_xcam_rq[g_xcam_nrq].t = t; g_xcam_rq[g_xcam_nrq].rev = d;
            memcpy(g_xcam_rq[g_xcam_nrq].c, d ? E : C, 12); memcpy(g_xcam_rq[g_xcam_nrq].e, d ? C : E, 12);
