                if (f41) { g_s41_ssp_first = 0; xlog("xcam shiv: ps41 - the victim shot's side is CHOSEN before it shows: %.0f deg (both-faces score %.2f; the SP camera's own side was %.0f deg, %.0f deg away) - no walk round the pair on screen", by * 57.2957795f, bs, cy * 57.2957795f, d); }
                d = d > mx ? mx : d < -mx ? -mx : d;
