    float f[3] = {LT[0] - Cd[0], LT[1] - Cd[1], LT[2] - Cd[2]}, fl = __builtin_sqrtf(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);
    if (fl < 1e-3f) { f[0] = -bx; f[1] = -0.3f; f[2] = -bz; fl = __builtin_sqrtf(1.09f); }
    for (int i = 0; i < 3; i++) f[i] /= fl;
    if (!authored) { if (g_xcam_shivcine) xv_pitch_clamp_cine(f); else xv_pitch_clamp(f); }        // the safety clamp is for our own cameras only: authored shots keep their pitch
    float L[3] = {Cd[0] + f[0] * 2.0f, Cd[1] + f[1] * 2.0f, Cd[2] + f[2] * 2.0f};
