    uint8_t *v3 = me && !IsBadReadPtr(me + 0x2F60, 8) ? *(uint8_t **)(me + 0x2F60) : NULL;
    if (!v3 || IsBadReadPtr(v3, 0xC0)) { xlog("wpw: no weapon controller"); return; }
    wpw_hook_natives();
