    g_wpw_lbl[0] = "controller+0x70"; g_wpw_lbl[1] = "controller+0x78"; g_wpw_lbl[2] = "controller+0x90";
    InterlockedExchange(&g_wpw_ever, 1);              // before any DR is set: the handler owns every DR1-3 trap from now
    g_wpw_addr[0] = (uint64_t)(v3 + 0x70); g_wpw_addr[1] = (uint64_t)(v3 + 0x78); g_wpw_addr[2] = (uint64_t)(v3 + 0x90);
    {   // the long gun is re-attached to the back sling (attach sid leftHand -> targLongGunSlotOne 0x4b173a4b5b5958a5 at
        // +35, A log 12693) although every holster path is blocked: DR3 watches the weapon's attach point index instead of +0x90
        // (byte +0x28 of [proc+0x4b0], read by the attach getter 0x141cd4870) - the writer's stack names who slings it
        uint8_t *wp = player_weapon(me);
        uint8_t *ai = wp && !IsBadReadPtr(wp + 0x4B0, 8) ? *(uint8_t **)(wp + 0x4B0) : NULL;
        if (ai && !IsBadReadPtr(ai + 0x28, 8)) { g_wpw_addr[2] = (uint64_t)(ai + 0x28) & ~7ULL; g_wpw_lbl[2] = "gun attach index (+0x28 of [proc+0x4b0])"; }
    }
    g_wpw_until = g_frame + 600;
    xlog("wpw: controller %p handle %llx/%d override %llx/%d slot %d flag %d, weapon now %p", (void *)v3, (unsigned long long)*(uint64_t *)(v3 + 0x70),
         *(int32_t *)(v3 + 0x78), (unsigned long long)*(uint64_t *)(v3 + 0x90), *(int32_t *)(v3 + 0x98), *(int32_t *)(v3 + 0xA8), *(uint8_t *)(v3 + 0xB0),
         (void *)player_weapon(me));
    CloseHandle(CreateThread(NULL, 0, wpw_set_thread, NULL, 0, NULL));
