static void wpw_tick(void) {
    while (g_wpw_printed < g_wpw_n && g_wpw_printed < WPW_MAX) {
        LONG i = g_wpw_printed++;
        char w[64], line[700]; int k;
        mod_off(g_wpw_hits[i].rip, w, sizeof w);
        k = snprintf(line, sizeof line, "wpw: write to %s = %llx at %s frame %llu stack", g_wpw_lbl[g_wpw_hits[i].dr >= 0 && g_wpw_hits[i].dr < 3 ? g_wpw_hits[i].dr : 0],
                     (unsigned long long)g_wpw_hits[i].val, w, (unsigned long long)g_wpw_hits[i].frame);
        for (int j = 0; j < 8 && g_wpw_hits[i].stk[j]; j++) { mod_off(g_wpw_hits[i].stk[j], w, sizeof w); k += snprintf(line + k, SNLEFT(line, k), " %s", w); }
        xlog("%s", line);
    }
    if (g_wpw_addr[0] && g_frame > g_wpw_until) {
        g_wpw_addr[0] = g_wpw_addr[1] = g_wpw_addr[2] = 0;
        CloseHandle(CreateThread(NULL, 0, wpw_set_thread, NULL, 0, NULL));
    }
}
