static int hfix_hold_item_held(void);   // v5-stuck2: melee item or the female knife
static int hfix_hold_off(void);
static int mdu_fw_keep(void);           // melee_duel.c (v5-dis2: the duel's finisher windup - SP intro on us after cancel-melee-action)
