static int hfix_patch(uint32_t off, const uint8_t *expect, int n, void *hook, void **tramp, const char *what) {
    uint8_t *fn = (uint8_t *)GetModuleHandleW(NULL) + off;
    if (memcmp(fn, expect, n)) { hook_miss(fn, n, "holster fix: %s prologue mismatch, not installed", what); return 0; }
    uint8_t *t = VirtualAlloc(NULL, 64, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
    if (!t) return 0;
    memcpy(t, fn, n);
    t[n] = 0xFF; t[n + 1] = 0x25; *(uint32_t *)(t + n + 2) = 0;
    *(uint64_t *)(t + n + 6) = (uint64_t)(fn + n);
    *tramp = t;
    DWORD old; VirtualProtect(fn, n, PAGE_EXECUTE_READWRITE, &old);
    fn[0] = 0xFF; fn[1] = 0x25; *(uint32_t *)(fn + 2) = 0;
    *(uint64_t *)(fn + 6) = (uint64_t)hook;
    for (int i = 14; i < n; i++) fn[i] = 0x90;
    VirtualProtect(fn, n, old, &old);
    FlushInstructionCache(GetCurrentProcess(), fn, n);
    return 1;
}
