    int free_i = 0; uint64_t oldest = ~0ULL;
    for (int i = 0; i < 6; i++) {
        if (g_acen[i].proc == proc) { g_acen[i].until = g_frame + 600; return; }
        if (g_acen[i].until < oldest) { oldest = g_acen[i].until; free_i = i; }
    }
    g_acen[free_i].proc = proc; g_acen[free_i].last_sid = 0; g_acen[free_i].until = g_frame + 600;
