static void attach_census_tick(void) {
    typedef uint8_t *(*fn_me)(void);
    typedef uint64_t *(*fn_att)(void *proc, void *out);
    static const uint8_t pa[6] = {0x48, 0x89, 0x5C, 0x24, 0x08, 0x57};
    static uint64_t held_prev;
    static int logn;
    if (g_frame % 6 || logn > 600) return;
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    if (memcmp(exe + 0x1CD4870, pa, 6)) return;
    uint8_t *me = ((fn_me)VMA(0x180050390))();
    if (!me) return;
    uint8_t *hw = player_weapon(me);
    if ((uint64_t)hw != held_prev) { held_prev = (uint64_t)hw; acen_watch((uint64_t)hw); }
    for (int i = 0; i < 6; i++) {
        uint64_t p = g_acen[i].proc;
        if (!p || g_frame > g_acen[i].until || IsBadReadPtr((void *)(p + 0x4B0), 8)) continue;
        uint8_t buf[0x40] = {0};
        uint64_t *r = ((fn_att)(exe + 0x1CD4870))((void *)p, buf);
        uint64_t sid = r && !IsBadReadPtr(r, 8) ? *r : 0;
        if (sid == g_acen[i].last_sid) continue;
        g_acen[i].last_sid = sid; logn++;
        xlog("attach census: frame %llu weapon proc %llx%s attach sid %llx %s", (unsigned long long)g_frame, (unsigned long long)p,
             p == (uint64_t)hw ? " (held)" : " (stowed/other)", (unsigned long long)sid, bp_ap_name(sid));
    }
}
static void watt_trace(int k, uint64_t proc, uint64_t a5, uint64_t a6, uint64_t a2, uint64_t a3, uint64_t a4) {
    static volatile LONG n;
    if (n >= 400 || !a5 || IsBadReadPtr((void *)a5, 8)) return;
    typedef uint8_t *(*fn_me)(void);
    uint8_t *me = ((fn_me)VMA(0x180050390))();
    if (!me) return;
    uint8_t *op = tac_handle_proc((uint8_t *)a5);
    if (*(uint8_t **)a5 != me && op != me) return;
    acen_watch(proc);
    if (InterlockedIncrement(&n) > 400) return;
    void *bt[7]; USHORT m = RtlCaptureStackBackTrace(1, 7, bt, NULL);
    char line[480], w[64];
    int q = snprintf(line, sizeof line, "attach trace: #%d frame %llu weapon proc %llx%s ap %llx %s (a2 %llx a3 %llx a4 %llx) callers", k,
                     (unsigned long long)g_frame, (unsigned long long)proc, proc == (uint64_t)player_weapon(me) ? " (held)" : " (stowed/other)",
                     (unsigned long long)a6, bp_ap_name(a6), (unsigned long long)a2, (unsigned long long)a3, (unsigned long long)a4);
    // what puts the long gun on the back just BEFORE an execution - every attach carries the execution / holster-fix state
    // (hfix scope: 0 none 1 attacker 2 victim 3 downed; gx role / frames to its end; psync role; exec timer; downed)
    q += snprintf(line + q, SNLEFT(line, q), " [exec: hfix %d, gx role %d %lld, psync %d, exec_until %s, downed %d]", g_hfix_on ? hfix_scope() : -1,
                  g_gx.role, g_gx.until ? (long long)g_gx.until - (long long)g_t60 : 0LL, psync_role(), g_exec_until ? "on" : "off", g_downed);
    for (USHORT j = 0; j < m && q < (int)sizeof line - 40; j++) { mod_off((uint64_t)bt[j], w, sizeof w); q += snprintf(line + q, SNLEFT(line, q), " %s", w); }
    xlog("%s", line);
}
