    if (!*(const uint64_t *)handle_src) return 0;                       // no weapon process on the state
    uint8_t *obj = *(uint8_t **)(me + 0x2FC8);
    if (!obj || IsBadReadPtr(obj, 8)) return 0;
    void **vt = *(void ***)obj;
    if (!vt || IsBadReadPtr(vt + 0x38 / 8, 8) || vt[0x38 / 8] != (void *)(exe + 0xD893A0)) { hook_fail("holster fix: weapon anim control vtable differs, overlay state not changed"); return 0; }
