            bst[0] = 0x48; bst[1] = 0xB8; *(uint64_t *)(bst + 2) = (uint64_t)vzoom_blend_hook; bst[10] = 0xFF; bst[11] = 0xE0;
            VirtualProtect(bst, 0x1000, PAGE_EXECUTE_READ, &old);
            VirtualProtect(bs, 5, PAGE_EXECUTE_READWRITE, &old);
            *(int32_t *)(bs + 1) = (int32_t)(bst - (bs + 5));
            VirtualProtect(bs, 5, old, &old);
            FlushInstructionCache(GetCurrentProcess(), bs, 5);
