// Cut the line a character is saying. The beg should be cut off by the first shot, not the kill shot: every exec-beg cut logged
// 'stop-vox -> ffffffffffffffff' = dc_call found no callable native under that name in this game (it is a UC4 name), so the plea ran on
// through the grunts until the death shot. The first of these names that resolves to code here is used (picked once, logged).
static uint64_t vox_stop(uint64_t ent) {
    static const char *const names[] = {"stop-vox", "stop-speaking", "stop-speaking-interruptible", "stop-line"};
    static int pick = -2;
    if (pick == -2) {
        pick = -1;
        char b[160] = {0};
        for (int i = 0; i < (int)(sizeof names / sizeof *names); i++) {
            uint8_t *rec = (uint8_t *)((fn_lookup)VMA(0x18000A190))(fnv64_rt(names[i]));
            void *fn = rec ? *(void **)(rec + 8) : NULL;
            int ok = fn && is_code(fn);
            snprintf(b + strlen(b), sizeof b - strlen(b), "%s%s %s", i ? ", " : "", names[i], ok ? "yes" : "no");
            if (ok && pick < 0) pick = i;
        }
        xlog("vox stop: %s -> using %s", b, pick >= 0 ? names[pick] : "NONE (lines cannot be cut)");
    }
    if (pick < 0 || !ent) return ~0ULL;
    uint64_t a[1] = {ent};
    return dc_call(fnv64_rt(names[pick]), 1, a);
}
