    if (g_test_tp_frame && g_frame - g_test_tp_frame < 10) { if (job[0]) ray_t(job[0]); if (job[1]) ray_t(job[1]); prev_ok = 0; pend = 0; job[0] = job[1] = 0; return; }
    if (off < 0 || g_frame - chk > 120) { chk = g_frame ? g_frame : 1; off = GetFileAttributesA("t2r-no-pair-wall-stop.txt") != INVALID_FILE_ATTRIBUTES; }
