                cj[k] = 0;
                const char *why = "clear behind it";
                if (r >= 0.0f && r < 0.95f) {
                    float p[3] = {start[0] + (endp[0] - start[0]) * r, start[1] + h + (endp[1] - start[1]) * r, start[2] + (endp[2] - start[2]) * r};
                    float mx = p[0] - cl[0], mz = p[2] - cl[2];
                    int i2 = sg_body_at(p, sg_pos, sg_n, 0.60f);
                    if (mx * mx + mz * mz < 0.60f * 0.60f) why = "then our own body at the end spot (clear)";
                    else if (i2 >= 0 && i2 != cj_i[k]) why = "then another player's body (clear)";
                    else { res = r; why = "GEOMETRY behind it"; }
                }
                xlog("stuck guard: %s ray re-cast through the body: %s (t %.2f)", k ? "chest" : "knee", why, r);
