// ---------------------------------------------------------------- death view evidence
// Black screens: a recording of a player shiv-killed right after their own E execution, the picture went pure black in ONE
// frame at the kill (YAVG 39 -> 0.05), HUD gone, only winmm text left (teammate tag "ST" edge-pinned and drifting with an
// exponential ease = winmm's kill camera FUN_180039090 lerping toward the killer's peer camera), black to the clip end (4 s+).
// Not found statically; the candidates this logs per death (8 s, every 0.5 s):
//  a) winmm's kill / spectate camera (FUN_1800344e0 -> FUN_180039090(slot)) puts the render camera at the peer record's camera
//     (+0xa9 pos, +0xb5 quat; only inf-checked, never 0 / staleness) - a stale or zero camera of the killer = a camera in the void
//  b) the engine's death camera FUN_140b5d730 (Death Enter / ragdoll): kCameraNetDeath only if the net flag 0x144082fbb is set and the
//     death controller's comp+0x160 handle is an object of type [0x144122508]; otherwise kCameraExplosionDeath (or Vehicle) - our
//     withheld death anim (vdh_start) may change which one runs
//  c) our own render camera overrides (icam / xcam / mcam) still on
static void death_view_diag(void) {
#ifdef T2R_RELEASE
    return;                        // log-only diagnostic: dev builds only (perf: per-frame natives + log lines on the game thread)
#endif
    typedef uint8_t *(*fn_obj)(void);
    typedef uint8_t *(*fn_peer)(uint32_t);
    static int dead_was;
    static uint64_t t0, next;
    if (match_substate() != 6) { dead_was = 0; return; }
    uint8_t *me = vdf_player();
    float hp = local_hp();
    int dead = (hp > -0.5f && hp <= 0.0f) || vdf_state(me) == VDF_DEATH_STATE;
    if (dead && !dead_was) { t0 = g_frame; next = g_frame; }
    dead_was = dead;
    if (!dead || g_frame < next || g_frame - t0 > 480) return;
    uint64_t dt = g_frame - t0;
    next = g_frame + (dt < 30 ? 5 : 30);
    uint8_t *exe = (uint8_t *)GetModuleHandleW(NULL);
    char b[1200]; int n = 0;
    n += snprintf(b + n, SNLEFT(b, n), "death view +%llu: hp %.1f state %llx", (unsigned long long)dt, hp, (unsigned long long)vdf_state(me));
    {   uint64_t ps = SID_PLAYER, d = dc_call(0xe93f704f02a9ecd5ULL /* character-is-dead? */, 1, &ps);
        n += snprintf(b + n, SNLEFT(b, n), " engine-dead %llx", (unsigned long long)(d == ~0ULL ? d : (d & 0xff))); }
    float pb[16]; const float *pl = player_locator(pb);
    if (pl) n += snprintf(b + n, SNLEFT(b, n), " | us %.1f %.1f %.1f", pl[0], pl[1], pl[2]);
    {   float c[3], dd[3];
        if (cam_pos_dir(c, dd)) n += snprintf(b + n, SNLEFT(b, n), " | game cam %.1f %.1f %.1f dir %.2f %.2f %.2f", c[0], c[1], c[2], dd[0], dd[1], dd[2]); }
    uint8_t *o = ((fn_obj)VMA(0x18004BF70))();
    if (o) {
        int32_t kc = *(int32_t *)(o + 0x2c40), sp = *(int32_t *)(o + 0x2c4c);
        n += snprintf(b + n, SNLEFT(b, n), " | winmm killcam slot %d spectating %d (slot %d) on %d", kc, o[0x2c44], sp, *(volatile uint8_t *)VMA(0x180162914));
        const float *wp = (const float *)VMA(0x1801628a8), *wq = (const float *)VMA(0x1801628c0);
        n += snprintf(b + n, SNLEFT(b, n), " set %.1f %.1f %.1f q %.2f %.2f %.2f %.2f", wp[0], wp[1], wp[2], wq[0], wq[1], wq[2], wq[3]);
        for (int k = 0; k < 2; k++) {
            int s = k ? sp : kc;
            if (s < 0 || s > T2R_MAX_PEERS - 1 || (k && s == kc)) continue;
            uint8_t *peer = ((fn_peer)t2r_peer)((uint32_t)s);
            if (!peer) continue;
            float c[7]; memcpy(c, peer + 0xa9, sizeof c);
            n += snprintf(b + n, SNLEFT(b, n), " | peer %d cam %.1f %.1f %.1f q %.2f %.2f %.2f %.2f (ok %d alive %d dead %d)", s, c[0], c[1], c[2], c[3], c[4], c[5], c[6],
                          peer[0x9c6], peer[4], peer[5]);
        }
    }
    {   uint8_t *c = vdf_comp(me);
        int net = exe[0x4082fbb], f1 = exe[0x4103d6a], f2 = exe[0x4103d6c], pred = -1;
        if (c) {
            uint8_t *r = c + 0x160, *p = *(uint8_t **)(r + 0x10);
            uint32_t id = *(uint32_t *)(r + 0x18);
            pred = 0;
            if (p && id && !IsBadReadPtr(p + 8, 8)) {
                uint8_t *ob = *(uint8_t **)(p + 8);
                if (ob && !IsBadReadPtr(ob + 0x94, 4) && *(uint32_t *)(ob + 0x94) == id && !IsBadReadPtr(ob + 0x40, 8)) {
                    uint8_t *bits = *(uint8_t **)(ob + 0x40);
                    uint32_t ix = *(uint32_t *)(exe + 0x4122508);
                    if (bits && !IsBadReadPtr(bits + 0x28 + (ix >> 6) * 8, 8)) pred = (int)((*(uint64_t *)(bits + 0x28 + (ix >> 6) * 8) >> (ix & 63)) & 1) + 1;
                }
            }
            n += snprintf(b + n, SNLEFT(b, n), " | death ctl +0x141 %d +0x13c %d", c[0x141], c[0x13c]);
        }
        n += snprintf(b + n, SNLEFT(b, n), " death cam: net %d flags %d %d handle %s -> %s", net, f1, f2, pred < 0 ? "?" : pred == 0 ? "none" : pred == 1 ? "other type" : "net type",
                      f2 ? "Vehicle" : !net ? "Explosion" : pred == 2 ? "NetDeath" : "Explosion (no net-type handle)");
    }
    n += snprintf(b + n, SNLEFT(b, n), " | ours: intro cam %d exec cam %d menu cam %d/%d", g_icam_on, g_xcam_on, g_mcam_watch, g_mcam_on);
    xlog("%s", b);
}
