    PF(feature_puppet_anim());
    PF(feel_tick());
    PF(mdg_tick());                                // melee_dodge.c: dodge gate / window / limits (t2r-no-melee-dodge.txt = off)
    PF(mo_tick());                                 // motion.c: closes the frame's write records, per-match summary (t2r-motion-cap.txt = speed cap, default off)
    PF(mhstun_tick());                             // melee_stagger.c: the interrupt of a landed melee blow (t2r-no-melee-hitstun.txt = off)
    PF(bloodbuild_tick());
    PF(mpsnow_tick());                             // mpsnow.c: snow strength on the winter map (only in builds with the snow garment)
    PF(mpsnow_hood_tick());                        // mpsnow.c: winter Seraphites wear the hood up (T2R_MP_SNOW=1 builds)
